import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final Pattern CSRF_JSON_PATTERN =
        Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"");

    {
        String baseUrl = System.getenv("BASE_URL") != null
            ? System.getenv("BASE_URL")
            : "http://127.0.0.1:8000";

        HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableAutoRedirect()
            .userAgentHeader("gatling-shop-flow");

        ChainBuilder flow = exec(session -> session
                .remove("csrf")
                .remove("cartId")
                .remove("etag")
                .remove("idem")
                .remove("loginLocation")
                .remove("loginStatus")
                .remove("loginBody")
                .remove("followBody")
                .remove("patchStatus")
                .remove("patchCsrf")
                .remove("patchEtag")
