class CsrfParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden_csrf = None
        self.named_csrf = None

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "input":
            return
        d = {k.lower(): v for k, v in attrs}
        if d.get("name") != "csrf":
            return
        val = d.get("value", "")
        typ = d.get("type", "").lower()
        if typ == "hidden":
            if self.hidden_csrf is None:
                self.hidden_csrf = val
        elif self.named_csrf is None:
            self.named_csrf = val


def extract_csrf(html):
    parser = CsrfParser()
    parser.feed(html)
    return parser.hidden_csrf or parser.named_csrf


class ChallengeParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.action = None
        self.challenge = None

    def handle_starttag(self, tag, attrs):
        d = {k.lower(): v for k, v in attrs}
        if tag.lower() == "form" and self.action is None:
