                    etag = resp.headers.get("ETag") or resp.headers.get("Etag")
                    if etag:
                        self.etag = etag
                    return True

                if resp.status_code == 412:
                    if retried_412:
                        resp.failure("PATCH 412 after retry")
                        return False
                    retried_412 = True
                    resp.success()
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return False
                    self.etag = new_etag
                    continue

                if resp.status_code == 401:
                    err = self._parse_401(resp)
                    if err == "denied" or recovered_401:
                        resp.failure(f"PATCH 401 {err}")
                        return False
                    recovered_401 = True
                    resp.success()
                    if not self._recover_401(err, cart_id):
                        return False
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return False
                    self.etag = new_etag
                    continue

                resp.failure(f"PATCH status {resp.status_code}")
                return False

        return False

    def create_reservation(self, cart_id):
        status, headers, body = self._authed_json_request(
            "POST",
            "/v2/reservations",
            json_body={"cart_id": cart_id},
            expected={202},
            cart_id=cart_id,
            operation="reservation",
        )
        if status != 202 or not isinstance(body, dict):
            return None

        status_url = body.get("status_url")
        if not status_url:
            return None

        return self.poll_reservation(status_url)

    def poll_reservation(self, status_url):
        url = urljoin(BASE_URL, status_url)
        for attempt in range(5):
            if attempt > 0:
                time.sleep(0.05)
            with self.client.get(url, allow_redirects=False, catch_response=True) as resp:
                if resp.status_code != 200:
                    resp.failure(f"reservation poll status {resp.status_code}")
                    return None
                body = self._json_or_none(resp)
                self._update_csrf_from_body(body)
                if not isinstance(body, dict):
                    resp.failure("reservation poll invalid json")
                    return None

                status = body.get("status")
                if status == "ready":
                    reservation_id = body.get("reservation_id")
                    if reservation_id:
                        return reservation_id
                    resp.failure("reservation ready missing reservation_id")
                    return None

                if status in ("pending", "failed"):
                    continue

                resp.failure(f"reservation unknown status {status}")
                return None

        return None

    def do_work_or_browse(self):
        recovered_401 = False
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 200:
                    body = self._json_or_none(resp)
                    self._update_csrf_from_body(body)
                    return True

                if resp.status_code == 429:
                    if attempt >= 4:
                        resp.failure("work 429 after max retries")
                        return False
                    time.sleep(1)
                    continue

                if resp.status_code == 401:
                    err = self._parse_401(resp)
                    if err == "denied" or recovered_401:
                        resp.failure(f"work 401 {err}")
                        return False
                    recovered_401 = True
                    resp.success()
                    if not self._recover_401(err, self.cart_id):
                        return False
                    continue

                resp.failure(f"work status {resp.status_code}")
                return False

        return False

    def create_order(self, cart_id, reservation_id):
        payload = {"cart_id": cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        if not self.idem_key:
            self.idem_key = f"order-{cart_id}-{self.__class__.__name__}"

        recovered_401 = False
        retried_412 = False

        for _ in range(3):
            headers = {
                "Idempotency-Key": self.idem_key,
                "X-CSRF-Token": self.csrf,
            }
            if self.etag:
                headers["If-Match"] = self.etag

            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 201:
                    body = self._json_or_none(resp)
                    if isinstance(body, dict) and body.get("accepted") is True and body.get("id"):
                        self._update_csrf_from_body(body)
                        return body.get("id")
                    resp.failure("orders 201 missing accepted/id")
                    return None

                if resp.status_code == 200:
                    body = self._json_or_none(resp)
                    if isinstance(body, dict) and body.get("accepted") is False:
                        resp.failure("orders 200 accepted:false business failure")
                    else:
                        resp.failure("orders 200 unexpected")
                    return None

                if resp.status_code == 401:
                    err = self._parse_401(resp)
                    if err == "denied" or recovered_401:
                        resp.failure(f"orders 401 {err}")
                        return None
                    recovered_401 = True
                    resp.success()
                    if not self._recover_401(err, cart_id):
                        return None
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return None
                    self.etag = new_etag
                    continue

                if resp.status_code == 412:
                    if retried_412:
                        resp.failure("orders 412 after retry")
                        return None
                    retried_412 = True
                    resp.success()
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return None
                    self.etag = new_etag
                    continue

                resp.failure(f"orders status {resp.status_code}")
                return None

        return None

    def run_journey(self):
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None

        if not self._fresh_login():
            return

        product_id, variant_id = self.select_product()
        if not product_id:
            return

        self.grant_id = self._obtain_challenge()

        cart_id, etag = self.create_cart(product_id, variant_id, self.grant_id)
        if not cart_id:
            return
        self.cart_id = cart_id
        self.etag = etag

        new_etag = self.get_cart_etag(cart_id)
        if not new_etag:
            return
        self.etag = new_etag

        if not self.patch_cart(cart_id, 1):
            return

        new_etag = self.get_cart_etag(cart_id)
        if not new_etag:
            return
        self.etag = new_etag

        self.do_work_or_browse()

        self.reservation_id = self.create_reservation(cart_id)

        new_etag = self.get_cart_etag(cart_id)
        if new_etag:
            self.etag = new_etag

        self.create_order(cart_id, self.reservation_id)


