        http.baseUrl(System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000")
            .disableFollowRedirect()
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .header("User-Agent", "gatling-model");

    private ChainBuilder applyFreshCsrf = exec(session -> {
        String fresh = session.getString("freshCsrf");
        if (fresh != null && !fresh.isEmpty()) {
            return session.set("csrf", fresh).remove("freshCsrf");
        }
        return session.remove("freshCsrf");
    });

