        .check(css("input[name=challenge]", "value").saveAs("challengeValue"))
    );

    private ChainBuilder postChallenge = exec(http("POST challenge action")
        .post(session -> session.getString("challengeAction"))
        .header("X-CSRF-Token", "#{csrf}")
        .body(StringBody("{\"challenge\":\"#{challengeValue}\"}"))
        .check(status().in(200, 201, 302).saveAs("challengeStatus"))
