        .check(jsonPath("$.csrf").optional().saveAs("freshCsrf"))
    )
    .exec(applyFreshCsrf)
    .exec(session -> session.set("reservationPollCount", 0).set("reservationStatus", "pending").set("reservationId", null))
    .asLongAs(session -> session.getInt("reservationPollCount") < 5 && !"ready".equals(session.getString("reservationStatus")))
    .on(
        pause(50).milliseconds()
