        .exitHereIfFailed()
        .exec(applyFreshCsrf)
        .exec(session -> session.set("reservationPollCount", session.getInt("reservationPollCount") + 1))
    )
    .exec(session -> {
        if (!"ready".equals(session.getString("reservationStatus")) ||
            session.getString("reservationId") == null ||
            session.getString("reservationId").isEmpty()) {
            throw new RuntimeException("reservation not ready after polling");
        }
        return session;
    });

    private ChainBuilder order = exec(http("POST /v2/orders")
        .post("/v2/orders")
        .header("X-CSRF-Token", "#{csrf}")
        .header("Idempotency-Key", "#{idempotencyKey}")
        .header("If-Match", "#{cartEtag}")
        .body(StringBody("{\"cart_id\":\"#{cartId}\",\"reservation_id\":\"#{reservationId}\"}"))
        .check(status().is(201))
        .check(jsonPath("$.accepted").ofBoolean().is(true))
        .check(jsonPath("$.id").optional().saveAs("orderId"))
        .check(jsonPath("$.csrf").optional().saveAs("freshCsrf"))
    )
    .exec(applyFreshCsrf);

    private ChainBuilder work = exec(session -> session.set("workRetryCount", 0))
        .asLongAs(session -> session.getInt("workRetryCount") <= 4 && session.getInt("workStatusCode") != 200)
        .on(
            exec(http("POST /v2/work")
                .post("/v2/work")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(status().in(200, 429).saveAs("workStatusCode"))
            )
            .exitHereIfFailed()
            .doIf(session -> session.getInt("workStatusCode") != null && session.getInt("workStatusCode") == 429)
            .on(pause(1).seconds())
            .exec(session -> session.set("workRetryCount", session.getInt("workRetryCount") + 1))
        );

    private ChainBuilder journey = exec(session -> {
        long uid = session.userId();
        int idx = (int) ((uid - 1) % 16) + 1;
        return session.set("username", "bench-" + idx)
                      .set("idempotencyKey", UUID.randomUUID().toString());
    })
        .exec(loginForm).exitHereIfFailed()
        .exec(loginPost).exitHereIfFailed()
        .exec(catalog).exitHereIfFailed()
        .exec(challengeForm).exitHereIfFailed()
        .exec(postChallenge).exitHereIfFailed()
        .exec(createCart).exitHereIfFailed()
        .exec(patchCart).exitHereIfFailed()
        .exec(reserve).exitHereIfFailed()
        .exec(order).exitHereIfFailed()
        .exec(work);

    {
        ScenarioBuilder scn = scenario("ModelScenario")
            .exec(repeat(2).on(journey));

        setUp(
            scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}
