function parseTagAttributes(tag) {
  const attrs = {};
  let inner = tag.replace(/^<\s*[a-zA-Z0-9_-]+\s*/i, '').replace(/\s*\/?\s*>$/, '');
  const len = inner.length;
  let i = 0;
  while (i < len) {
    while (i < len && /\s/.test(inner[i])) i++;
    if (i >= len) break;
    const start = i;
    while (i < len && !/[\s=]/.test(inner[i])) i++;
    const attrName = inner.slice(start, i).toLowerCase();
    if (!attrName) break;
    while (i < len && /\s/.test(inner[i])) i++;
    let value = true;
    if (i < len && inner[i] === '=') {
      i++;
      while (i < len && /\s/.test(inner[i])) i++;
      if (i < len && (inner[i] === '"' || inner[i] === "'")) {
        const quote = inner[i];
        i++;
        const valStart = i;
        while (i < len && inner[i] !== quote) i++;
        value = inner.slice(valStart, i);
        if (i < len) i++;
      } else {
        const valStart = i;
        while (i < len && !/\s/.test(inner[i])) i++;
        value = inner.slice(valStart, i);
      }
    }
    attrs[attrName] = value;
  }
  return attrs;
}

function extractCsrf(html) {
  const tags = findInputTags(html);
  const candidates = [];
  for (const tag of tags) {
    const attrs = parseTagAttributes(tag);
    if (attrs.name === 'csrf') {
      candidates.push({
        value: typeof attrs.value === 'string' ? attrs.value : '',
        disabled: attrs.disabled !== undefined,
      });
    }
  }

  if (candidates.length === 0) {
    throw new Error('CSRF input not found');
  }

  const nonDisabledNonEmpty = candidates.filter(c => !c.disabled && c.value.length > 0);
  if (nonDisabledNonEmpty.length > 0) return nonDisabledNonEmpty[0].value;

  const nonDisabled = candidates.filter(c => !c.disabled);
  if (nonDisabled.length > 0) return nonDisabled[0].value;

  return candidates[0].value;
}

function extractFormAction(html) {
  const forms = findFormTags(html);
  if (forms.length === 0) return null;
  const attrs = parseTagAttributes(forms[0]);
  return typeof attrs.action === 'string' ? attrs.action : null;
}

function extractChallengeValue(html) {
  const tags = findInputTags(html);
  for (const tag of tags) {
    const attrs = parseTagAttributes(tag);
    if (attrs.name === 'challenge') {
      return typeof attrs.value === 'string' ? attrs.value : '';
    }
  }
  return null;
}

export default function () {
  const account = `bench-${((__VU - 1) % 2) + 1}`;
  const password = 'bench';
  let csrf = '';
  let cartId = null;
  let cartEtag = null;
  let idempotencyKey = null;
  let grantId = null;

  function performLoginAndRecover() {
    const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
    if (formRes.status !== 200) {
      throw new Error(`Fresh login form status=${formRes.status}`);
    }
    const freshCsrf = extractCsrf(formRes.body);

    let loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
      username: account,
      password: password,
      csrf: freshCsrf,
    }), {
      redirects: 0,
      headers: { 'Content-Type': 'application/json' },
    });

    if (loginRes.status === 302) {
      const loc = getHeader(loginRes, 'Location');
      if (!loc) throw new Error('Fresh login 302 missing Location');
      const locRes = http.get(resolveUrl(loc), { redirects: 0 });
      if (locRes.status !== 200) throw new Error(`Fresh login redirect status=${locRes.status}`);
      const body = parseJson(locRes);
      if (body.csrf) csrf = body.csrf;
    } else if (loginRes.status === 200) {
      const body = parseJson(loginRes);
      if (body.csrf) csrf = body.csrf;
    } else {
      throw new Error(`Fresh login failed status=${loginRes.status}`);
    }

    if (cartId) {
      const recRes = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), jsonParams(csrf));
      if (recRes.status === 200 || recRes.status === 201) {
        const body = parseJson(recRes);
        if (body.csrf) csrf = body.csrf;
      } else if (recRes.status === 404) {
        throw new Error('Cart not found during fresh recovery');
      } else if (recRes.status === 401) {
        throw new Error('Fresh recovery returned 401');
      } else {
        throw new Error(`Fresh recovery failed status=${recRes.status}`);
      }
    }
  }

  function recoverSession(res) {
    let errorCode = null;
    try {
      const body = res.json();
      errorCode = body.error;
    } catch (e) {
      // ignore parse failures
    }

    if (errorCode === 'denied') {
      throw new Error('401 denied is not recoverable');
    }

    if (errorCode === 'expired') {
      const renewRes = http.post(`${BASE}/v2/session/renew`, JSON.stringify({}), jsonParams(csrf));
      if (renewRes.status === 200 || renewRes.status === 201) {
        const body = parseJson(renewRes);
        if (body.csrf) csrf = body.csrf;
      } else if (renewRes.status === 401) {
        performLoginAndRecover();
        return;
      } else {
        throw new Error(`Renew failed status=${renewRes.status}`);
      }

      if (cartId) {
        const recRes = http.post(`${BASE}/v2/carts/${cartId}/recover`, JSON.stringify({}), jsonParams(csrf));
        if (recRes.status === 200 || recRes.status === 201) {
          const body = parseJson(recRes);
          if (body.csrf) csrf = body.csrf;
        } else if (recRes.status === 404) {
          throw new Error('Cart not found during recovery');
        } else if (recRes.status === 401) {
          performLoginAndRecover();
          return;
        } else {
          throw new Error(`Recover cart failed status=${recRes.status}`);
        }
      }
    } else {
      performLoginAndRecover();
    }
  }

  function solveChallenge() {
    let formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
    if (formRes.status === 401) {
      recoverSession(formRes);
      formRes = http.get(`${BASE}/v2/challenge-form`, { redirects: 0 });
    }
    if (formRes.status !== 200) return null;

    const action = extractFormAction(formRes.body);
    const challenge = extractChallengeValue(formRes.body);
    if (!action || challenge === null) return null;

    const actionUrl = resolveUrl(action);
    let postRes = http.post(actionUrl, JSON.stringify({ challenge: challenge }), jsonParams(csrf));
    if (postRes.status === 401) {
      recoverSession(postRes);
      postRes = http.post(actionUrl, JSON.stringify({ challenge: challenge }), jsonParams(csrf));
    }
    if (postRes.status !== 302) return null;

    const loc = getHeader(postRes, 'Location');
    if (!loc) return null;

    let locRes = http.get(resolveUrl(loc), { redirects: 0 });
    if (locRes.status === 401) {
      recoverSession(locRes);
      locRes = http.get(resolveUrl(loc), { redirects: 0 });
    }
    if (locRes.status !== 200) return null;

    const body = parseJson(locRes);
    if (body.csrf) csrf = body.csrf;
    return body.grant_id || null;
  }

  function chooseProduct() {
    const maxPages = 3;
    let pagesSeen = 0;
    let url = `${BASE}/v2/catalog`;

    while (url && pagesSeen < maxPages) {
      const res = http.get(url, { redirects: 0 });
      if (res.status !== 200) break;
      const body = parseJson(res);
      if (body.data && Array.isArray(body.data.products)) {
        for (const p of body.data.products) {
          for (const v of p.variants) {
            if (v.in_stock) {
              return { product_id: p.id, variant_id: v.id };
            }
          }
        }
      }
      pagesSeen++;
      if (body.next) {
        url = resolveUrl(body.next);
      } else {
        url = null;
      }
    }

    pagesSeen = 0;
    url = `${BASE}/v2/catalog/page`;
    while (url && pagesSeen < maxPages) {
      const res = http.get(url, { redirects: 0 });
      if (res.status !== 200) break;
      const body = parseJson(res);
      if (body.data && Array.isArray(body.data.products)) {
        for (const p of body.data.products) {
          for (const v of p.variants) {
            if (v.in_stock) {
              return { product_id: p.id, variant_id: v.id };
            }
          }
        }
      }
      pagesSeen++;
      if (body.next) {
        url = resolveUrl(body.next);
      } else {
        url = null;
      }
    }

    throw new Error('No in-stock product found in catalog');
  }

  function createCartOp(product_id, variant_id) {
    const body = { product_id: product_id, variant_id: variant_id };
    if (grantId) body.grant_id = grantId;

    let res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), jsonParams(csrf));
    if (res.status === 401) {
      recoverSession(res);
      res = http.post(`${BASE}/v2/carts`, JSON.stringify(body), jsonParams(csrf));
    }

    if (res.status !== 201) {
      throw new Error(`Create cart failed status=${res.status} body=${String(res.body || '').slice(0, 200)}`);
    }

    const b = parseJson(res);
    cartId = b.id;
    if (b.csrf) csrf = b.csrf;
    cartEtag = getHeader(res, 'ETag') || null;
    idempotencyKey = `idem-${cartId}-${__VU}-${__ITER}-${Date.now()}`;
  }

  function patchCartOp() {
    const quantity = 1;
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    };
    if (cartEtag) headers['If-Match'] = cartEtag;

    let res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
      redirects: 0,
      headers: headers,
    });

    if (res.status === 401) {
      recoverSession(res);
      const cartRes = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
      if (cartRes.status === 200) {
        cartEtag = getHeader(cartRes, 'ETag') || cartEtag;
      }
      headers['X-CSRF-Token'] = csrf;
      if (cartEtag) headers['If-Match'] = cartEtag;
      res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
        redirects: 0,
        headers: headers,
      });
    }

    if (res.status === 412) {
      const cartRes = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
      if (cartRes.status === 200) {
        cartEtag = getHeader(cartRes, 'ETag') || cartEtag;
      }
      headers['X-CSRF-Token'] = csrf;
      if (cartEtag) headers['If-Match'] = cartEtag;
      res = http.patch(`${BASE}/v2/carts/${cartId}`, JSON.stringify({ quantity: quantity }), {
        redirects: 0,
        headers: headers,
      });
    }

    if (res.status !== 200 && res.status !== 204) {
      throw new Error(`Patch failed status=${res.status} body=${String(res.body || '').slice(0, 200)}`);
    }

    const etag = getHeader(res, 'ETag');
    if (etag) cartEtag = etag;

    try {
      const b = parseJson(res);
      if (b.csrf) csrf = b.csrf;
    } catch (e) {
      // empty patch response body is acceptable
    }
  }

  function createReservationOp() {
    let res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), jsonParams(csrf));
    if (res.status === 401) {
      recoverSession(res);
      res = http.post(`${BASE}/v2/reservations`, JSON.stringify({ cart_id: cartId }), jsonParams(csrf));
    }
    if (res.status !== 202) return null;

    const body = parseJson(res);
    if (body.csrf) csrf = body.csrf;
    const statusUrl = body.status_url;
    if (!statusUrl) return null;

    let reservationId = null;
    for (let i = 0; i < 5; i++) {
      sleep(0.06);
      let stRes = http.get(resolveUrl(statusUrl), { redirects: 0 });
      if (stRes.status === 401) {
        recoverSession(stRes);
        stRes = http.get(resolveUrl(statusUrl), { redirects: 0 });
      }
      if (stRes.status === 200) {
        const stBody = parseJson(stRes);
        if (stBody.status === 'ready' && stBody.reservation_id) {
          reservationId = stBody.reservation_id;
          if (stBody.csrf) csrf = stBody.csrf;
          break;
        }
      }
    }
    return reservationId;
  }

  function createOrderOp(reservationId) {
    const body = { cart_id: cartId };
    if (reservationId) body.reservation_id = reservationId;

    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': idempotencyKey,
    };
    if (cartEtag) headers['If-Match'] = cartEtag;

    let res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), {
      redirects: 0,
      headers: headers,
    });

    if (res.status === 401) {
      recoverSession(res);
      const cartRes = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
      if (cartRes.status === 200) {
        cartEtag = getHeader(cartRes, 'ETag') || cartEtag;
      }
      headers['X-CSRF-Token'] = csrf;
      headers['Idempotency-Key'] = idempotencyKey;
      if (cartEtag) headers['If-Match'] = cartEtag;
      res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), {
        redirects: 0,
        headers: headers,
      });
    }

    if (res.status === 412) {
      const cartRes = http.get(`${BASE}/v2/carts/${cartId}`, { redirects: 0 });
      if (cartRes.status === 200) {
        cartEtag = getHeader(cartRes, 'ETag') || cartEtag;
      }
      headers['X-CSRF-Token'] = csrf;
      headers['Idempotency-Key'] = idempotencyKey;
      if (cartEtag) headers['If-Match'] = cartEtag;
      res = http.post(`${BASE}/v2/orders`, JSON.stringify(body), {
        redirects: 0,
        headers: headers,
      });
    }

    if (res.status === 201) {
      const b = parseJson(res);
      if (b.accepted !== true) {
        throw new Error(`Order not accepted body=${String(res.body || '').slice(0, 200)}`);
      }
      if (b.csrf) csrf = b.csrf;
    } else if (res.status === 200) {
      const b = parseJson(res);
      if (b.accepted === false) {
        throw new Error('Order accepted:false business failure');
      }
    } else {
      throw new Error(`Order failed status=${res.status} body=${String(res.body || '').slice(0, 200)}`);
    }
  }

  function recordWork(res) {
    let failure = 1;
    try {
      if (res.status === 429) {
        failure = 0;
      } else if (res.status >= 200 && res.status < 300) {
        const b = res.json();
        if (b && b.ok === true) failure = 0;
      } else if (res.status === 401) {
        let b = null;
        try { b = res.json(); } catch (e) {}
        if (b && b.error === 'expired') failure = 0;
      }
    } catch (e) {
      // remain failure
    }
    businessFailure.add(failure);
  }

  function postWorkOp() {
    const payload = JSON.stringify({});
    let res = http.post(`${BASE}/v2/work`, payload, jsonParams(csrf));
    recordWork(res);

    if (res.status === 429) {
      let retries = 0;
      while (res.status === 429 && retries < 4) {
        sleep(1);
        res = http.post(`${BASE}/v2/work`, payload, jsonParams(csrf));
        recordWork(res);
        retries++;
      }
    }

    if (res.status === 401) {
      recoverSession(res);
      res = http.post(`${BASE}/v2/work`, payload, jsonParams(csrf));
      recordWork(res);
    }

    if (res.status !== 200) {
      throw new Error(`Work failed status=${res.status} body=${String(res.body || '').slice(0, 200)}`);
    }

    const body = parseJson(res);
    if (body.ok !== true) {
      throw new Error(`Work not ok body=${String(res.body || '').slice(0, 200)}`);
    }
  }

  const loginFormRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  if (loginFormRes.status !== 200) {
    throw new Error(`Login form status=${loginFormRes.status}`);
  }
  csrf = extractCsrf(loginFormRes.body);

  let loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: account,
    password: password,
    csrf: csrf,
  }), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
  });

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    if (!loc) throw new Error('Login 302 missing Location');
    const locRes = http.get(resolveUrl(loc), { redirects: 0 });
    if (locRes.status !== 200) throw new Error(`Login redirect status=${locRes.status}`);
    const body = parseJson(locRes);
    if (body.csrf) csrf = body.csrf;
  } else if (loginRes.status === 200) {
    const body = parseJson(loginRes);
    if (body.csrf) csrf = body.csrf;
  } else {
    throw new Error(`Login failed status=${loginRes.status}`);
  }

  const product = chooseProduct();

  grantId = solveChallenge();

  createCartOp(product.product_id, product.variant_id);

  patchCartOp();

  const reservationId = createReservationOp();

  createOrderOp(reservationId);

  postWorkOp();
}

