import os
import time
import uuid
from html.parser import HTMLParser

from locust import HttpUser, LoadTestShape, StopUser, constant, task


class _FormParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms = []
        self.inputs = []

    def handle_starttag(self, tag, attrs):
        if tag == "form":
            self.forms.append(dict(attrs))
        elif tag == "input":
            self.inputs.append(dict(attrs))


class FlowShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.spawned = False

    def tick(self):
        current = self.runner.user_count

        if not self.spawned:
            if current == 0:
                return (2, 2)
            self.spawned = True
            return (current, current)

        if current == 0:
            return None

        return (current, current)


class ShopUser(HttpUser):
    wait_time = constant(0)
    account_counter = 0

    def on_start(self):
        ShopUser.account_counter += 1
        self.username = f"bench-{((ShopUser.account_counter - 1) % 16) + 1}"
        self._journey_count = 0

    @task
    def do_journey(self):
        self._journey_count += 1
        self._run_journey()
        if self._journey_count >= 2:
            raise StopUser()

    # ---------- low-level helpers ----------

    def _json_safe(self, resp):
        try:
            return resp.json()
        except Exception:
            return None

    def _auth_error(self, resp):
        data = self._json_safe(resp)
        if isinstance(data, dict):
            return data.get("error")
        return None

    def _parse_html(self, html):
        parser = _FormParser()
        parser.feed(html)
        return parser.forms, parser.inputs

    def _extract_csrf(self, html):
        _, inputs = self._parse_html(html)
        for inp in inputs:
            if inp.get("name") == "csrf":
                return inp.get("value")
        return None

    def _extract_challenge(self, html):
        forms, inputs = self._parse_html(html)
        action = None
        challenge = None

        for form in forms:
            if form.get("action") and "/v2/challenges/" in form["action"]:
                action = form["action"]
                break

        for inp in inputs:
            if inp.get("name") == "challenge":
                challenge = inp.get("value")
                break

        return action, challenge

    def _mark_all_success(self, responses):
        for resp, _ in responses:
            resp.success()

    # ---------- session / cart recovery ----------

    def _renew_session(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        resp = self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        )

        if resp.status_code == 200:
            data = self._json_safe(resp)
            if data and "csrf" in data:
                self.csrf = data["csrf"]
            resp.success()
            return True

        resp.failure(f"session renew status {resp.status_code}: {resp.text[:200]}")
        return False

    def _recover_cart_if_exists(self):
        if not self.cart_id:
            return True

        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf

        resp = self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        )

        if resp.status_code == 200:
            data = self._json_safe(resp)
            if data and "csrf" in data:
                self.csrf = data["csrf"]
            resp.success()
            return True

        resp.failure(f"cart recover status {resp.status_code}: {resp.text[:200]}")
        return False

    def _fresh_login_recover(self):
        if not self._login():
            return False
        return self._recover_cart_if_exists()

    # ---------- auth / login ----------

    def _login(self):
        # 1) get login form and CSRF
        with self.client.get(
            "/v2/login-form", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}: {resp.text[:200]}")
                return False

            token = self._extract_csrf(resp.text)
            if token is None:
                resp.failure("login-form missing input[name=csrf]")
                return False

            resp.success()

        # 2) submit login
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": token},
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = self._json_safe(resp)
                self.csrf = data.get("csrf", token) if data else token
                resp.success()
                return True

            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login returned 302 without Location")
                    return False
                resp.success()

                with self.client.get(
                    location, allow_redirects=False, catch_response=True
                ) as resp2:
                    if resp2.status_code != 200:
                        resp2.failure(
                            f"login Location GET status {resp2.status_code}: {resp2.text[:200]}"
                        )
                        return False

                    data = self._json_safe(resp2)
                    self.csrf = data.get("csrf", token) if data else token
                    resp2.success()
                    return True

            resp.failure(f"login status {resp.status_code}: {resp.text[:200]}")
            return False

    # ---------- generic authenticated JSON POST with recovery ----------

    def _post_json(
        self,
        url,
        json_body,
        expected_status=(200, 201, 202),
        operation_name="POST",
        validate=None,
    ):
        retries_left = 1

        while True:
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            resp = self.client.post(
                url,
                json=json_body,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            )

            if resp.status_code in expected_status:
                data = self._json_safe(resp)

                if validate:
                    ok, reason = validate(resp, data)
                    if not ok:
                        resp.failure(f"{operation_name} {url} validation failed: {reason}")
                        return None

                resp.success()
                return resp

            if resp.status_code == 401:
                err = self._auth_error(resp)

                if err == "expired":
                    resp.success()
                    if retries_left > 0:
                        if self._renew_session():
                            self._recover_cart_if_exists()
                            retries_left -= 1
                            continue
                        return None
                    return None

                if err == "session":
                    resp.success()
                    if retries_left > 0:
                        if self._fresh_login_recover():
                            self._recover_cart_if_exists()
                            retries_left -= 1
                            continue
                        return None
                    return None

                if err == "denied":
                    resp.failure("denied")
