        if not getattr(self, "_idempotency_key", None):
            self._idempotency_key = uuid.uuid4().hex
        headers["Idempotency-Key"] = self._idempotency_key

        def validate_order(resp, data):
            return isinstance(data, dict) and data.get("accepted") is True

        resp = self._post_json(
            "/v2/orders",
            body,
            expected_status=(200, 201),
            operation_name="order",
            validate=validate_order,
            extra_headers=headers,
        )
        if resp is None:
            return False

        data = self._json_safe(resp)
        if isinstance(data, dict) and "csrf" in data:
            self.csrf = data["csrf"]

        etag = resp.headers.get("ETag")
        if etag:
            self.cart_etag = etag

        return True

    # ---------- post-checkout work ----------

    def _do_work(self):
        scheduled_retries = 4
        retries_401 = 1

        while True:
            headers = {}
            if self.csrf:
                headers["X-CSRF-Token"] = self.csrf

            resp = self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            )

            if resp.status_code == 200:
                data = self._json_safe(resp)
                if isinstance(data, dict) and data.get("ok") is True:
                    resp.success()
                    return True

                resp.failure("work response not ok")
                return False

            if resp.status_code == 429:
                resp.success()

                if scheduled_retries > 0:
                    scheduled_retries -= 1
                    retry_after = resp.headers.get("Retry-After")
                    try:
                        sleep_for = float(retry_after) if retry_after else 1.0
                    except Exception:
                        sleep_for = 1.0

                    if sleep_for < 1.0:
                        sleep_for = 1.0

                    time.sleep(sleep_for)
                    continue

                return True

            if resp.status_code == 401:
                err = self._auth_error(resp)

                if err == "expired":
                    resp.success()
                    if retries_401 > 0:
                        if self._renew_session():
                            self._recover_cart_if_exists()
                            retries_401 -= 1
                            continue
                        return False
                    resp.failure("work expired retry exhausted")
                    return False

                if err == "session":
                    resp.success()
                    if retries_401 > 0:
                        if self._fresh_login_recover():
                            self._recover_cart_if_exists()
                            retries_401 -= 1
                            continue
                        return False
                    resp.failure("work session retry exhausted")
                    return False

                if err == "denied":
                    resp.failure("denied")
                    return False

                resp.failure(f"work 401 error={err}: {resp.text[:200]}")
                return False

            resp.failure(f"work status {resp.status_code}: {resp.text[:200]}")
            return False

    # ---------- journey ----------

    def _run_journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.product_id = None
        self.variant_id = None
        self.grant_id = None
        self.reservation_id = None
        self._idempotency_key = None
        self._reservation_status_url = None

        if not self._login():
            return

        if not self._find_product():
            return

        if not self._complete_challenge():
            return

        if not self._create_cart():
            return

        if not self._patch_cart_quantity():
            return

        if not self._create_reservation():
