        Object raw = session.get("catalog_products");
        if (raw instanceof List) {
            List<Object> products = (List<Object>) raw;
            for (Object pObj : products) {
                if (!(pObj instanceof Map)) continue;
                Map<String, Object> product = (Map<String, Object>) pObj;
                Object productId = product.get("id");
                Object variantsObj = product.get("variants");

                if (!(variantsObj instanceof List)) continue;
                List<Object> variants = (List<Object>) variantsObj;

                for (Object vObj : variants) {
                    if (!(vObj instanceof Map)) continue;
                    Map<String, Object> variant = (Map<String, Object>) vObj;
                    Object inStockObj = variant.get("in_stock");
                    boolean inStock = Boolean.TRUE.equals(inStockObj)
                            || "true".equalsIgnoreCase(String.valueOf(inStockObj))
                            || "1".equals(String.valueOf(inStockObj));

                    if (inStock) {
                        return session
                                .set("product_id", String.valueOf(productId))
                                .set("variant_id", String.valueOf(variant.get("id")))
                                .set("found_stock", true);
                    }
                }
            }
        }
        return session.set("found_stock", false);
    }

    private static Session buildCartBody(Session session) {
        String body = "{\"product_id\":\"" + session.getString("product_id")
                + "\",\"variant_id\":\"" + session.getString("variant_id");
        if (session.contains("grant_id")) {
            body += "\",\"grant_id\":\"" + session.getString("grant_id") + "\"";
        } else {
            body += "\"";
        }
        body += "}";
        return session.set("cart_body", body);
    }

    ChainBuilder resetJourney = exec(session -> session
            .remove("csrf")
            .remove("login_location")
            .remove("login_csrf")
            .remove("challenge_action")
            .remove("challenge_value")
            .remove("challenge_location")
            .remove("challenge_csrf")
            .remove("grant_id")
            .remove("product_id")
            .remove("variant_id")
            .remove("found_stock")
            .remove("cart_id")
            .remove("etag")
            .remove("order_id")
            .remove("order_csrf")
            .remove("cart_csrf")
            .remove("cart_body")
            .remove("work_attempt")
            .remove("work_done")
            .remove("work_retry_after")
    );

    ChainBuilder login = exec(
            http("login-form")
                    .get("/v2/login-form")
