    ).exec(
            http("login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("login_location"))
                    .check(jsonPath("$.csrf").optional().saveAs("login_csrf"))
    ).doIf(session -> session.contains("login_location")).then(
            http("login-redirect")
                    .get("#{login_location}")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").saveAs("login_csrf"))
    ).exec(session -> updateCsrf(session, "login_csrf"));

    ChainBuilder challenge = exec(
            http("challenge-form")
                    .get("/v2/challenge-form")
                    .check(status().in(200, 403, 404))
                    .check(css("form[action^='/v2/challenges/']", "action").optional().saveAs("challenge_action"))
                    .check(css("form[action^='/v2/challenges/'] input[name=challenge]", "value").optional().saveAs("challenge_value"))
