                            .check(status().is(200))
                            .check(jsonPath("$.grant_id").saveAs("grant_id"))
                            .check(jsonPath("$.csrf").optional().saveAs("challenge_csrf"))
            ).exec(session -> updateCsrf(session, "challenge_csrf"))
    );

    ChainBuilder catalogAndCart = exec(
            http("catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[*]").findAll().saveAs("catalog_products"))
    ).exec(session -> selectFromCatalog(session))
            .exec(session -> {
                if (!session.getBoolean("found_stock")) {
                    throw new RuntimeException("No in-stock product found in catalog");
                }
                return session;
            })
            .exec(session -> buildCartBody(session))
            .exec(
