                    .check(status().in(200, 403, 404))
                    .check(css("form[action^='/v2/challenges/']", "action").optional().saveAs("challenge_action"))
                    .check(css("form[action^='/v2/challenges/'] input[name=challenge]", "value").optional().saveAs("challenge_value"))
    ).doIf(session -> session.contains("challenge_action") && session.contains("challenge_value")).then(
            exec(http("solve-challenge")
                    .post("#{challenge_action}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"challenge\":\"#{challenge_value}\"}"))
                    .check(status().is(302))
                    .check(header("Location").optional().saveAs("challenge_location"))
                    .check(jsonPath("$.csrf").optional().saveAs("challenge_csrf"))
            ).doIf(session -> session.contains("challenge_location")).then(
                    http("challenge-redirect")
                            .get("#{challenge_location}")
                            .check(status().is(200))
                            .check(jsonPath("$.grant_id").saveAs("grant_id"))
                            .check(jsonPath("$.csrf").optional().saveAs("challenge_csrf"))
            ).exec(session -> updateCsrf(session, "challenge_csrf"))
    );

    ChainBuilder catalogAndCart = exec(session -> session
            .set("found_stock", false)
            .set("page_count", 0)
            .remove("catalog_products")
            .remove("page_data")
            .remove("page_next")
            .remove("page_next_raw"))
            .exec(
                    http("catalog-main")
                            .get("/v2/catalog")
                            .check(status().is(200))
                            .check(jsonPath("$.data.products[*]").findAll().saveAs("catalog_products"))
            )
            .exec(session -> selectFromCatalogProducts(session, session.get("catalog_products")))
            .asLongAs(session -> !session.getBoolean("found_stock") && session.getInt("page_count") < 3, "pageTraversal")
            .on(
                    exec(session -> session.set("page_count", session.getInt("page_count") + 1))
                            .exec(
                                    http("catalog-page-#{page_count}")
                                            .get(session -> {
                                                String next = session.getString("page_next");
                                                return (next == null || next.isEmpty()) ? "/v2/catalog/page" : next;
                                            })
                                            .check(status().is(200))
                                            .check(jsonPath("$.data").saveAs("page_data"))
                                            .check(jsonPath("$.next").optional().saveAs("page_next_raw"))
                            )
                            .exec(session -> {
                                session = session.remove("page_next");
                                if (session.contains("page_next_raw")) {
                                    Object next = session.getString("page_next_raw");
                                    session = session.remove("page_next_raw");
                                    if (next != null && !"null".equals(next) && !next.isEmpty()) {
                                        session = session.set("page_next", next);
                                    }
                                }
                                return session;
                            })
                            .exec(session -> selectFromPageData(session, session.get("page_data")))
            )
            .exec(session -> {
                if (!session.getBoolean("found_stock")) {
                    throw new RuntimeException("No in-stock product found after catalog traversal");
                }
                return session;
            })
            .exec(session -> buildCartBody(session))
            .exec(
                    http("create-cart")
                            .post("/v2/carts")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody("#{cart_body}"))
                            .check(status().is(201))
                            .check(jsonPath("$.id").saveAs("cart_id"))
                            .check(header("ETag").saveAs("etag"))
                            .check(jsonPath("$.csrf").optional().saveAs("cart_csrf"))
            )
            .exec(session -> updateCsrf(session, "cart_csrf"));

    ChainBuilder order = exec(
            http("create-order")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("Idempotency-Key", "#{cart_id}")
                    .header("If-Match", "#{etag}")
                    .body(StringBody("{\"cart_id\":\"#{cart_id}\"}"))
                    .check(status().is(201))
                    .check(jsonPath("$.id").saveAs("order_id"))
                    .check(jsonPath("$.csrf").optional().saveAs("order_csrf"))
    ).exec(session -> updateCsrf(session, "order_csrf"));

    ChainBuilder work = exec(session -> session.set("work_attempt", 0).set("work_done", false))
            .asLongAs(session -> !session.getBoolean("work_done"))
            .on(
                    exec(session -> session.set("work_attempt", session.getInt("work_attempt") + 1))
                            .exec(
                                    http("work")
                                            .post("/v2/work")
                                            .header("X-CSRF-Token", "#{csrf}")
                                            .body(StringBody("{}"))
                                            .check(status().in(200, 429))
                                            .check(status().saveAs("work_status"))
                            )
                            .exec(session -> {
                                String status = session.getString("work_status");
                                if ("200".equals(status)) {
                                    return session.set("work_done", true);
                                }
                                if ("429".equals(status)) {
                                    if (session.getInt("work_attempt") < 5) {
                                        return session.set("work_retry_after", 1);
                                    }
                                    return session.set("work_done", true);
                                }
                                return session;
                            })
                            .doIf(session -> session.contains("work_retry_after")).then(
                                    exec(session -> session.remove("work_retry_after"))
                                            .pause(Duration.ofMillis(1000))
                            )
            );

    ScenarioBuilder scn = scenario("PublicShopCheckout")
            .exec(session -> session.set("username", "bench"))
            .repeat(2).on(
                    resetJourney,
                    login,
                    challenge,
                    catalogAndCart,
                    order,
                    work
            );

    {
        HttpProtocolBuilder httpProtocol = http
                .baseUrl(BASE_URL)
                .disableFollowRedirect()
                .disableCaching()
                .acceptHeader("*/*")
                .contentTypeHeader("application/json");

        setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
    }
}
