import os
import re
import time
from locust import HttpUser, constant, LoadTestShape, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    _account_seq = 0

    def on_start(self):
        type(self)._account_seq += 1
        n = type(self)._account_seq
        self.username = f"bench-{n}" if n <= 16 else "bench"
        self.password = "bench"

        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self.reservation_id = None
        self.journey_count = 0

    # ---------- helpers ----------

    def _safe_json(self, resp):
        try:
            return resp.json()
        except Exception:
            return {}

    def _update_csrf_from_resp(self, resp):
        data = self._safe_json(resp)
        if isinstance(data, dict):
            csrf = data.get("csrf")
            if csrf:
                self.csrf = csrf

    def _error_from_resp(self, resp):
        data = self._safe_json(resp)
        if isinstance(data, dict):
            return data.get("error")
        return "unknown"

    def _extract_input_value(self, html, name):
        for match in re.finditer(r"<input\b[^>]*>", html, re.I):
            attrs = match.group(0)
            if re.search(r"\bname\s*=\s*[\"']%s[\"']" % re.escape(name), attrs, re.I):
                value_match = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", attrs, re.I)
                if value_match:
                    return value_match.group(1)
        return None

    def _extract_form_action(self, html):
        for match in re.finditer(r"<form\b[^>]*>", html, re.I):
            attrs = match.group(0)
            if "/v2/challenges/" in attrs:
                action_match = re.search(r"\baction\s*=\s*[\"']([^\"']+)[\"']", attrs, re.I)
                if action_match:
                    return action_match.group(1)
        return None

    def _make_relative_url(self, url):
        if url.startswith("http"):
            return url
        if url.startswith("/"):
            return url
        return "/" + url

    def _find_in_stock(self, products):
        for product in products or []:
            pid = product.get("id")
            if not pid:
                continue
            for variant in product.get("variants") or []:
                if variant.get("in_stock"):
                    return pid, variant.get("id")
        return None

    def _renew_session_and_recover(self):
        headers = {"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"}
        resp = self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        )
        if resp.status_code not in (200, 201, 202):
            resp.failure("renew failed")
            return False

        self._update_csrf_from_resp(resp)
        if self.cart_id:
            return self._recover_cart()
        return True

    def _recover_cart(self):
        headers = {"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"}
        resp = self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        )
        if resp.status_code in (200, 201, 204):
            self._update_csrf_from_resp(resp)
            return True
        else:
            resp.failure("cart recovery failed")
            return False

    def _fresh_login_and_recover(self):
        if not self.do_login():
            return False
        if self.cart_id:
            return self._recover_cart()
        return True

    def authed_request(self, method, url, json_data=None, headers_extra=None, expected=(200,)):
        for attempt in range(2):
            headers = {"X-CSRF-Token": self.csrf or ""}
            if json_data is not None:
                headers["Content-Type"] = "application/json"
            if headers_extra:
                headers.update(headers_extra)

            kwargs = {
                "headers": headers,
                "allow_redirects": False,
                "catch_response": True,
            }
            if json_data is not None:
                kwargs["json"] = json_data

            resp = self.client.request(method, url, **kwargs)

            if resp.status_code == 401:
                error = self._error_from_resp(resp)
                if error == "expired":
                    if attempt == 0:
                        if self._renew_session_and_recover():
                            continue
                        else:
                            resp.failure("401 expired renewal failed")
                            return resp
                    else:
                        resp.failure("401 expired persist after retry")
                        return resp

                elif error == "session":
                    if attempt == 0:
                        if self._fresh_login_and_recover():
                            continue
                        else:
                            resp.failure("401 revoked recovery failed")
                            return resp
                    else:
                        resp.failure("401 revoked persist after retry")
                        return resp

                else:
                    resp.failure(f"401 denied {error}")
                    return resp

            if resp.status_code in expected:
                self._update_csrf_from_resp(resp)
                return resp
            else:
                resp.failure(f"unexpected status {resp.status_code} for {method} {url}")
                return resp

        return None

    # ---------- protocol steps ----------

    def do_login(self):
        resp = self.client.get(
            "/v2/login-form", allow_redirects=False, catch_response=True
        )
        if resp.status_code != 200:
            resp.failure(f"login-form status {resp.status_code}")
            return False

        csrf = self._extract_input_value(resp.text, "csrf")
        if not csrf:
            resp.failure("login-form csrf missing")
            return False

        self.csrf = csrf
        headers = {"Content-Type": "application/json", "X-CSRF-Token": csrf}
        login_resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": csrf},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        )

        if login_resp.status_code in (301, 302, 303, 307, 308):
            loc = login_resp.headers.get("Location")
            if not loc:
                login_resp.failure("login redirect missing Location")
                return False
            loc_resp = self.client.get(loc, allow_redirects=False, catch_response=True)
            if loc_resp.status_code not in (200, 201):
                loc_resp.failure(f"login redirect GET status {loc_resp.status_code}")
                return False
            self._update_csrf_from_resp(loc_resp)
            return True

        if login_resp.status_code in (200, 201):
            self._update_csrf_from_resp(login_resp)
            return True

        login_resp.failure(f"login status {login_resp.status_code}")
        return False

    def select_product(self):
        resp = self.client.get(
            "/v2/catalog", allow_redirects=False, catch_response=True
        )
        if resp.status_code != 200:
            resp.failure(f"catalog status {resp.status_code}")
            return False

        data = self._safe_json(resp)
        products = (data.get("data") or {}).get("products") or []
        selected = self._find_in_stock(products)
        if selected:
            self.product_id, self.variant_id = selected
            return True

        page_url = "/v2/catalog/page"
        for _ in range(3):
            resp = self.client.get(page_url, allow_redirects=False, catch_response=True)
            if resp.status_code != 200:
                resp.failure(f"catalog page status {resp.status_code}")
                return False

            data = self._safe_json(resp)
            data_block = data.get("data") or {}
            product = data_block.get("product")
            if product is None and isinstance(data_block.get("products"), list):
                products = data_block.get("products")
                if products:
                    product = products[0]

            if product:
                selected = self._find_in_stock([product])
                if selected:
                    self.product_id, self.variant_id = selected
                    return True

            next_url = data.get("next")
            if not next_url:
                break
            page_url = self._make_relative_url(next_url)

        resp.failure("no in-stock product found")
        return False

    def solve_challenge(self):
        resp = self.client.get(
            "/v2/challenge-form", allow_redirects=False, catch_response=True
        )
        if resp.status_code != 200:
            resp.failure(f"challenge-form status {resp.status_code}")
            return False

        action = self._extract_form_action(resp.text)
        challenge = self._extract_input_value(resp.text, "challenge")
        if not action or challenge is None:
            resp.failure("challenge form fields missing")
            return False

        headers = {"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"}
        chal_resp = self.client.post(
            action,
            json={"challenge": challenge},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        )
        if chal_resp.status_code not in (301, 302, 303, 307, 308):
            chal_resp.failure(f"challenge POST status {chal_resp.status_code}")
            return False

        loc = chal_resp.headers.get("Location")
        if not loc:
            chal_resp.failure("challenge redirect missing Location")
            return False

        loc_resp = self.client.get(loc, allow_redirects=False, catch_response=True)
        if loc_resp.status_code not in (200, 201):
            loc_resp.failure(f"challenge redirect GET status {loc_resp.status_code}")
            return False

        data = self._safe_json(loc_resp)
        if not isinstance(data, dict) or "grant_id" not in data:
            loc_resp.failure("grant_id missing")
            return False

        self.grant_id = data["grant_id"]
        self._update_csrf_from_resp(loc_resp)
        return True

    def create_cart(self):
        payload = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        resp = self.authed_request(
            "POST", "/v2/carts", json_data=payload, expected=(201,)
        )
        if not resp or resp.status_code != 201:
            return False

        data = self._safe_json(resp)
        if not isinstance(data, dict) or "id" not in data:
            resp.failure("cart id missing")
            return False

        self.cart_id = data["id"]
        etag = resp.headers.get("ETag")
        if etag:
            self.cart_etag = etag

        return True

    def ensure_cart_etag(self):
        if not self.cart_id:
            return False

        resp = self.client.get(
            f"/v2/carts/{self.cart_id}",
            allow_redirects=False,
            catch_response=True,
        )
        if resp.status_code != 200:
            resp.failure(f"cart GET status {resp.status_code}")
            return False

        etag = resp.headers.get("ETag")
        if not etag:
            resp.failure("cart GET missing ETag")
            return False

        self.cart_etag = etag
        return True

    def patch_cart_quantity(self):
        if not self.cart_id:
            return False

        if not self.cart_etag:
            if not self.ensure_cart_etag():
                return False

        headers_extra = {"If-Match": self.cart_etag}
        resp = self.authed_request(
            "PATCH",
            f"/v2/carts/{self.cart_id}",
            json_data={"quantity": 1},
            headers_extra=headers_extra,
            expected=(200, 201, 204, 412),
        )
        if not resp:
            return False

        if resp.status_code == 412:
            if not self.ensure_cart_etag():
                return False

            headers_extra = {"If-Match": self.cart_etag}
            resp = self.authed_request(
                "PATCH",
                f"/v2/carts/{self.cart_id}",
                json_data={"quantity": 1},
                headers_extra=headers_extra,
                expected=(200, 201, 204),
            )
            if not resp:
                return False

        return resp.status_code in (200, 201, 204)

    def create_reservation(self):
        if not self.cart_id:
            return False

        resp = self.authed_request(
            "POST",
            "/v2/reservations",
            json_data={"cart_id": self.cart_id},
            expected=(202,),
        )
        if not resp or resp.status_code != 202:
            return False

        data = self._safe_json(resp)
        if not isinstance(data, dict) or "status_url" not in data:
            resp.failure("reservation missing status_url")
            return False

        status_url = self._make_relative_url(data["status_url"])
        poll_resp = None

        for poll in range(5):
            if poll > 0:
                time.sleep(0.06)

            poll_resp = self.client.get(
                status_url, allow_redirects=False, catch_response=True
            )
            if poll_resp.status_code != 200:
                poll_resp.failure(f"reservation poll status {poll_resp.status_code}")
                return False

            poll_data = self._safe_json(poll_resp)
            if not isinstance(poll_data, dict):
                poll_resp.failure("invalid reservation poll body")
                return False

            status = poll_data.get("status")
            if status == "ready":
                reservation_id = poll_data.get("reservation_id")
                if not reservation_id:
                    poll_resp.failure("ready reservation missing reservation_id")
                    return False
                self.reservation_id = reservation_id
                return True

            if status == "pending":
                continue

            if status == "failed":
                poll_resp.failure("reservation failed")
                return False

            poll_resp.failure(f"unknown reservation status {status}")
            return False

        if poll_resp:
            poll_resp.failure("reservation did not become ready after polling")
        return False

    def place_order(self):
        if not self.cart_id:
            return False

        if not self.cart_etag:
            if not self.ensure_cart_etag():
                return False

        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id

        headers_extra = {
            "If-Match": self.cart_etag,
            "Idempotency-Key": f"{self.username}-{self.cart_id}",
        }

        resp = self.authed_request(
            "POST",
            "/v2/orders",
            json_data=payload,
            headers_extra=headers_extra,
            expected=(200, 201),
        )
        if not resp:
            return False

        data = self._safe_json(resp)
        if not isinstance(data, dict):
            resp.failure("order response invalid")
            return False

        if data.get("accepted") is True:
            return True

        resp.failure("order accepted false")
        return False

    def perform_work(self):
        for attempt in range(5):
            resp = self.authed_request(
                "POST",
                "/v2/work",
                json_data={},
                expected=(200, 429),
            )
            if not resp:
                return

            if resp.status_code == 200:
                data = self._safe_json(resp)
                if data.get("ok") is True:
                    return
                resp.failure("work not ok")
                return

            if resp.status_code == 429:
                if attempt >= 4:
                    return
                retry_after = resp.headers.get("Retry-After")
                sleep_time = 1
                if retry_after and retry_after.isdigit():
                    sleep_time = int(retry_after)
                time.sleep(sleep_time)
                continue

            resp.failure(f"work unexpected status {resp.status_code}")
            return

    # ---------- journey ----------

    def run_journey(self):
        if not self.do_login():
            return False
        if not self.select_product():
            return False
        if not self.solve_challenge():
            return False
        if not self.create_cart():
            return False
        if not self.patch_cart_quantity():
            return False
        if not self.create_reservation():
            return False
        if not self.ensure_cart_etag():
            return False
        if not self.place_order():
            return False

        self.perform_work()
        return True

    @task
    def checkout_journey(self):
        if self.journey_count >= 2:
            raise StopUser()

        self.journey_count += 1
        ok = self.run_journey()
        if not ok:
            raise StopUser()


