                    .header("If-Match", session -> strValue(session, "cartEtag"))
                    .body(StringBody("{\"quantity\":1}"))
                    .check(
                            status().is(200, 204),
                            header("ETag").optional().saveAs("cartEtag"),
                            bodyString().saveAs("patchBody")
                    )
            )
            .exec(session -> {
                String csrf = extractJsonString(strValue(session, "patchBody"), "csrf");
                if (csrf != null) {
                    session = session.set("csrf", csrf);
                }
                return session;
            });
    }

    private ChainBuilder reserve() {
        return exec(http("Create Reservation")
                .post("/v2/reservations")
                .header("X-CSRF-Token", session -> strValue(session, "csrf"))
                .body(StringBody(session -> "{\"cart_id\":" + strValue(session, "cartId") + "}"))
                .check(
                        status().is(202),
                        jsonPath("$.status_url").ofString().saveAs("statusUrl"),
                        jsonPath("$.csrf").optional().saveAs("csrf")
                )
        )
        .exec(session -> session.set("pollCount", 0).set("reservationReady", false))
        .exec(asLongAs(session ->
                intValue(session, "pollCount") < 5
                        && !boolValue(session, "reservationReady", false)
        ).on(
                exec(pause(Duration.ofMillis(50)))
                .exec(http("Poll Reservation")
                        .get(session -> strValue(session, "statusUrl"))
                        .check(
                                status().is(200),
                                jsonPath("$.status").ofString().saveAs("reservationStatus"),
                                jsonPath("$.reservation_id").ofString().optional().saveAs("reservationId")
                        )
                )
                .exec(session -> {
                    session = session.set("pollCount", intValue(session, "pollCount") + 1);
                    String status = strValue(session, "reservationStatus");
                    if ("ready".equals(status)) {
                        if (!session.contains("reservationId") || session.get("reservationId") == null) {
                            throw new RuntimeException("Reservation ready but no reservation_id");
                        }
                        session = session.set("reservationReady", true);
                    } else if ("failed".equals(status)) {
                        throw new RuntimeException("Reservation failed");
                    }
                    return session;
                })
        ))
        .exec(session -> {
            if (!boolValue(session, "reservationReady", false)) {
                throw new RuntimeException("Reservation did not become ready within 5 polls");
            }
            return session;
        });
    }

    private ChainBuilder createOrder() {
        return exec(session -> session.set("idempotencyKey", "order-" + strValue(session, "cartId")))
        .exec(http("Create Order")
                .post("/v2/orders")
                .header("X-CSRF-Token", session -> strValue(session, "csrf"))
                .header("Idempotency-Key", session -> strValue(session, "idempotencyKey"))
                .header("If-Match", session -> strValue(session, "cartEtag"))
                .body(StringBody(session -> {
                    String body = "{\"cart_id\":" + strValue(session, "cartId");
                    String reservationId = strValue(session, "reservationId");
                    if (reservationId != null && !reservationId.isEmpty()) {
                        body += ",\"reservation_id\":\"" + reservationId + "\"";
                    }
                    body += "}";
                    return body;
                }))
                .check(
                        status().is(201),
                        jsonPath("$.accepted").ofBoolean().is(true),
                        jsonPath("$.id").ofString().saveAs("orderId"),
                        jsonPath("$.csrf").optional().saveAs("csrf")
                )
        );
    }

    private ChainBuilder journey() {
        return login()
                .exec(selectCatalogItem())
                .exec(createCart())
                .exec(getCart())
                .exec(patchCart())
                .exec(reserve())
                .exec(createOrder());
    }

    {
        ScenarioBuilder defaultProfileScenario = scenario("Default profile journey")
                .exec(session -> session.set("username", "bench-1"))
                .exec(repeat(2).on(journey()));

        ScenarioBuilder alternateProfileScenario = scenario("Alternate profile journey")
                .exec(session -> session.set("username", "bench-2"))
                .exec(repeat(2).on(journey()));

        setUp(
                defaultProfileScenario.injectOpen(atOnceUsers(1)),
                alternateProfileScenario.injectOpen(atOnceUsers(1))
        ).protocols(httpProtocol);
    }

    private static String strValue(Session session, String key) {
        Object value = session.get(key);
        return value == null ? null : String.valueOf(value);
    }

    private static int intValue(Session session, String key) {
        Object value = session.get(key);
        if (value == null) {
            return 0;
        }
        if (value instanceof Number) {
            return ((Number) value).intValue();
        }
        return Integer.parseInt(String.valueOf(value));
    }

    private static boolean boolValue(Session session, String key, boolean defaultValue) {
        Object value = session.get(key);
        if (value == null) {
            return defaultValue;
        }
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        return "true".equalsIgnoreCase(String.valueOf(value));
    }

    private static String jsonEscape(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private static String extractJsonString(String body, String key) {
        if (body == null) {
            return null;
        }
        Pattern pattern = Pattern.compile("\"" + key + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher matcher = pattern.matcher(body);
        if (matcher.find()) {
            return matcher.group(1);
        }
        return null;
    }
}
