```javascript
import http from 'k6/http';
import { sleep } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const base = BASE_URL.replace(/\/+$/, '');
const username = 'bench-' + __VU;

let currentCsrf = '';
let cartId = null;
let cartEtag = null;

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '120s',
    },
  },
};

function resolveUrl(u) {
  if (/^https?:\/\//i.test(u)) return u;
  if (u.indexOf('/') === 0) return base + u;
  return base + '/' + u;
}

function getHeader(res, name) {
  const lower = name.toLowerCase();
  const keys = Object.keys(res.headers || {});
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === lower) return res.headers[keys[i]];
  }
  return null;
}

function parseJsonSafe(res) {
  try {
    return JSON.parse(res.body || '{}');
  } catch (e) {
    return {};
  }
}

function parseJson(res) {
  if (!res.body) return {};
  return JSON.parse(res.body);
}

function extractInputValue(html, name) {
  const inputRe = /<input\b[^>]*>/gi;
  let m;
  let firstEmpty = null;
  while ((m = inputRe.exec(html)) !== null) {
    const tag = m[0];
    const nameMatch = tag.match(/\bname\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    const n = nameMatch ? (nameMatch[1] || nameMatch[2] || nameMatch[3]) : null;
    if (n === name) {
      const valMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
      const value = valMatch ? (valMatch[1] || valMatch[2] || valMatch[3]) : '';
      if (value && value !== '') return value;
      if (firstEmpty === null) firstEmpty = '';
    }
  }
  return firstEmpty;
}

function findChallengeAction(html) {
  const formRe = /<form\b[^>]*>/gi;
  let m;
  while ((m = formRe.exec(html)) !== null) {
    const tag = m[0];
    const actionMatch = tag.match(/\baction\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    const action = actionMatch ? (actionMatch[1] || actionMatch[2] || actionMatch[3]) : null;
    if (action && action.indexOf('/v2/challenges/') !== -1) {
      return action.replace(/&amp;/g, '&');
    }
  }
  return null;
}

function updateCsrfFromResponse(res) {
  const data = parseJsonSafe(res);
  if (data.csrf) currentCsrf = data.csrf;
}

function freshLogin() {
  http.cookieJar().clear(base);

  const formRes = http.get(base + '/v2/login-form', {
    redirects: 0,
    responseType: 'text',
  });
  if (formRes.status !== 200) throw new Error('login-form failed ' + formRes.status);

  const csrf = extractInputValue(formRes.body, 'csrf');
  if (!csrf) throw new Error('login csrf not found');
  currentCsrf = csrf;

  let loginRes = http.post(
    base + '/v2/login',
    JSON.stringify({ username: username, password: 'bench', csrf: csrf }),
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
      responseType: 'text',
    }
  );

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    if (!loc) throw new Error('login redirect missing Location');
    loginRes = http.get(resolveUrl(loc), {
      headers: { 'X-CSRF-Token': csrf },
      redirects: 0,
      responseType: 'text',
    });
  }

  if (loginRes.status < 200 || loginRes.status >= 300) {
    throw new Error('login failed ' + loginRes.status);
  }

  const data = parseJsonSafe(loginRes);
  if (data.csrf) currentCsrf = data.csrf;
}

function tryRenewSession() {
  if (!currentCsrf) return false;
  const res = http.post(
    base + '/v2/session/renew',
    '{}',
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      redirects: 0,
      responseType: 'text',
    }
  );
  if (res.status >= 200 && res.status < 300) {
    const data = parseJsonSafe(res);
    if (data.csrf) currentCsrf = data.csrf;
    return true;
  }
  return false;
}

function renewSession() {
  if (!tryRenewSession()) freshLogin();
}

function recoverCart(id) {
  const res = http.post(
    base + '/v2/carts/' + id + '/recover',
    '{}',
    {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      redirects: 0,
      responseType: 'text',
    }
  );
  if (res.status < 200 || res.status >= 300) {
    throw new Error('cart recover failed ' + res.status);
  }
  updateCsrfFromResponse(res);
}

function requestWithAuth(method, url, bodyObj, extraHeaders, retried) {
  retried = retried || false;
  const fullUrl = resolveUrl(url);
  const headers = {};
  if (currentCsrf) headers['X-CSRF-Token'] = currentCsrf;
  if (method !== 'GET') headers['Content-Type'] = 'application/json';
  if (extraHeaders) {
    for (const key in extraHeaders) headers[key] = extraHeaders[key];
  }

  const params = { headers: headers, redirects: 0, responseType: 'text' };
  let res;
  if (method === 'GET') {
    res = http.get(fullUrl, params);
  } else if (method === 'POST') {
    res = http.post(fullUrl, bodyObj ? JSON.stringify(bodyObj) : '', params);
  } else if (method === 'PATCH') {
    res = http.patch(fullUrl, bodyObj ? JSON.stringify(bodyObj) : '', params);
  } else {
    throw new Error('unsupported method ' + method);
  }

  if (res.status === 401 && !retried) {
    const err = parseJsonSafe(res);
    if (err.error === 'denied') throw new Error('denied 401');
    if (err.error === 'expired') {
      renewSession();
      if (cartId) recoverCart(cartId);
      return requestWithAuth(method, url, bodyObj, extraHeaders, true);
    }
    if (err.error === 'session') {
      if (!tryRenewSession()) freshLogin();
      if (cartId) recoverCart(cartId);
      return requestWithAuth(method, url, bodyObj, extraHeaders, true);
    }
    throw new Error('unknown 401 ' + res.body);
  }

  return res;
}

function findEligibleProduct() {
  let pagePath = '/v2/catalog/page';
  for (let i = 0; i < 3; i++) {
    const res = requestWithAuth('GET', pagePath, null, {});
    if (res.status !== 200) throw new Error('catalog page failed ' + res.status);

    const data = parseJson(res);
    let products = [];
    if (data.data && data.data.products) {
      products = Array.isArray(data.data.products) ? data.data.products : [data.data.products];
    } else if (data.data && data.data.product) {
      products = [data.data.product];
    } else if (data.product) {
      products = [data.product];
    } else if (Array.isArray(data.products)) {
      products = data.products;
    } else if (Array.isArray(data.data)) {
      products = data.data;
    }

    for (let i = 0; i < products.length; i++) {
      const p = products[i];
      if (!p || !p.id) continue;
      const variants = p.variants || [];
      for (let j = 0; j < variants.length; j++) {
        const v = variants[j];
        if (v.id && v.in_stock) {
          return { product_id: p.id, variant_id: v.id };
        }
      }
    }

    let next = data.next;
    if (!next && data.data && data.data.next) next = data.data.next;
    if (!next) break;
    pagePath = next;
  }
  throw new Error('no eligible product found in first 3 catalog pages');
}

function solveChallenge() {
  const formRes = requestWithAuth('GET', '/v2/challenge-form', null, {});
  if (formRes.status === 404 || formRes.status === 405) return null;
  if (formRes.status !== 200) throw new Error('challenge-form failed ' + formRes.status);

  const action = findChallengeAction(formRes.body);
  if (!action) throw new Error('challenge action missing');
  const challenge = extractInputValue(formRes.body, 'challenge');
  if (challenge === null) throw new Error('challenge input missing');

  const postRes = requestWithAuth('POST', action, { challenge: challenge }, {});
  if (postRes.status !== 302) throw new Error('challenge post expected 302 got ' + postRes.status);

  const loc = getHeader(postRes, 'Location');
  if (!loc) throw new Error('challenge redirect missing Location');

  const locRes = requestWithAuth('GET', loc, null, {});
  if (locRes.status !== 200) throw new Error('challenge location GET failed ' + locRes.status);

  const data = parseJson(locRes);
  if (data.csrf) currentCsrf = data.csrf;
  return data.grant_id;
}

function createCart(selected, grantId) {
  const payload = { product_id: selected.product_id, variant_id: selected.variant_id };
  if (grantId) payload.grant_id = grantId;

  const res = requestWithAuth('POST', '/v2/carts', payload, {});
  if (res.status !== 201) throw new Error('cart create failed ' + res.status);

  updateCsrfFromResponse(res);
  const data = parseJson(res);
  if (!data.id) throw new Error('cart id missing');
  cartId = data.id;

  cartEtag = getHeader(res, 'Etag');
  if (!cartEtag) {
    const getRes = requestWithAuth('GET', '/v2/carts/' + cartId, null, {});
    if (getRes.status !== 200) throw new Error('cart GET after create failed ' + getRes.status);
    cartEtag = getHeader(getRes, 'Etag');
  }
  if (!cartEtag) throw new Error('cart ETag missing');

  return cartId;
}

function patchCart() {
  const url = '/v2/carts/' + cartId;
  const payload = { quantity: 2 };

  let res = requestWithAuth('PATCH', url, payload, { 'If-Match': cartEtag });
  if (res.status === 412) {
    const getRes = requestWithAuth('GET', url, null, {});
    if (getRes.status !== 200) throw new Error('cart GET after 412 failed ' + getRes.status);
    cartEtag = getHeader(getRes, 'Etag');
    if (!cartEtag) throw new Error('cart ETag missing after 412');
    res = requestWithAuth('PATCH', url, payload, { 'If-Match': cartEtag });
  }

  if (res.status < 200 || res.status >= 300) throw new Error('cart patch failed ' + res.status);
  updateCsrfFromResponse(res);

  const etag = getHeader(res, 'Etag');
  if (etag) {
    cartEtag = etag;
  } else {
    const getRes = requestWithAuth('GET', url, null, {});
    if (getRes.status === 200) cartEtag = getHeader(getRes, 'Etag');
  }
}

function createReservation(cartId) {
  const res = requestWithAuth('POST', '/v2/reservations', { cart_id: cartId }, {});
  if (res.status !== 202) throw new Error('reservation create failed ' + res.status);

  updateCsrfFromResponse(res);
  const data = parseJson(res);
  const statusUrl = data.status_url;
  if (!statusUrl) throw new Error('reservation status_url missing');

  for (let i = 0; i < 5; i++) {
    sleep(0.06);
    const pollRes = requestWithAuth('GET', statusUrl, null, {});
    if (pollRes.status !== 200) throw new Error('reservation poll failed ' + pollRes.status);

    const st = parseJson(pollRes);
    if (st.status === 'ready') {
      if (!st.reservation_id) throw new Error('reservation_id missing when ready');
      if (st.csrf) currentCsrf = st.csrf;
      return st.reservation_id;
    }
    if (st.status === 'failed') throw new Error('reservation failed');
  }
  throw new Error('reservation not ready after 5 polls');
}

function commitOrder(reservationId) {
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;

  const headers = {
    'Idempotency-Key': 'idem-' + cartId + '-' + __VU + '-' + __ITER,
  };
  if (cartEtag) headers['If-Match'] = cartEtag;

  const res = requestWithAuth('POST', '/v2/orders', payload, headers);

  if (res.status === 200) {
    const data = parseJsonSafe(res);
    if (data.accepted === false) throw new Error('order business failure accepted:false');
    throw new Error('unexpected order 200');
  }

  if (res.status !== 201) throw new Error('order commit failed ' + res.status);

  const data = parseJson(res);
  if (!data.accepted) throw new Error('order not accepted');
  if (!data.id) throw new Error('order id missing');
  updateCsrfFromResponse(res);
  return data.id;
}

export default function () {
  http.cookieJar().clear(base);
  currentCsrf = '';
  cartId = null;
  cartEtag = null;

  freshLogin();

  const selected = findEligibleProduct();
  const grantId = solveChallenge();

  createCart(selected, grantId);
  patchCart();

  const reservationId = createReservation(cartId);
  const orderId = commitOrder(reservationId);

  if (!cartId || !orderId) throw new Error('missing resulting IDs');
  console.log('cart_id=' + cartId + ' order_id=' + orderId);
}
