import os
import re
import time

from locust import HttpUser, LoadTestShape, StopUser, constant, task


def extract_csrf_from_html(html):
    if not html:
        return None
    for tag in re.finditer(r'<input\b[^>]*>', html, re.I):
        tag_text = tag.group(0)
        if re.search(r'\bname\s*=\s*["\']?\s*csrf\s*["\']?(?=[\s>])', tag_text, re.I):
            vm = re.search(r'\bvalue\s*=\s*["\']([^"\']*)["\']', tag_text, re.I)
            if vm:
                return vm.group(1)
            vm = re.search(r'\bvalue\s*=\s*([^\s>]+)', tag_text, re.I)
            if vm:
                return vm.group(1)
    return None


def parse_challenge_form(html):
    action = None
    challenge = None

    fm = re.search(r'<form\b[^>]*\baction\s*=\s*["\']([^"\']*v2/challenges/[^"\']+)["\']', html, re.I)
    if fm:
        action = fm.group(1)
    else:
        fm = re.search(r'<form\b[^>]*\baction\s*=\s*([^\s>]+)', html, re.I)
        if fm and 'challenge' in fm.group(1):
            action = fm.group(1)

    im = re.search(r'<input\b[^>]*\bname\s*=\s*["\']?\s*challenge\s*["\']?[^>]*>', html, re.I)
    if im:
        tag = im.group(0)
        vm = re.search(r'\bvalue\s*=\s*["\']([^"\']*)["\']', tag, re.I)
        if vm:
            challenge = vm.group(1)
        else:
            vm = re.search(r'\bvalue\s*=\s*([^\s>]+)', tag, re.I)
            if vm:
                challenge = vm.group(1)

    return action, challenge


class BenchmarkShape(LoadTestShape):
    user_total = 2
    spawn_rate = 2
    spawned = False
    completed_users = 0

    def tick(self):
        if not self.spawned:
            self.spawned = True
            return (self.user_total, self.spawn_rate)

        done = BenchmarkShape.completed_users
        if done >= self.user_total:
            return None
        return (self.user_total - done, self.spawn_rate)


class ShopUser(HttpUser):
    wait_time = constant(0)

    next_account = 1

    def on_start(self):
        self.username = f"bench-{ShopUser.next_account}"
        ShopUser.next_account = (ShopUser.next_account % 16) + 1

        self.iterations = 0
        self.csrf = None
        self.cart_id = None
        self.order_id = None
        self.etag = None
        self.idem_key = None

    def on_stop(self):
        BenchmarkShape.completed_users += 1

    @task
    def do_journey(self):
        self.iterations += 1
        try:
            self.run_journey()
        except Exception:
            pass
        self.post_work()
        if self.iterations >= 2:
            raise StopUser()

    def run_journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.order_id = None
        self.etag = None
        self.idem_key = f"idem-{self.username}-{time.time_ns()}"

        if not self.login():
            return False

        product_id, variant_id = self.find_eligible_item()
        if not product_id or not variant_id:
            return False

        grant_id = self.obtain_grant()
        if grant_id is False:
            return False

        cart_id = self.create_cart(product_id, variant_id, grant_id)
        if not cart_id:
            return False
        self.cart_id = cart_id

        if not self.patch_cart(cart_id):
            return False

        reservation_id = self.create_reservation(cart_id)
        if reservation_id is None:
            return False

        order_id = self.create_order(cart_id, reservation_id)
        if not order_id:
            return False

        self.order_id = order_id
        return True

    def login(self):
        with self.client.get(
            "/v2/login-form", catch_response=True, allow_redirects=False
        ) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login form 302 missing Location")
                    return False
                resp.success()
                with self.client.get(
                    location, catch_response=True, allow_redirects=False
                ) as resp2:
                    if resp2.status_code != 200:
                        resp2.failure(f"login form redirect status {resp2.status_code}")
                        return False
                    csrf = extract_csrf_from_html(resp2.text)
                    if not csrf:
                        resp2.failure("no csrf after login form redirect")
                        return False
                    self.csrf = csrf
                    resp2.success()
            elif resp.status_code == 200:
                csrf = extract_csrf_from_html(resp.text)
                if not csrf:
                    resp.failure("no csrf in login form")
                    return False
                self.csrf = csrf
                resp.success()
            else:
                resp.failure(f"login form status {resp.status_code}")
                return False

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            allow_redirects=False,
        ) as resp:
            if resp.status_code in (200, 302):
                if resp.status_code == 302:
                    location = resp.headers.get("Location")
                    if not location:
                        resp.failure("login 302 missing Location")
                        return False
                    resp.success()
                    with self.client.get(
                        location, catch_response=True, allow_redirects=False
                    ) as resp2:
                        if resp2.status_code not in (200, 201):
                            resp2.failure(f"login location status {resp2.status_code}")
                            return False
                        try:
                            data = resp2.json()
                        except Exception:
                            resp2.failure("login location invalid JSON")
                            return False
                        self.csrf = data.get("csrf") or self.csrf
                        resp2.success()
                        return True
                else:
                    try:
                        data = resp.json()
                    except Exception:
                        resp.failure("login invalid JSON")
                        return False
                    self.csrf = data.get("csrf") or self.csrf
