function getHeader(res, name) {
  const low = name.toLowerCase();
  if (!res || !res.headers) return null;
  for (const key of Object.keys(res.headers)) {
    if (key.toLowerCase() === low) return res.headers[key];
  }
  return null;
}

function joinUrl(base, pathOrUrl) {
  if (!pathOrUrl) return base;
  if (pathOrUrl.startsWith('http://') || pathOrUrl.startsWith('https://')) return pathOrUrl;
  if (pathOrUrl.startsWith('/')) return base + pathOrUrl;
  return base + '/' + pathOrUrl;
}

function extractCsrfFromHtml(html) {
  if (!html) return null;
  const inputRegex = /<input\b[^>]*>/gi;
  let match;
  while ((match = inputRegex.exec(html)) !== null) {
    const tag = match[0];
    if (/name\s*=\s*(?:"csrf"|'csrf'|csrf)/i.test(tag)) {
      const valueMatch = tag.match(/value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
      if (valueMatch) {
        return valueMatch[1] || valueMatch[2] || valueMatch[3] || null;
      }
    }
  }
  return null;
}

function parseJson(res, label) {
  try {
    return JSON.parse(res.body);
  } catch (e) {
    throw new Error(label + ' returned non-JSON body: ' + res.body);
  }
}

function login(baseUrl, username, password) {
  const formRes = http.get(baseUrl + '/v2/login-form', { redirects: 0 });
  if (formRes.status !== 200) {
    throw new Error('login-form failed status ' + formRes.status + ' body ' + formRes.body);
  }
  const formCsrf = extractCsrfFromHtml(formRes.body);
  if (!formCsrf) {
    throw new Error('login-form contained no csrf input');
  }

  const payload = JSON.stringify({ username: username, password: password, csrf: formCsrf });
  const loginParams = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': formCsrf,
    },
    redirects: 0,
  };

  let loginRes = http.post(baseUrl + '/v2/login', payload, loginParams);

  if (loginRes.status === 301 || loginRes.status === 302 || loginRes.status === 303 || loginRes.status === 307 || loginRes.status === 308) {
    const location = getHeader(loginRes, 'Location');
    if (!location) {
      throw new Error('login redirect missing Location header');
    }
    const locUrl = joinUrl(baseUrl, location);
    loginRes = http.get(locUrl, { redirects: 0 });
  }

  if (loginRes.status < 200 || loginRes.status >= 300) {
    throw new Error('login failed status ' + loginRes.status + ' body ' + loginRes.body);
