  const catalogRes = http.get(baseUrl + '/v2/catalog', { redirects: 0 });
  if (catalogRes.status !== 200) {
    throw new Error('catalog failed status ' + catalogRes.status + ' body ' + catalogRes.body);
  }

  const catalog = parseJson(catalogRes, 'catalog');
  const products = (catalog.data && catalog.data.products) || [];
  for (const product of products) {
    if (product && product.id && Array.isArray(product.variants)) {
      for (const variant of product.variants) {
        if (variant && variant.id && variant.in_stock) {
          return { product_id: product.id, variant_id: variant.id };
        }
      }
    }
  }

  let next = '/v2/catalog/page';
  let pages = 0;
  while (next && pages < 3) {
    const pageUrl = joinUrl(baseUrl, next);
    const pageRes = http.get(pageUrl, { redirects: 0 });
    if (pageRes.status !== 200) {
      throw new Error('catalog page failed status ' + pageRes.status + ' body ' + pageRes.body);
    }
    const pageData = parseJson(pageRes, 'catalog page');
    let product = null;
    if (pageData.product) product = pageData.product;
    else if (pageData.data && pageData.data.product) product = pageData.data.product;
    else if (pageData.data && Array.isArray(pageData.data.products) && pageData.data.products.length > 0) product = pageData.data.products[0];

    if (product && product.id && Array.isArray(product.variants)) {
      for (const variant of product.variants) {
        if (variant && variant.id && variant.in_stock) {
          return { product_id: product.id, variant_id: variant.id };
        }
      }
    }

    next = (pageData && pageData.next) || (pageData.data && pageData.data.next) || null;
    pages++;
  }

  throw new Error('no in-stock product found in catalog');
}

function createCart(baseUrl, csrf, productId, variantId) {
  const payload = JSON.stringify({
    product_id: productId,
    variant_id: variantId,
  });
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
  };
  const res = http.post(baseUrl + '/v2/carts', payload, params);
  if (res.status !== 201) {
    throw new Error('cart creation failed status ' + res.status + ' body ' + res.body);
  }

  const data = parseJson(res, 'cart creation');
  const etag = getHeader(res, 'ETag');
  if (!etag) {
    throw new Error('cart creation missing ETag');
  }
  const nextCsrf = data.csrf || csrf;
  return { cartId: data.id, etag: etag, csrf: nextCsrf, data: data };
}

function getCart(baseUrl, cartId) {
  const res = http.get(baseUrl + '/v2/carts/' + cartId, { redirects: 0 });
  if (res.status !== 200) {
    throw new Error('get cart failed status ' + res.status + ' body ' + res.body);
  }
  const etag = getHeader(res, 'ETag');
  if (!etag) {
    throw new Error('get cart missing ETag');
  }
  let data = {};
  if (res.body && res.body.length > 0) {
    try {
      data = JSON.parse(res.body);
    } catch (e) {
      // ignore body parse errors for GET cart; ETag is the required part
    }
  }
  return { etag: etag, csrf: data.csrf || null, data: data };
}

function patchCart(baseUrl, csrf, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity: quantity });
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
    },
    redirects: 0,
  };
  return http.patch(baseUrl + '/v2/carts/' + cartId, payload, params);
}

function postOrder(baseUrl, csrf, cartId, etag, idempotencyKey) {
  const payload = JSON.stringify({ cart_id: cartId });
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
      'Idempotency-Key': idempotencyKey,
    },
    redirects: 0,
  };
  return http.post(baseUrl + '/v2/orders', payload, params);
}

export default function () {
