    if (freshCart.csrf) csrf = freshCart.csrf;
    etag = freshCart.etag;
    patchRes = patchCart(BASE_URL, csrf, cartId, etag, quantity);
  }

  if (patchRes.status < 200 || patchRes.status >= 300) {
    throw new Error('cart patch failed status ' + patchRes.status + ' body ' + patchRes.body);
  }

  const patchEtag = getHeader(patchRes, 'ETag');
  if (patchEtag) etag = patchEtag;

  if (patchRes.body && patchRes.body.length > 0) {
    try {
