      if (patchData && patchData.csrf) csrf = patchData.csrf;
    } catch (e) {
      // patch response may be empty; not an error
    }
  }

  const idempotencyKey = 'order-' + cartId + '-' + vu + '-' + iter;
  let orderRes = postOrder(BASE_URL, csrf, cartId, etag, idempotencyKey);

