import os
import time
import uuid
from html.parser import HTMLParser

from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser


BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
MAX_ITER = 2
QUANTITY = 2


class TokenParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.csrf = None
        self.challenge = None
        self.action = None

    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if tag == "form":
            action = d.get("action", "")
            if "/v2/challenges/" in action:
                self.action = action
        elif tag == "input":
            name = d.get("name")
            if name == "csrf" and not self.csrf:
                self.csrf = d.get("value")
            elif name == "challenge":
                self.challenge = d.get("value")


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0.1)

    account_counter = 0
    completed_users = 0

    def on_start(self):
        self.client.allow_redirects = False
        type(self).account_counter += 1
        num = type(self).account_counter
        self.username = f"bench-{num}" if num <= 16 else "bench"
        self.password = "bench"
        self.iteration = 0

    @task
    def run_journey(self):
        if self.iteration >= MAX_ITER:
            type(self).completed_users += 1
            raise StopUser()

        self.iteration += 1
        self.client.cookies.clear()
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.idempotency_key = None
        self.grant_id = None

        self._journey()

    def _journey(self):
        if not self._login():
            return

        product_id, variant_id = self._get_product()
        if not product_id or not variant_id:
            return

        self._obtain_grant()

        if not self._create_cart(product_id, variant_id):
            return

        if not self._get_cart_etag():
            return

        self._do_work()

        if not self._patch_cart():
            return

        self._create_order()

    @staticmethod
    def _json(resp):
        try:
            return resp.json()
        except Exception:
            return {}

    def _login(self):
        with self.client.get(
            "/v2/login-form", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(
                    f"GET /v2/login-form expected 200, got {resp.status_code}: {resp.text[:200]}"
                )
                return False
            resp.success()

            parser = TokenParser()
            parser.feed(resp.text)
            self.csrf = parser.csrf

        if not self.csrf:
            with self.client.get(
                "/v2/login-form", allow_redirects=False, catch_response=True
            ) as dummy:
                dummy.success()
            return False

        headers = {"X-CSRF-Token": self.csrf, "Content-Type": "application/json"}
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 302:
                resp.success()
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("login 302 without Location")
                    return False
                with self.client.get(loc, allow_redirects=False, catch_response=True) as r2:
                    if r2.status_code not in (200, 201):
                        r2.failure(
                            f"login redirect GET expected 200/201, got {r2.status_code}: {r2.text[:200]}"
                        )
                        return False
                    r2.success()
                    data = self._json(r2)
            elif resp.status_code in (200, 201):
                resp.success()
                data = self._json(resp)
            else:
                resp.failure(
                    f"POST /v2/login expected 200/302, got {resp.status_code}: {resp.text[:200]}"
                )
                return False

        if data.get("csrf"):
            self.csrf = data["csrf"]
        return True

    def _obtain_grant(self):
        with self.client.get(
            "/v2/challenge-form", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code == 404:
                resp.success()
                return False
            if resp.status_code != 200:
                resp.failure(
                    f"GET /v2/challenge-form expected 200, got {resp.status_code}: {resp.text[:200]}"
                )
                return False
            resp.success()

            parser = TokenParser()
            parser.feed(resp.text)
            action = parser.action
            challenge = parser.challenge

        if not action or challenge is None:
            return False

        headers = {"X-CSRF-Token": self.csrf, "Content-Type": "application/json"}
        with self.client.post(
            action,
            json={"challenge": challenge},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 302:
                resp.success()
                loc = resp.headers.get("Location")
                if not loc:
                    resp.failure("challenge form POST 302 without Location")
                    return False
                with self.client.get(loc, allow_redirects=False, catch_response=True) as r2:
                    if r2.status_code != 200:
                        r2.failure(
                            f"challenge follow GET expected 200, got {r2.status_code}: {r2.text[:200]}"
                        )
                        return False
                    r2.success()
                    data = self._json(r2)
            elif resp.status_code == 200:
                resp.success()
                data = self._json(resp)
            else:
                resp.failure(
                    f"challenge POST expected 302/200, got {resp.status_code}: {resp.text[:200]}"
                )
                return False

        self.grant_id = data.get("grant_id")
        if data.get("csrf"):
            self.csrf = data["csrf"]

        return bool(self.grant_id)

    def _get_product(self):
        with self.client.get(
            "/v2/catalog", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(
                    f"GET /v2/catalog expected 200, got {resp.status_code}: {resp.text[:200]}"
                )
                return None, None
            resp.success()
            data = self._json(resp)
            products = data.get("data", {}).get("products", [])
            pid, vid = self._choose_product_variant(products)
            if pid and vid:
                return pid, vid

        next_url = "/v2/catalog/page"
        for _ in range(3):
            with self.client.get(next_url, allow_redirects=False, catch_response=True) as resp:
                if resp.status_code != 200:
                    resp.failure(
                        f"GET {next_url} expected 200, got {resp.status_code}: {resp.text[:200]}"
                    )
                    return None, None
                resp.success()
                data = self._json(resp)
                product = data.get("data")
                if isinstance(product, list):
                    products = product
                elif product:
                    products = [product]
                else:
                    products = []
                pid, vid = self._choose_product_variant(products)
                if pid and vid:
                    return pid, vid
                next_url = data.get("next")
                if not next_url:
                    break

        return None, None

    @staticmethod
    def _choose_product_variant(products):
        if not isinstance(products, list):
            return None, None

        for prod in products:
            if not isinstance(prod, dict):
                continue
            pid = prod.get("id")
            variants = prod.get("variants", [])
            for var in variants:
                if isinstance(var, dict) and var.get("in_stock") is True:
                    vid = var.get("id")
                    if pid and vid:
                        return pid, vid
            if pid and variants:
                first_var = variants[0]
                if isinstance(first_var, dict):
                    return pid, first_var.get("id")

        return None, None

    def _create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id

        headers = {"X-CSRF-Token": self.csrf, "Content-Type": "application/json"}
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 201:
                resp.failure(
                    f"POST /v2/carts expected 201, got {resp.status_code}: {resp.text[:200]}"
                )
                return False
            resp.success()

            data = self._json(resp)
            self.cart_id = data.get("id")
            if not self.cart_id:
                resp.failure("cart creation response missing id")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]

        return True

    def _get_cart_etag(self):
        with self.client.get(
            f"/v2/carts/{self.cart_id}", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(
                    f"GET /v2/carts/{self.cart_id} expected 200, got {resp.status_code}: {resp.text[:200]}"
                )
                return False
            resp.success()

            etag = resp.headers.get("ETag") or resp.headers.get("etag")
            if not etag:
                resp.failure("GET cart did not return ETag")
                return False

            self.etag = etag

            data = self._json(resp)
            if data.get("csrf"):
                self.csrf = data["csrf"]

        return True

    def _refresh_cart_etag(self):
        return self._get_cart_etag()

    def _do_work(self):
        headers = {"X-CSRF-Token": self.csrf, "Content-Type": "application/json"}
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 200:
                    resp.success()
                    return True

                if resp.status_code == 429:
                    retry_after = resp.headers.get("Retry-After", "1")
                    resp.success()
                    if attempt < 4:
                        try:
                            sleep_time = float(retry_after)
                        except Exception:
                            sleep_time = 1
                        time.sleep(max(sleep_time, 0.05))
                        continue
                    return False

                resp.failure(
                    f"Unexpected /v2/work status {resp.status_code}: {resp.text[:200]}"
                )
                return False

        return False

    def _patch_once(self, payload, allow_conflict):
        headers = {
            "X-CSRF-Token": self.csrf,
            "Content-Type": "application/json",
            "If-Match": self.etag,
        }
        with self.client.patch(
            f"/v2/carts/{self.cart_id}",
            json=payload,
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (200, 204):
                resp.success()
                etag = resp.headers.get("ETag") or resp.headers.get("etag")
                if etag:
                    self.etag = etag
                data = self._json(resp)
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return "success"

            if resp.status_code == 412:
                if allow_conflict:
                    resp.success()
                else:
                    resp.failure("unexpected 412 on cart PATCH retry")
                return "conflict"

            if resp.status_code == 401:
                if self._handle_401(resp):
                    return "recovered"
                return "failure"

            resp.failure(
                f"PATCH cart expected 200/204/412, got {resp.status_code}: {resp.text[:200]}"
            )
            return "failure"

    def _patch_cart(self):
        payload = {"quantity": QUANTITY}

        result = self._patch_once(payload, True)
        if result == "success":
            if not self.etag:
                self._refresh_cart_etag()
            return True

        if result == "conflict":
            if not self._refresh_cart_etag():
                return False
            result = self._patch_once(payload, False)
            if result == "success":
                if not self.etag:
                    self._refresh_cart_etag()
                return True
            if result == "conflict":
                return False
            if result == "recovered":
                if not self._refresh_cart_etag():
                    return False
                result = self._patch_once(payload, False)
                if result == "success":
                    return True
            return False

        if result == "recovered":
            result = self._patch_once(payload, False)
            if result == "success":
                return True
            if result == "conflict":
                if not self._refresh_cart_etag():
                    return False
                result = self._patch_once(payload, False)
                if result == "success":
                    return True
            return False

        return False

    def _create_order_once(self, allow_conflict):
        if not self.idempotency_key:
            self.idempotency_key = uuid.uuid4().hex

        payload = {"cart_id": self.cart_id}
        headers = {
            "X-CSRF-Token": self.csrf,
            "Content-Type": "application/json",
            "Idempotency-Key": self.idempotency_key,
            "If-Match": self.etag,
        }
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 201:
                data = self._json(resp)
                if data.get("accepted") is not True:
                    resp.failure("order 201 but accepted != true")
                    return "failure"
                resp.success()
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return "success"

            if resp.status_code == 200:
                data = self._json(resp)
                if data.get("accepted") is False:
                    resp.failure("HTTP 200 accepted:false business failure")
                else:
                    resp.failure("order expected 201, got HTTP 200")
                return "failure"

            if resp.status_code == 412:
                if allow_conflict:
                    resp.success()
                else:
                    resp.failure("unexpected 412 on order retry")
                return "conflict"

            if resp.status_code == 401:
                if self._handle_401(resp):
                    return "recovered"
                return "failure"

            resp.failure(
                f"POST /v2/orders expected 201, got {resp.status_code}: {resp.text[:200]}"
            )
            return "failure"

    def _create_order(self):
        result = self._create_order_once(True)
        if result == "success":
            return True

        if result == "conflict":
            if not self._refresh_cart_etag():
                return False
            result = self._create_order_once(False)
            if result == "success":
                return True
            if result == "conflict":
                return False
            if result == "recovered":
                result = self._create_order_once(False)
                if result == "success":
                    return True
            return False

        if result == "recovered":
            result = self._create_order_once(False)
            if result == "success":
                return True
            if result == "conflict":
                if not self._refresh_cart_etag():
                    return False
                result = self._create_order_once(False)
                if result == "success":
                    return True
            return False

        return False

    def _handle_401(self, resp):
        try:
            error = resp.json().get("error")
        except Exception:
            resp.failure("401 without json error")
            return False

        if error == "denied":
            resp.failure("401 denied")
            return False

        if error == "expired":
            resp.success()

            with self.client.post(
                "/v2/session/renew",
                json={},
                headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                allow_redirects=False,
                catch_response=True,
            ) as r:
                if r.status_code not in (200, 201):
                    r.failure(
                        f"renew expected 200/201, got {r.status_code}: {r.text[:200]}"
                    )
                    return False
                r.success()
                data = self._json(r)
                if data.get("csrf"):
                    self.csrf = data["csrf"]

            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                    allow_redirects=False,
                    catch_response=True,
                ) as r2:
                    if r2.status_code not in (200, 201, 204):
                        r2.failure(
                            f"cart recover expected 200/201/204, got {r2.status_code}: {r2.text[:200]}"
                        )
                        return False
                    r2.success()
                    data2 = self._json(r2)
                    if data2.get("csrf"):
                        self.csrf = data2["csrf"]

            return True

        if error == "session":
            resp.success()

            if not self._login():
                return False

            if self.cart_id:
                with self.client.post(
                    f"/v2/carts/{self.cart_id}/recover",
                    json={},
                    headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
                    allow_redirects=False,
                    catch_response=True,
                ) as r:
                    if r.status_code not in (200, 201, 204):
                        r.failure(
                            f"cart recover expected 200/201/204, got {r.status_code}: {r.text[:200]}"
                        )
                        return False
                    r.success()
                    data = self._json(r)
                    if data.get("csrf"):
                        self.csrf = data["csrf"]

            return True

        resp.failure(f"unknown 401 error: {error}")
        return False


class JourneyShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False
        self.spawned_once = False

    def tick(self):
        if not self.started:
            self.started = True
            return (2, 2)

        current = self.runner.user_count
        if current > 0:
            self.spawned_once = True
            return (current, 1)

        if self.spawned_once and ShopUser.completed_users >= 2:
            return None

        return (2, 2)
