import http from 'k6/http';
import { sleep } from 'k6';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const lower = name.toLowerCase();
  for (const key of Object.keys(res.headers)) {
    if (key.toLowerCase() === lower) return res.headers[key];
  }
  return null;
}

function extractInputValue(html, inputName) {
  const inputs = html.match(/<\s*input\b[^>]*>/gi) || [];
  for (let i = 0; i < inputs.length; i++) {
    const tag = inputs[i];
    const nameMatch = tag.match(/\bname\s*=\s*["']([^"']+)["']/i);
    if (nameMatch && nameMatch[1] === inputName) {
      const valueMatch = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
      if (valueMatch) return valueMatch[1];
      const unquoted = tag.match(/\bvalue\s*=\s*([^\s>]+)/i);
      if (unquoted) return unquoted[1];
      return '';
    }
  }
  return null;
}

function extractFormAction(html) {
  const forms = html.match(/<\s*form\b[^>]*>/gi) || [];
  for (let i = 0; i < forms.length; i++) {
    const action = forms[i].match(/\baction\s*=\s*["']([^"']+)["']/i);
    if (action) return action[1];
  }
  return null;
}

function extractCsrfFromBody(body, fallback) {
  if (!body) return fallback;
  try {
    const j = JSON.parse(body);
    if (j && typeof j.csrf === 'string') return j.csrf;
  } catch (e) {
    // not JSON
  }
  return fallback;
}

function resolveUrl(base, loc) {
  if (!loc) return loc;
  if (loc.startsWith('http://') || loc.startsWith('https://')) return loc;
  if (loc.startsWith('/')) return base + loc;
  return base + '/' + loc;
}

export function setup() {
  const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
  const formRes = http.get(BASE + '/v2/login-form', { maxRedirects: 0 });
  if (formRes.status !== 200) throw new Error('setup login form status ' + formRes.status);
  const csrf = extractInputValue(formRes.body, 'csrf');
  if (!csrf) throw new Error('setup missing csrf');

  const loginBody = JSON.stringify({ username: 'bench-1', password: 'bench', csrf: csrf });
  let res = http.post(BASE + '/v2/login', loginBody, {
    headers: { 'Content-Type': 'application/json' },
    maxRedirects: 0,
  });

  if (res.status === 301 || res.status === 302 || res.status === 303) {
    const loc = getHeader(res, 'Location');
    if (loc) res = http.get(resolveUrl(BASE, loc), { maxRedirects: 0 });
  }

  if (res.status < 200 || res.status >= 300) {
    throw new Error('setup login failed ' + res.status + ': ' + res.body);
  }

  return { csrf: extractCsrfFromBody(res.body, csrf) };
}

export default function () {
  const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
  const username = 'bench-' + ((__VU - 1) % 16 + 1);

  let csrf = '';
  let cartId = null;
  let cartEtag = null;
  let grantId = null;
  let reservationId = null;
  let orderId = null;
  let idempotencyKey = null;

  function extractError(res) {
    try {
      return JSON.parse(res.body).error || '';
    } catch (e) {
      return '';
    }
  }

  function renewSession() {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    };
    const res = http.post(BASE + '/v2/session/renew', '{}', { headers, maxRedirects: 0 });
    if (res.status >= 200 && res.status < 300) {
      csrf = extractCsrfFromBody(res.body, csrf);
      return true;
    }
    return false;
  }

  function recoverCart() {
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    };
    const res = http.post(BASE + '/v2/carts/' + cartId + '/recover', '{}', {
      headers,
      maxRedirects: 0,
    });
    if (res.status >= 200 && res.status < 300) {
      csrf = extractCsrfFromBody(res.body, csrf);
      const etag = getHeader(res, 'ETag');
      if (etag) cartEtag = etag;
      return true;
    }
    return false;
  }

  function freshLogin() {
    const formRes = http.get(BASE + '/v2/login-form', { maxRedirects: 0 });
    if (formRes.status !== 200) return false;
    const loginCsrf = extractInputValue(formRes.body, 'csrf');
    if (!loginCsrf) return false;

    const loginBody = JSON.stringify({ username: username, password: 'bench', csrf: loginCsrf });
    let res = http.post(BASE + '/v2/login', loginBody, {
      headers: { 'Content-Type': 'application/json' },
      maxRedirects: 0,
    });

    if (res.status === 301 || res.status === 302 || res.status === 303) {
      const loc = getHeader(res, 'Location');
      if (!loc) return false;
      res = http.get(resolveUrl(BASE, loc), { maxRedirects: 0 });
    }

    if (res.status < 200 || res.status >= 300) return false;
    csrf = extractCsrfFromBody(res.body, loginCsrf);
    return true;
  }

  function login() {
    if (!freshLogin()) {
      fail('login failed for user ' + username);
    }
  }

  function authRequest(method, url, body, ifMatch, idempotencyKey, op) {
    let attempt = 0;
    while (attempt < 2) {
      attempt++;
      const headers = {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      };
      if (ifMatch) headers['If-Match'] = ifMatch;
      if (idempotencyKey) headers['Idempotency-Key'] = idempotencyKey;

      const params = { headers, maxRedirects: 0 };
      const res = http.request(method.toUpperCase(), url, body, params);

      if (res.status >= 200 && res.status < 300) {
        csrf = extractCsrfFromBody(res.body, csrf);
        const etag = getHeader(res, 'ETag');
        if (etag) cartEtag = etag;
        return res;
      }

      if (res.status === 301 || res.status === 302 || res.status === 303) {
        return res;
      }

      if (res.status === 429) {
        return res;
      }

      if (res.status === 401) {
        const err = extractError(res);
        if (err === 'expired' || err === 'expiry') {
          if (!renewSession()) fail('session renew failed for ' + op);
          if (cartId) {
            if (!recoverCart()) fail('cart recover failed for ' + op);
            ifMatch = cartEtag;
          }
          if (attempt >= 2) fail('401 expired retry failed for ' + op);
          continue;
        }

        if (err === 'session' || err === 'revoked') {
          if (!freshLogin()) fail('session revoked login failed for ' + op);
          if (cartId) {
            if (!recoverCart()) fail('cart recover failed for ' + op);
            ifMatch = cartEtag;
          }
          if (attempt >= 2) fail('401 session retry failed for ' + op);
          continue;
        }

        if (err === 'denied') {
          fail('401 denied for ' + op);
        }

        fail('401 error=' + err + ' for ' + op + ': ' + res.body);
      }

      if (res.status === 412) {
        if (!cartId) fail('412 with no cart for ' + op);
        const cartRes = http.get(BASE + '/v2/carts/' + cartId, { maxRedirects: 0 });
        if (cartRes.status !== 200) fail('412 re-read cart failed: ' + cartRes.status);
        const etag = getHeader(cartRes, 'ETag');
        if (etag) cartEtag = etag;
        ifMatch = cartEtag;
        if (attempt >= 2) fail('412 retry failed for ' + op);
        continue;
      }

      fail('Unexpected ' + res.status + ' for ' + op + ': ' + res.body);
    }
    fail('authRequest exhausted retries for ' + op);
  }

  function selectProductAndVariant() {
    let nextPath = '/v2/catalog/page';
    for (let i = 0; i < 3; i++) {
      const res = http.get(BASE + nextPath, { maxRedirects: 0 });
      if (res.status !== 200) fail('catalog page status ' + res.status + ': ' + res.body);

      let data;
      try {
        data = JSON.parse(res.body);
      } catch (e) {
        fail('catalog parse failed');
      }

      let product = null;
      const payloadData = data && data.data;
      if (payloadData && payloadData.product) product = payloadData.product;
      else if (payloadData && payloadData.products && payloadData.products.length) product = payloadData.products[0];
      else if (payloadData && payloadData.id) product = payloadData;
      else if (data && data.product) product = data.product;
      else if (data && data.products && data.products.length) product = data.products[0];
      else if (Array.isArray(data)) product = data[0];
      else if (Array.isArray(payloadData)) product = payloadData[0];

      if (product && product.id) {
        const variants = product.variants || [];
        const variant = variants.find(v => v.in_stock === true || v.in_stock === 1);
        if (variant) {
          return { productId: product.id, variantId: variant.id };
        }
      }

      const next = data && data.next;
      if (next && typeof next === 'string' && next !== 'null') {
        nextPath = next.startsWith('/') ? next : '/' + next;
      } else {
        break;
      }
    }
    fail('no in-stock product found in catalog');
  }

  function getGrantId() {
    for (let attempt = 0; attempt < 2; attempt++) {
      const formRes = http.get(BASE + '/v2/challenge-form', { maxRedirects: 0 });
      if (formRes.status !== 200) fail('challenge form status ' + formRes.status);

      const action = extractFormAction(formRes.body);
      const challengeVal = extractInputValue(formRes.body, 'challenge');
      if (!action || !challengeVal) fail('challenge form missing action or challenge');

      const challUrl = resolveUrl(BASE, action);
      const res = authRequest(
        'post',
        challUrl,
        JSON.stringify({ challenge: challengeVal }),
        null,
        null,
        'challenge'
      );

      if (res.status === 301 || res.status === 302 || res.status === 303) {
        const loc = getHeader(res, 'Location');
        if (!loc) fail('challenge redirect missing Location');
        const locRes = http.get(resolveUrl(BASE, loc), { maxRedirects: 0 });
        if (locRes.status !== 200) fail('challenge redirect status ' + locRes.status + ': ' + locRes.body);
        let j;
        try {
          j = JSON.parse(locRes.body);
        } catch (e) {
          fail('challenge redirect parse failed');
        }
        csrf = j.csrf || csrf;
        if (!j.grant_id) fail('challenge redirect missing grant_id');
        return j.grant_id;
      }

      if (res.status === 200 || res.status === 201) {
        let j;
        try {
          j = JSON.parse(res.body);
        } catch (e) {
          fail('challenge parse failed');
        }
        csrf = j.csrf || csrf;
        if (!j.grant_id) fail('challenge response missing grant_id');
        return j.grant_id;
      }

      sleep(0.05);
    }
    fail('could not obtain grant_id');
  }

  function createCart(productId, variantId, withGrantId) {
    const payload = { product_id: productId, variant_id: variantId };
    if (withGrantId) payload.grant_id = withGrantId;

    const res = authRequest('post', BASE + '/v2/carts', JSON.stringify(payload), null, null, 'cart-create');
    if (res.status !== 201) fail('cart create status ' + res.status + ': ' + res.body);

    let j;
    try {
      j = JSON.parse(res.body);
    } catch (e) {
      fail('cart create parse failed');
    }
    if (!j.id) fail('cart create missing id');
    cartId = j.id;
    csrf = j.csrf || csrf;
    const etag = getHeader(res, 'ETag');
    if (etag) cartEtag = etag;
  }

  function patchCart() {
    const url = BASE + '/v2/carts/' + cartId;
    const res = authRequest('patch', url, JSON.stringify({ quantity: 2 }), cartEtag, null, 'cart-patch');
    if (res.status < 200 || res.status >= 300) {
      fail('cart patch failed: ' + res.status + ' ' + res.body);
    }
  }

  function createReservation() {
    const res = authRequest(
      'post',
      BASE + '/v2/reservations',
      JSON.stringify({ cart_id: cartId }),
      null,
      null,
      'reservation-create'
    );
    if (res.status !== 202) fail('reservation status ' + res.status + ': ' + res.body);

    let j;
    try {
      j = JSON.parse(res.body);
    } catch (e) {
      fail('reservation parse failed');
    }
    csrf = j.csrf || csrf;
    const statusUrl = j.status_url;
    if (!statusUrl) fail('reservation missing status_url');
    const fullStatusUrl = resolveUrl(BASE, statusUrl);

    for (let i = 0; i < 5; i++) {
      sleep(0.05);
      const resStatus = http.get(fullStatusUrl, { maxRedirects: 0 });
      if (resStatus.status !== 200) {
        fail('reservation poll status ' + resStatus.status + ': ' + resStatus.body);
      }
      let dj;
      try {
        dj = JSON.parse(resStatus.body);
      } catch (e) {
        fail('reservation poll parse failed');
      }
      if (dj.status === 'ready') {
        if (!dj.reservation_id) fail('reservation ready missing reservation_id');
        return dj.reservation_id;
      } else if (dj.status === 'failed') {
        fail('reservation failed');
      }
    }
    fail('reservation not ready after 5 polls');
  }

  function createOrder(withReservationId) {
    const url = BASE + '/v2/orders';
    idempotencyKey = 'idem-' + cartId;
    const body = JSON.stringify({ cart_id: cartId, reservation_id: withReservationId });
    const res = authRequest('post', url, body, cartEtag, idempotencyKey, 'order-create');

    if (res.status !== 201 && res.status !== 200) {
      fail('order create status ' + res.status + ': ' + res.body);
    }
    let j;
    try {
      j = JSON.parse(res.body);
    } catch (e) {
      fail('order create parse failed');
    }
    if (j.accepted !== true) fail('order accepted false');
    if (!j.id) fail('order missing id');
    csrf = j.csrf || csrf;
    orderId = j.id;
  }

  login();
  const selected = selectProductAndVariant();
  grantId = getGrantId();
  createCart(selected.productId, selected.variantId, grantId);
  patchCart();
  reservationId = createReservation();
  createOrder(reservationId);
}
