import re
import time
from locust import HttpUser, LoadTestShape, constant
from locust.exception import StopUser


class ShopUser(HttpUser):
    wait_time = constant(0)
    max_iterations = 2

    def on_start(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idempotency_key = None
        self.quantity = 1
        self.iterations_done = 0

    def _base_headers(self):
        return {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
        }

    def _safe_json(self, resp):
        try:
            return resp.json()
        except Exception:
            return None

    def _json_error(self, resp):
        data = self._safe_json(resp)
        if data:
            return data.get("error")
        return None

    def _extract_csrf(self, html):
        tags = re.findall(r'<input\b[^>]*>', html, re.I)
        for tag in tags:
            if re.search(r'\bname\s*=\s*("csrf"|\'csrf\'|csrf)', tag, re.I):
                val = re.search(r'\bvalue\s*=\s*("([^"]*)"|\'([^\']*)\'|([^"\' >]+))', tag, re.I)
                if val:
                    return val.group(2) or val.group(3) or val.group(4) or ""
                return ""
        return None

    def _update_csrf_from_data(self, data):
        if data and "csrf" in data:
            self.csrf = data["csrf"]

    def _login(self):
        with self.client.get("/v2/login-form", allow_redirects=False, catch_response=True) as resp:
            if resp.status_code != 200:
                resp.failure(f"login form failed {resp.status_code}")
                raise StopUser()
            form_csrf = self._extract_csrf(resp.text)
            if not form_csrf:
                resp.failure("login form missing csrf")
                raise StopUser()
            self.csrf = form_csrf

        with self.client.post(
            "/v2/login",
            json={"username": "bench", "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf, "Content-Type": "application/json"},
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = self._safe_json(resp)
                if not data:
                    resp.failure("login response not json")
                    raise StopUser()
                self._update_csrf_from_data(data)
                return True

            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 missing Location")
                    raise StopUser()
                if not location.startswith("http"):
                    location = location if location.startswith("/") else f"/{location}"
                with self.client.get(location, allow_redirects=False, catch_response=True) as loc_resp:
                    if loc_resp.status_code != 200:
                        loc_resp.failure(f"login follow failed {loc_resp.status_code}")
                        raise StopUser()
                    data = self._safe_json(loc_resp)
                    if not data:
                        loc_resp.failure("login follow not json")
                        raise StopUser()
                    self._update_csrf_from_data(data)
                    return True

            resp.failure(f"login failed {resp.status_code}")
            raise StopUser()

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = self._safe_json(resp)
                self._update_csrf_from_data(data)
                return True
            resp.failure(f"session renew failed {resp.status_code}")
            return False

    def _recover_cart_only(self):
        if not self.cart_id:
            return True
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 200:
                data = self._safe_json(resp)
                self._update_csrf_from_data(data)
                self.cart_etag = resp.headers.get("ETag", self.cart_etag)
                return True
            resp.failure(f"cart recover failed {resp.status_code}")
            return False

    def _fresh_login_and_recover_cart(self):
        self._login()
        if self.cart_id:
            return self._recover_cart_only()
        return True

    def _mutate(self, method, path, payload=None, expected_status=(200, 201, 202), track_etag=False):
        for attempt in range(2):
            headers = self._base_headers()
            if method.upper() == "PATCH" and self.cart_etag:
                headers["If-Match"] = self.cart_etag
            if method.upper() == "POST" and "orders" in path and self.cart_etag:
                headers["If-Match"] = self.cart_etag

            with self.client.request(
                method.upper(),
                path,
                json=payload,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code in expected_status:
                    data = self._safe_json(resp)
                    self._update_csrf_from_data(data)
                    if track_etag and resp.headers.get("ETag"):
                        self.cart_etag = resp.headers.get("ETag")
                    return resp

                if resp.status_code == 401:
                    err = self._json_error(resp)
                    if err == "expired":
                        resp.failure(f"{method} {path} expired")
                        if self._renew_session():
                            if self.cart_id and not self._recover_cart_only():
                                return None
                            continue
                        return None
                    if err == "session":
                        resp.failure(f"{method} {path} session")
                        if self._fresh_login_and_recover_cart():
                            continue
                        return None
                    resp.failure(f"{method} {path} 401 {err}")
                    return None

                if resp.status_code == 429:
                    retry_after = resp.headers.get("Retry-After")
                    if retry_after and attempt < 1:
                        time.sleep(float(retry_after))
                        continue
                    resp.failure(f"{method} {path} 429")
                    return None

                resp.failure(f"{method} {path} failed: {resp.status_code}")
                return None
        return None

    def _get_cart_etag(self):
        with self.client.get(
            f"/v2/carts/{self.cart_id}", allow_redirects=False, catch_response=True
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"cart GET failed {resp.status_code}")
                return False
            self.cart_etag = resp.headers.get("ETag")
            if not self.cart_etag:
                resp.failure("cart GET missing ETag")
                return False
            data = self._safe_json(resp)
            self._update_csrf_from_data(data)
            return True

    def _get_product_variant(self):
        with self.client.get("/v2/catalog", allow_redirects=False, catch_response=True) as resp:
            if resp.status_code == 200:
                data = self._safe_json(resp)
                if data:
                    products = data.get("data", {}).get("products", []) or []
                    for p in products:
                        for v in p.get("variants", []) or []:
                            if v.get("in_stock"):
                                return p.get("id"), v.get("id"), v.get("in_stock", 0)
            else:
                resp.failure(f"catalog failed {resp.status_code}")

        page = "/v2/catalog/page"
        for _ in range(3):
            with self.client.get(page, allow_redirects=False, catch_response=True) as resp:
                if resp.status_code != 200:
                    resp.failure(f"catalog page failed {resp.status_code}")
                    break
                data = self._safe_json(resp)
                if data:
                    item = data.get("data")
                    if item and "variants" in item:
                        for v in item.get("variants", []) or []:
                            if v.get("in_stock"):
                                return item.get("id"), v.get("id"), v.get("in_stock", 0)
                    products = data.get("data", {}).get("products", []) if isinstance(data.get("data"), dict) else []
                    for p in products:
                        for v in p.get("variants", []) or []:
                            if v.get("in_stock"):
                                return p.get("id"), v.get("id"), v.get("in_stock", 0)
                    next_rel = data.get("next")
                    if not next_rel:
                        break
                    page = next_rel if next_rel.startswith("/") else f"/{next_rel}"
                else:
                    break
        return None, None, 0

    def _create_cart(self):
        product_id, variant_id, stock = self._get_product_variant()
        if not product_id:
            raise StopUser()
        self.quantity = 2 if stock >= 2 else 1

        resp = self._mutate(
            "POST",
            "/v2/carts",
            payload={"product_id": product_id, "variant_id": variant_id},
            expected_status=(201,),
            track_etag=True,
        )
        if not resp or resp.status_code != 201:
            return False

        data = self._safe_json(resp)
        if not data or not data.get("id"):
            resp.failure("cart creation missing id")
            return False
        self.cart_id = data["id"]

        if not self.cart_etag:
            if not self._get_cart_etag():
                return False
        return True

    def _patch_cart(self):
        payload = {"quantity": self.quantity}
        for attempt in range(2):
            headers = self._base_headers()
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            with self.client.patch(
                f"/v2/carts/{self.cart_id}",
                json=payload,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 200:
                    data = self._safe_json(resp)
                    self._update_csrf_from_data(data)
                    self.cart_etag = resp.headers.get("ETag", self.cart_etag)
                    return True

                if resp.status_code == 412 and attempt == 0:
                    if self._get_cart_etag():
                        continue
                    resp.failure("cart GET for patch 412 failed")
                    return False

                if resp.status_code == 401:
                    err = self._json_error(resp)
                    if err == "expired":
                        resp.failure("patch expired")
                        if self._renew_session():
                            if not self._recover_cart_only():
                                return False
                            continue
                        return False
                    if err == "session":
                        resp.failure("patch session")
                        if self._fresh_login_and_recover_cart():
                            continue
                        return False
                    resp.failure(f"patch 401 {err}")
                    return False

                resp.failure(f"patch failed {resp.status_code}")
                return False
        return False

    def _order(self):
        payload = {"cart_id": self.cart_id}
        idempotency_key = f"order-{self.cart_id}"
        for attempt in range(2):
            headers = self._base_headers()
            headers["Idempotency-Key"] = idempotency_key
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code in (200, 201):
                    data = self._safe_json(resp)
                    self._update_csrf_from_data(data)
                    accepted = data.get("accepted") if data else None
                    if accepted is True:
                        return True
                    resp.failure(f"order accepted {accepted}")
                    return False

                if resp.status_code == 412 and attempt == 0:
                    if self._get_cart_etag():
                        continue
                    resp.failure("cart GET for order 412 failed")
                    return False

                if resp.status_code == 401:
                    err = self._json_error(resp)
                    if err == "expired":
                        resp.failure("order expired")
                        if self._renew_session():
                            if not self._recover_cart_only():
                                return False
                            continue
                        return False
                    if err == "session":
                        resp.failure("order session")
                        if self._fresh_login_and_recover_cart():
                            continue
                        return False
                    resp.failure(f"order 401 {err}")
                    return False

                resp.failure(f"order failed {resp.status_code}")
                return False
        return False

    def _work(self, label):
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers=self._base_headers(),
                allow_redirects=False,
                catch_response=True,
            ) as resp:
