                        return False

                    if err == "session":
                        if self._fresh_login_and_recover_cart():
                            continue
                        return False

                    resp.failure(f"patch 401 {err}")
                    return False

                resp.failure(f"patch failed {resp.status_code}")
                return False
        return False

    def _order(self):
        payload = {"cart_id": self.cart_id}
        idempotency_key = f"order-{self.cart_id}"

        for attempt in range(2):
            headers = self._base_headers()
            headers["Idempotency-Key"] = idempotency_key
            if self.cart_etag:
                headers["If-Match"] = self.cart_etag

            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code in (200, 201):
                    data = self._safe_json(resp)
                    self._update_csrf_from_data(data)
                    accepted = data.get("accepted") if data else None
                    if accepted is True:
                        self.cart_id = None
                        self.cart_etag = None
                        return True
                    resp.failure(f"order accepted {accepted}")
                    return False

                if resp.status_code == 412 and attempt == 0:
                    if self._get_cart_etag():
                        continue
                    return False

                if resp.status_code == 401:
                    err = self._json_error(resp)
                    if err == "expired":
                        if self._renew_session():
                            if not self._recover_cart_only():
                                return False
                            continue
                        return False

                    if err == "session":
                        if self._fresh_login_and_recover_cart():
                            continue
                        return False

                    resp.failure(f"order 401 {err}")
                    return False

                resp.failure(f"order failed {resp.status_code}")
                return False
        return False

    def _work(self, label):
        for attempt in range(5):
            with self.client.post(
                "/v2/work",
                json={},
                headers=self._base_headers(),
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 200:
                    data = self._safe_json(resp)
                    self._update_csrf_from_data(data)
                    if data and data.get("ok") is True:
                        return
                    resp.failure(f"{label} work ok false")
                    return

                if resp.status_code == 429:
                    retry_after = resp.headers.get("Retry-After")
                    if retry_after and attempt < 4:
                        try:
                            time.sleep(float(retry_after))
                        except ValueError:
                            time.sleep(1)
                        continue
                    return

                if resp.status_code == 401:
                    err = self._json_error(resp)
                    if err == "expired":
                        if self._renew_session():
                            if self.cart_id and not self._recover_cart_only():
                                return
                            continue
                        return

                    if err == "session":
                        if self._fresh_login_and_recover_cart():
                            continue
                        return

                    if err == "denied":
                        resp.failure(f"{label} work denied")
                        return
                    resp.failure(f"{label} work 401 {err}")
                    return

                resp.failure(f"{label} work {resp.status_code}")
                return

    def _reset_journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.quantity = 1

    @task
    def perform_journey(self):
        if self.iterations_done >= self.max_iterations:
            raise StopUser()

        try:
            self._reset_journey()
            self._login()
            self._work("after_login")
            if not self._create_cart():
                return
            if not self._patch_cart():
                return
            if not self._order():
                return
            self._work("after_order")
        except StopUser:
            raise
        finally:
            self.iterations_done += 1


