            .check(jsonPath("$.data.products[0].id").ofInt().saveAs("productId"))
            .check(jsonPath("$.data.products[0].variants[0].id").ofInt().saveAs("variantId"))
        );
    }

    private static ChainBuilder challenge() {
        return exec(http("challenge-form")
            .get("/v2/challenge-form")
            .check(status().is(200))
            .check(regex("<form[^>]+action=[\"']([^\"']+)[\"']").saveAs("challengeAction"))
            .check(css("input[name='challenge']", "value").saveAs("challengeValue"))
        )
        .exec(http("challenge-submit")
