            .check(status().in(200, 201))
            .check(jsonPath("$.csrf").optional().saveAs("recoverCsrf"))
            .check(header("ETag").optional().saveAs("recoverEtag"))
        )
        .exec(session -> {
            Session s = session;
            String csrf = session.getString("recoverCsrf");
            String etag = session.getString("recoverEtag");
            if (csrf != null) {
                s = s.set("csrf", csrf);
            }
            if (etag != null) {
                s = s.set("cartEtag", etag);
            }
