            .check(status().saveAs(statusKey))
            .check(bodyString().saveAs(requestName + "Body"))
            .check(jsonPath("$.error").optional().saveAs(errorKey))
            .check(jsonPath("$.status_url").optional().saveAs("reservationStatusUrl"))
            .check(jsonPath("$.csrf").optional().saveAs("reservationCsrf"))
        );
    }

    private static ChainBuilder reservationWithRecovery() {
        return exec(reservationCall("reservation1"))
        .exec(session -> {
            int st = session.getInt("reservation1Status");
            String err = session.getString("reservation1Error");
            boolean expiry = st == 401 && ("expired".equals(err) || "session".equals(err));
            if (expiry) {
                return session.set("reservation1Recover", true);
            }
            if (st != 202) {
                return session.markAsFailed();
            }
            String csrf = session.getString("reservationCsrf");
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session.set("reservation1Recover", false);
