                    }
                    String csrf = session.getString("reservationCsrf");
                    if (csrf != null) {
                        session = session.set("csrf", csrf);
                    }
                    return session;
                })
            );
    }

    private static ChainBuilder pollReservationAttempt() {
        return exec(http("reservation-poll")
            .get(session -> session.getString("reservationStatusUrl"))
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .check(status().is(200))
            .check(jsonPath("$.status").saveAs("reservationPollStatus"))
            .check(jsonPath("$.reservation_id").optional().saveAs("reservationId"))
            .check(jsonPath("$.csrf").optional().saveAs("reservationPollCsrf"))
        )
        .exec(session -> {
            int count = session.getInt("reservationPollCount") + 1;
            String status = session.getString("reservationPollStatus");

            if ("ready".equals(status)) {
                Session s = session.set("reservationPollCount", count)
                    .set("reservationPollDone", true);
                String csrf = session.getString("reservationPollCsrf");
                if (csrf != null) {
                    s = s.set("csrf", csrf);
                }
                return s;
            }

            if ("failed".equals(status)) {
                return session.markAsFailed()
                    .set("reservationPollCount", count)
                    .set("reservationPollDone", true);
            }

            return session.set("reservationPollCount", count)
                .set("reservationPollDone", false);
        });
    }

    private static ChainBuilder pollReservation() {
        return exec(session -> session.remove("reservationId")
            .set("reservationPollCount", 0)
            .set("reservationPollDone", false))
        .exec(asLongAs(session -> !session.getBoolean("reservationPollDone") &&
                session.getInt("reservationPollCount") < 5,
            "reservationPollCounter")
            .on(exec(pollReservationAttempt()).pause(Duration.ofMillis(50))))
        .exec(session -> {
            if (session.getString("reservationId") == null) {
                return session.markAsFailed();
            }
            return session;
        });
    }

