            .body(new StringBody(session -> "{\"cart_id\":" + session.getInt("cartId") +
                ",\"reservation_id\":\"" + session.getString("reservationId") + "\"}"))
            .check(status().in(201, 401))
            .check(status().saveAs(statusKey))
            .check(bodyString().saveAs(requestName + "Body"))
            .check(jsonPath("$.error").optional().saveAs(errorKey))
            .check(jsonPath("$.csrf").optional().saveAs("orderCsrf"))
        );
    }

    private static ChainBuilder orderWithRecovery() {
        return exec(orderCall("order1"))
        .exec(session -> {
            int st = session.getInt("order1Status");
            String err = session.getString("order1Error");
            boolean expiry = st == 401 && ("expired".equals(err) || "session".equals(err));
            if (expiry) {
                return session.set("order1Recover", true);
            }
            if (st != 201) {
                return session.markAsFailed();
            }
            String csrf = session.getString("orderCsrf");
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session.set("order1Recover", false);
        })
        .doIf(session -> session.getBoolean("order1Recover"))
            .then(
                recoverExpiredSession()
                .exec(orderCall("order2"))
                .exec(session -> {
                    if (session.getInt("order2Status") != 201) {
                        return session.markAsFailed();
                    }
                    String csrf = session.getString("orderCsrf");
                    if (csrf != null) {
                        session = session.set("csrf", csrf);
                    }
                    return session;
                })
            );
    }

    private static ChainBuilder workWithRetry() {
        return exec(session -> session.set("workAttempt", 0).set("workDone", false).remove("workStatus"))
        .exec(asLongAs(session -> !session.getBoolean("workDone") &&
                session.getInt("workAttempt") < 5,
            "workCounter")
            .on(
                exec(http("work")
                    .post("/v2/work")
                    .header("X-CSRF-Token", session -> session.getString("csrf"))
                    .body(new StringBody("{}"))
                    .check(status().in(200, 429))
                    .check(status().saveAs("workStatus"))
                    .check(header("Retry-After").optional().saveAs("workRetryAfter"))
                )
                .exec(session -> {
                    int attempt = session.getInt("workAttempt") + 1;
                    int st = session.getInt("workStatus");
                    if (st == 200) {
                        return session.set("workAttempt", attempt).set("workDone", true);
                    }
                    if (st == 429) {
                        return session.set("workAttempt", attempt).set("workDone", false);
                    }
                    return session.markAsFailed().set("workAttempt", attempt).set("workDone", true);
                })
                .doIf(session -> session.getInt("workStatus") == 429 && session.getInt("workAttempt") < 5)
                    .then(pause(Duration.ofSeconds(1)))
            )
        )
        .exec(session -> {
            if (session.getInt("workStatus") != 200) {
                return session.markAsFailed();
            }
            return session;
        });
    }

    private static ChainBuilder journey() {
        return loginFlow()
            .exec(catalog())
            .exec(challenge())
            .exec(createCart())
            .exec(reservationWithRecovery())
            .exec(pollReservation())
            .exec(orderWithRecovery())
            .exec(workWithRetry());
    }

    private final ScenarioBuilder scn = scenario("ExpiryRecoverySimulation")
        .feed(userFeeder)
        .repeat(2).on(journey());

    {
        setUp(scn.injectOpen(atOnceUsers(2))).protocols(httpProtocol);
    }
}
