import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

export const options = {
  scenarios: {
    main: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function getHeader(res, name) {
  const headers = res.headers || {};
  const lower = name.toLowerCase();
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === lower) return headers[key];
  }
  return undefined;
}

function resolveUrl(url) {
  if (!url) return url;
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('/')) return BASE_URL + url;
  return BASE_URL + '/' + url;
}

function parseJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractError(res) {
  const body = parseJson(res);
  if (body && body.error) return body.error;
  if (res.body) {
    const text = res.body;
    const m1 = text.match(/"error"\s*:\s*"([^"]+)"/);
    if (m1) return m1[1];
    const m2 = text.match(/error=([A-Za-z]+)/);
    if (m2) return m2[1];
  }
  return null;
}

function authHeaders(csrf, extra = {}) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
  for (const key of Object.keys(extra)) {
    headers[key] = extra[key];
  }
  return headers;
}

function getCsrfFromForm(res) {
  const value = res.html().find('input[name=csrf]').attr('value');
  if (!value) throw new Error('csrf missing');
  return value;
}

function doLogin(username, password) {
  let formRes = http.get(BASE_URL + '/v2/login-form', { redirects: 0 });
  if (!check(formRes, { 'login form 200': (r) => r.status === 200 })) {
    throw new Error('login form failed');
  }

  let csrf = getCsrfFromForm(formRes);

  let loginRes = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({ username, password, csrf }),
    { headers: authHeaders(csrf), redirects: 0 },
  );

  if (loginRes.status === 302 || loginRes.status === 301 || loginRes.status === 303) {
    const location = getHeader(loginRes, 'location');
    if (!location) throw new Error('login redirect missing location');
    loginRes = http.get(resolveUrl(location), { redirects: 0 });
  }

  if (!check(loginRes, { 'login 200': (r) => r.status === 200 })) {
    throw new Error('login failed');
  }

  const body = parseJson(loginRes);
  if (!body) throw new Error('login json missing');

  return body.csrf || csrf;
}

function selectProduct() {
  const res = http.get(BASE_URL + '/v2/catalog', { redirects: 0 });
  if (!check(res, { 'catalog 200': (r) => r.status === 200 })) {
    throw new Error('catalog failed');
  }

  const body = parseJson(res);
  const products = body && body.data && body.data.products;
  if (!products || products.length === 0) throw new Error('no products');

  for (const product of products) {
    const variant = (product.variants || []).find((v) => v.in_stock);
    if (variant) {
      return { product_id: product.id, variant_id: variant.id };
    }
  }

  throw new Error('no in-stock variant');
}

function obtainGrant(csrf) {
  const formRes = http.get(BASE_URL + '/v2/challenge-form', { redirects: 0 });
  if (!check(formRes, { 'challenge form 200': (r) => r.status === 200 })) {
    throw new Error('challenge form failed');
  }

  const action = formRes.html().find('form[action*="/v2/challenges/"]').attr('action');
  if (!action) throw new Error('challenge action missing');

  const challengeValue = formRes.html().find('input[name=challenge]').attr('value') || '';

  const postRes = http.post(
    resolveUrl(action),
    JSON.stringify({ challenge: challengeValue }),
    { headers: authHeaders(csrf), redirects: 0 },
  );

  if (postRes.status !== 302 && postRes.status !== 301 && postRes.status !== 303) {
    check(postRes, { 'challenge redirect': (r) => false });
    throw new Error('challenge post not redirect');
  }
  check(postRes, {
    'challenge redirect': (r) => r.status === 302 || r.status === 301 || r.status === 303,
  });

  const location = getHeader(postRes, 'location');
  if (!location) throw new Error('challenge redirect missing location');

  const grantRes = http.get(resolveUrl(location), { redirects: 0 });
  if (!check(grantRes, { 'grant 200': (r) => r.status === 200 })) {
    throw new Error('grant fetch failed');
  }

  const grantBody = parseJson(grantRes);
  if (!grantBody || !grantBody.grant_id) throw new Error('grant id missing');

  return { grantId: grantBody.grant_id, csrf: grantBody.csrf || csrf };
}

function createCartWithGrant(product, grantId, csrf) {
  const res = http.post(
    BASE_URL + '/v2/carts',
    JSON.stringify({
      product_id: product.product_id,
      variant_id: product.variant_id,
      grant_id: grantId,
    }),
    { headers: authHeaders(csrf), redirects: 0 },
  );

  if (!check(res, { 'cart 201': (r) => r.status === 201 })) {
    throw new Error('cart creation failed');
  }

  const body = parseJson(res);
  if (!body || !body.id) throw new Error('cart id missing');

  return {
    cartId: body.id,
    csrf: body.csrf || csrf,
    etag: getHeader(res, 'etag'),
  };
}

function recoverFromExpiry(cartId, csrf, username, password) {
  let newCsrf = csrf;

  const renewRes = http.post(
    BASE_URL + '/v2/session/renew',
    '{}',
    { headers: authHeaders(csrf), redirects: 0 },
  );

  if (renewRes.status === 401) {
    const err = extractError(renewRes);
    if (err === 'session') {
      newCsrf = doLogin(username, password);
    } else {
      check(renewRes, { 'renew 401 not session': () => false });
      throw new Error('renew failed');
    }
  } else if (renewRes.status >= 200 && renewRes.status < 300) {
    check(renewRes, { 'renew 2xx': () => true });
    const body = parseJson(renewRes);
    if (body && body.csrf) newCsrf = body.csrf;
  } else {
    check(renewRes, { 'renew 2xx': (r) => r.status >= 200 && r.status < 300 });
    throw new Error('renew unexpected status');
  }

  const recoverRes = http.post(
    BASE_URL + '/v2/carts/' + cartId + '/recover',
    '{}',
    { headers: authHeaders(newCsrf), redirects: 0 },
  );

  if (recoverRes.status < 200 || recoverRes.status >= 300) {
    check(recoverRes, { 'recover 2xx': (r) => r.status >= 200 && r.status < 300 });
    throw new Error('cart recovery failed');
  }
  check(recoverRes, { 'recover 2xx': () => true });

  const recBody = parseJson(recoverRes);
  if (recBody) {
    if (recBody.csrf) newCsrf = recBody.csrf;
    if (recBody.id) cartId = recBody.id;
  }

  return { cartId, csrf: newCsrf };
}

function pollReservation(statusUrl) {
  let reservationId = null;

  for (let i = 0; i < 5; i++) {
    sleep(0.1);

    const res = http.get(resolveUrl(statusUrl), { redirects: 0 });
    if (!check(res, { 'reservation status 200': (r) => r.status === 200 })) {
      throw new Error('reservation status failed');
    }

    const body = parseJson(res);
    if (!body) throw new Error('reservation status json missing');

    if (body.status === 'ready') {
      if (!body.reservation_id) throw new Error('ready reservation without id');
      reservationId = body.reservation_id;
      break;
    } else if (body.status === 'failed') {
      throw new Error('reservation failed');
    } else if (body.status !== 'pending') {
      throw new Error('unexpected reservation status');
    }
  }

  return reservationId;
}

function placeOrder(cartId, reservationId, csrf, etag, idempotencyKey) {
  const headers = authHeaders(csrf, { 'Idempotency-Key': idempotencyKey });
  if (etag) headers['If-Match'] = etag;

  let res = http.post(
    BASE_URL + '/v2/orders',
    JSON.stringify({ cart_id: cartId, reservation_id: reservationId }),
    { headers, redirects: 0 },
  );

  if (res.status === 412) {
    const getRes = http.get(BASE_URL + '/v2/carts/' + cartId, { redirects: 0 });
    if (!check(getRes, { 'cart get for etag 200': (r) => r.status === 200 })) {
      throw new Error('cart etag refresh failed');
    }

    const freshEtag = getHeader(getRes, 'etag');
    if (freshEtag) headers['If-Match'] = freshEtag;

    const getBody = parseJson(getRes);
    if (getBody && getBody.csrf) headers['X-CSRF-Token'] = getBody.csrf;

    res = http.post(
      BASE_URL + '/v2/orders',
      JSON.stringify({ cart_id: cartId, reservation_id: reservationId }),
      { headers, redirects: 0 },
    );
  }

  const body = parseJson(res);

  if (res.status !== 201) {
    check(res, { 'order 201': (r) => r.status === 201 });
    if (res.status === 200 && body && body.accepted === false) {
      check(res, { 'order accepted true': () => false });
      throw new Error('order business failure');
    }
    throw new Error('order failed');
  }

  if (!body || body.accepted !== true) {
    check(res, { 'order accepted true': () => body && body.accepted === true });
    throw new Error('order not accepted');
  }

  check(res, { 'order accepted true': () => true });
}

export default function () {
  const USERNAME = 'bench-' + __VU;
  const PASSWORD = 'bench';

  let csrf = doLogin(USERNAME, PASSWORD);

  const product = selectProduct();
  const challenge = obtainGrant(csrf);
  csrf = challenge.csrf;

  const cart = createCartWithGrant(product, challenge.grantId, csrf);
  let cartId = cart.cartId;
  csrf = cart.csrf;

  sleep(3);

  let reservationRes = http.post(
    BASE_URL + '/v2/reservations',
    JSON.stringify({ cart_id: cartId }),
    { headers: authHeaders(csrf), redirects: 0 },
  );

  const errorType = extractError(reservationRes);

  if (reservationRes.status === 401 && errorType === 'expired') {
    check(reservationRes, { 'session expiry recognized': () => true });
    const recovered = recoverFromExpiry(cartId, csrf, USERNAME, PASSWORD);
    cartId = recovered.cartId;
    csrf = recovered.csrf;

    reservationRes = http.post(
      BASE_URL + '/v2/reservations',
      JSON.stringify({ cart_id: cartId }),
      { headers: authHeaders(csrf), redirects: 0 },
    );
  } else if (reservationRes.status === 401 && errorType === 'session') {
    check(reservationRes, { 'session revocation recognized': () => true });
    const recovered = recoverFromExpiry(cartId, csrf, USERNAME, PASSWORD);
    cartId = recovered.cartId;
    csrf = recovered.csrf;

    reservationRes = http.post(
      BASE_URL + '/v2/reservations',
      JSON.stringify({ cart_id: cartId }),
      { headers: authHeaders(csrf), redirects: 0 },
    );
  } else if (reservationRes.status === 401 && errorType === 'denied') {
    check(reservationRes, { 'denied is not expiry': () => false });
    throw new Error('denied');
  } else if (reservationRes.status === 202) {
    check(reservationRes, { 'reservation accepted without expiry': () => true });
  } else {
    check(reservationRes, { 'expected 401 expired/session or 202': () => false });
    throw new Error('unexpected reservation status');
  }

  if (reservationRes.status !== 202) {
    check(reservationRes, { 'reservation retry 202': (r) => r.status === 202 });
    throw new Error('reservation not accepted after recovery');
  }
  check(reservationRes, { 'reservation accepted': (r) => r.status === 202 });

  const reservationBody = parseJson(reservationRes);
  if (!reservationBody || !reservationBody.status_url) {
    throw new Error('reservation status_url missing');
  }
  if (reservationBody.csrf) csrf = reservationBody.csrf;

  const reservationId = pollReservation(reservationBody.status_url);
  if (!reservationId) {
    throw new Error('reservation never ready');
  }

  const cartGet = http.get(BASE_URL + '/v2/carts/' + cartId, { redirects: 0 });
  if (!check(cartGet, { 'cart get 200': (r) => r.status === 200 })) {
    throw new Error('cart get failed');
  }

  const cartEtag = getHeader(cartGet, 'etag');
  const cartGetBody = parseJson(cartGet);
  if (cartGetBody && cartGetBody.csrf) csrf = cartGetBody.csrf;

  const idempotencyKey = 'order-' + cartId;
  placeOrder(cartId, reservationId, csrf, cartEtag, idempotencyKey);
}
