import os
import re
import uuid
from locust import HttpUser, task, between, LoadTestShape, StopUser

HOST = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USER_SEQ = 0


def get_attr(tag, attr):
    m = re.search(r"\b" + re.escape(attr) + r'\s*=\s*(["\'])(.*?)\1', tag, re.I | re.S)
    if m:
        return m.group(2)
    m = re.search(r"\b" + re.escape(attr) + r"\s*=\s*([^\s>]+)", tag, re.I)
    if m:
        return m.group(1)
    return None


def extract_csrf(html):
    pattern = re.compile(r"<input\b[^>]*>", re.I | re.S)
    for tag in pattern.findall(html):
        if re.search(r'\bname\s*=\s*(["\']?)csrf\1', tag, re.I):
            value = get_attr(tag, "value")
            if value:
                return value
    return None


def find_product_and_next(data):
    if not isinstance(data, dict):
        return None, None

    product = None
    next_url = data.get("next")

    if "data" in data and isinstance(data["data"], dict):
        d = data["data"]
        if next_url is None:
            next_url = d.get("next")

        if "id" in d and "variants" in d:
            product = d
        elif "product" in d and isinstance(d["product"], dict):
            product = d["product"]
        elif "products" in d and isinstance(d["products"], list) and d["products"]:
            product = d["products"][0]
    else:
        if "id" in data and "variants" in data:
            product = data
        elif "product" in data and isinstance(data["product"], dict):
            product = data["product"]
        elif "products" in data and isinstance(data["products"], list) and data["products"]:
            product = data["products"][0]

    return product, next_url


def safe_json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def next_username():
    global USER_SEQ
    USER_SEQ += 1
    if USER_SEQ > 16:
        USER_SEQ = 1
    return f"bench-{USER_SEQ}"


class BaseJourneyUser(HttpUser):
    wait_time = between(0.1, 0.2)
    host = HOST

    def on_start(self):
        self.username = next_username()
        self.password = "bench"
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idempotency_key = None
        self.iter_count = 0
        self.max_iterations = 2

    def update_csrf_from_response(self, resp):
        data = safe_json(resp)
        if isinstance(data, dict) and "csrf" in data:
            self.csrf = data["csrf"]

    def update_etag_from_response(self, resp):
        etag = resp.headers.get("ETag") or resp.headers.get("Etag")
        if etag:
            self.cart_etag = etag
            return
        data = safe_json(resp)
        if isinstance(data, dict) and "etag" in data:
            self.cart_etag = data["etag"]

    def do_login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="login_form",
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login_form expected 200, got {resp.status_code}")
                return False

            csrf = extract_csrf(resp.text)
            if not csrf:
                resp.failure("login_form missing csrf")
                return False
            self.csrf = csrf

        payload = {"username": self.username, "password": self.password, "csrf": self.csrf}
        with self.client.post(
            "/v2/login",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="login",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = safe_json(resp)
                if not isinstance(data, dict):
                    resp.failure("login 200 non-JSON")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True

            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 missing Location")
                    return False
                resp.success()

                with self.client.get(
                    location,
                    catch_response=True,
                    name="login_redirect",
                    allow_redirects=False,
                ) as redirected:
                    if redirected.status_code != 200:
                        redirected.failure(
                            f"login redirect expected 200, got {redirected.status_code}"
                        )
                        return False
                    data = safe_json(redirected)
                    if not isinstance(data, dict):
                        redirected.failure("login redirect non-JSON")
                        return False
                    self.csrf = data.get("csrf", self.csrf)
                    return True

            resp.failure(f"login expected 200/302, got {resp.status_code}")
            return False

    def renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="session_renew",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = safe_json(resp)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                return True

            if resp.status_code == 401:
                body = safe_json(resp)
                if isinstance(body, dict) and body.get("error") == "session":
                    resp.success()
                    return False
                resp.failure(f"renew 401 {body}")
                return False

            resp.failure(f"renew expected 200, got {resp.status_code}")
            return False

    def recover_cart(self):
        if not self.cart_id:
            return True

        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="cart_recover",
            allow_redirects=False,
        ) as resp:
            if resp.status_code in (200, 201):
                data = safe_json(resp)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                self.update_etag_from_response(resp)
                return True

            if resp.status_code == 401:
                body = safe_json(resp)
                if isinstance(body, dict) and body.get("error") == "denied":
                    resp.failure("cart recovery denied")
                else:
                    resp.failure(f"cart recovery 401 {body}")
                return False

            resp.failure(
                f"cart recovery expected 200/201, got {resp.status_code}"
            )
            return False

    def expire_renew_recover(self):
        if not self.renew_session():
            return False
        return self.recover_cart()

    def revoked_relogin_recover(self):
        if not self.do_login():
            return False
        return self.recover_cart()

    def refresh_cart_etag(self):
        if not self.cart_id:
            return False

        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            catch_response=True,
            name="get_cart",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                self.update_etag_from_response(resp)
                data = safe_json(resp)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                return True

            resp.failure(f"get cart expected 200, got {resp.status_code}")
            return False

    def auth_post(
        self,
        path,
        json_data,
        op_name,
        expected_statuses=(200, 201),
        use_if_match=False,
        headers_extra=None,
        handle_412=False,
    ):
        recovered = False
        retried_412 = False

        while True:
            headers = {"X-CSRF-Token": self.csrf}
            if headers_extra:
                headers.update(headers_extra)
            if use_if_match and self.cart_etag:
                headers["If-Match"] = self.cart_etag

            with self.client.post(
                path,
                json=json_data,
                headers=headers,
                catch_response=True,
                name=op_name,
                allow_redirects=False,
            ) as resp:
                if resp.status_code in expected_statuses:
                    self.update_csrf_from_response(resp)
                    return resp

                if resp.status_code == 412 and handle_412 and not retried_412:
                    resp.success()
                    retried_412 = True
                    if not self.refresh_cart_etag():
                        resp.failure(f"{op_name}: cannot refresh ETag after 412")
                        return None
                    continue

                if resp.status_code == 401:
                    body = safe_json(resp)
                    if not isinstance(body, dict):
                        resp.failure(f"{op_name}: 401 non-JSON")
                        return None

                    error = body.get("error")
                    if error == "expired":
                        resp.success()
                        if recovered:
                            resp.failure(f"{op_name}: still expired after recovery")
                            return None
                        recovered = True
                        if not self.expire_renew_recover():
                            resp.failure(f"{op_name}: expiry recovery failed")
                            return None
                        continue

                    if error == "session":
                        resp.success()
                        if recovered:
                            resp.failure(f"{op_name}: still session after recovery")
                            return None
                        recovered = True
                        if not self.revoked_relogin_recover():
                            resp.failure(f"{op_name}: session recovery failed")
                            return None
                        continue

                    if error == "denied":
                        resp.failure(f"{op_name}: denied is not expiry")
                        return None

                    resp.failure(f"{op_name}: 401 unknown {body}")
                    return None

                resp.failure(
                    f"{op_name}: expected {expected_statuses}, got {resp.status_code}"
                )
                return None

    def get_product_variant(self):
        with self.client.get(
            "/v2/catalog",
            catch_response=True,
            name="catalog",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = safe_json(resp)
                if isinstance(data, dict):
                    product, _ = find_product_and_next(data)
                    if product:
                        for variant in product.get("variants", []):
                            if variant.get("in_stock"):
                                return product.get("id"), variant.get("id")
            else:
                resp.failure(f"catalog expected 200, got {resp.status_code}")

        next_url = "/v2/catalog/page"
        for _ in range(3):
            if not next_url:
                break

            with self.client.get(
                next_url,
                catch_response=True,
                name="catalog_page",
                allow_redirects=False,
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"catalog page expected 200, got {resp.status_code}")
                    return None, None

                data = safe_json(resp)
                if not isinstance(data, dict):
                    resp.failure("catalog page non-JSON")
                    return None, None

                product, next_relative = find_product_and_next(data)
                if product:
                    for variant in product.get("variants", []):
                        if variant.get("in_stock"):
                            return product.get("id"), variant.get("id")

                next_url = next_relative

        return None, None

    def create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        resp = self.auth_post(
            "/v2/carts",
            payload,
            "create_cart",
            expected_statuses=(201,),
            use_if_match=False,
        )
        if resp is None:
            return None

        data = safe_json(resp)
        if not isinstance(data, dict):
            resp.failure("create_cart non-JSON")
            return None

        cart_id = data.get("id")
        if not cart_id:
            resp.failure("create_cart missing id")
            return None

        self.cart_id = cart_id
        self.csrf = data.get("csrf", self.csrf)
        self.update_etag_from_response(resp)
        self.idempotency_key = f"idem-{cart_id}-{uuid.uuid4()}"
        return cart_id

    def checkout(self):
        if not self.cart_id or not self.idempotency_key:
            return None

        payload = {"cart_id": self.cart_id}
        headers_extra = {"Idempotency-Key": self.idempotency_key}

        resp = self.auth_post(
            "/v2/orders",
            payload,
            "create_order",
            expected_statuses=(201,),
            use_if_match=True,
            headers_extra=headers_extra,
            handle_412=True,
        )
        if resp is None:
            return None

        data = safe_json(resp)
        if not isinstance(data, dict):
            resp.failure("create_order non-JSON")
            return None

        if data.get("accepted") is not True:
            resp.failure("create_order accepted false")
            return None

        self.csrf = data.get("csrf", self.csrf)
        return data.get("id")

    def execute_journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idempotency_key = None

        if not self.do_login():
            return

        product_id, variant_id = self.get_product_variant()
        if product_id is None or variant_id is None:
            return

        if not self.create_cart(product_id, variant_id):
            return

        if self.cart_etag is None:
            self.refresh_cart_etag()

        if not self.checkout():
            return

    @task
    def journey(self):
        self.iter_count += 1
        self.execute_journey()

        if self.iter_count >= self.max_iterations:
            raise StopUser()


class VariantA(BaseJourneyUser):
    profile = {"expire_after": 2}


class VariantB(BaseJourneyUser):
    profile = {
        "expire_after": 2,
        "html_layout": 1,
        "reverse_catalog": True,
    }


class JourneyShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False
        self.active = False

    def tick(self):
        if not self.started:
            self.started = True
            return {VariantA.__name__: 1, VariantB.__name__: 1}

        if self.runner.user_count > 0:
            self.active = True
            return {VariantA.__name__: 1, VariantB.__name__: 1}

        if self.active:
            return None

        return {VariantA.__name__: 1, VariantB.__name__: 1}
