                    throw new IllegalStateException("no in_stock product variant");
                }
                return session.set("productId", pick[0]).set("variantId", pick[1]);
            });
    }

    private static ChainBuilder challenge() {
        return exec(http("challenge_form")
            .get("/v2/challenge-form")
            .check(status().is(200))
            .check(css("form", "action").saveAs("challengeAction"))
            .check(css("input[name=challenge]", "value").saveAs("challenge")))
            .exec(http("challenge_submit")
                .post(session -> session.getString("challengeAction"))
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "${csrf}")
                .body(StringBody("{\"challenge\":\"${challenge}\"}"))
                .check(status().is(302))
                .check(header("Location").saveAs("challengeLocation"))
                .check(jsonPath("$.grant_id").optional().saveAs("grantId"))
                .check(jsonPath("$.csrf").optional().saveAs("freshCsrf")))
            .exec(updateCsrf())
            .exec(http("challenge_location")
                .get(session -> session.getString("challengeLocation"))
                .check(status().is(200))
                .check(jsonPath("$.grant_id").optional().saveAs("grantId"))
                .check(jsonPath("$.csrf").optional().saveAs("freshCsrf")))
            .exec(updateCsrf());
    }

    private static ChainBuilder cart() {
        return exec(http("cart_create")
            .post("/v2/carts")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "${csrf}")
            .body(StringBody(session -> {
                String productId = session.getString("productId");
                String variantId = session.getString("variantId");
                String grantId = session.getString("grantId");

                StringBuilder sb = new StringBuilder();
                sb.append("{\"product_id\":\"").append(productId)
                    .append("\",\"variant_id\":\"").append(variantId).append("\"");
                if (grantId != null && !grantId.isEmpty()) {
                    sb.append(",\"grant_id\":\"").append(grantId).append("\"");
                }
                sb.append("}");
                return sb.toString();
            }))
            .check(status().is(201))
            .check(header("ETag").optional().saveAs("cartEtag"))
            .check(jsonPath("$.id").saveAs("cartId"))
            .check(jsonPath("$.csrf").optional().saveAs("freshCsrf")))
            .exec(updateCsrf());
    }

    private static ChainBuilder reserve() {
        return exec(http("reserve_cart")
            .post("/v2/reservations")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "${csrf}")
            .body(StringBody("{\"cart_id\":\"${cartId}\"}"))
            .check(status().is(202))
            .check(jsonPath("$.status_url").saveAs("statusUrl"))
            .check(jsonPath("$.csrf").optional().saveAs("freshCsrf")))
            .exec(updateCsrf())
            .exec(session -> session.set("pollCount", 0).set("resReady", false).set("resFailed", false));
    }

    private static ChainBuilder poll() {
        return asLongAs(session -> {
            int count = session.getInt("pollCount");
            int maxPolls = session.getInt("maxPolls");
            boolean ready = Boolean.TRUE.equals(session.getBoolean("resReady"));
            boolean failed = Boolean.TRUE.equals(session.getBoolean("resFailed"));
            return count < maxPolls && !ready && !failed;
        }).on(
            exec(http("reservation_poll")
                .get(session -> session.getString("statusUrl"))
                .check(status().is(200))
                .check(jsonPath("$.status").saveAs("resStatus"))
                .check(jsonPath("$.reservation_id").optional().saveAs("reservationId"))
                .check(jsonPath("$.csrf").optional().saveAs("freshCsrf")))
                .exec(updateCsrf())
                .exec(session -> {
                    session = session.set("pollCount", session.getInt("pollCount") + 1);
                    String status = session.getString("resStatus");
                    if ("ready".equals(status)) {
                        session = session.set("resReady", true);
                    } else if ("failed".equals(status)) {
                        session = session.set("resFailed", true);
                    }
                    return session;
                })
                .pause(Duration.ofMillis(50L))
        );
    }

    private static ChainBuilder checkout() {
        return exec(http("create_order")
            .post("/v2/orders")
            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", "${csrf}")
            .header("Idempotency-Key", session -> "order-" + session.getString("cartId"))
            .header("If-Match", "${cartEtag}")
            .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cartId")
                + "\",\"reservation_id\":\"" + session.getString("reservationId") + "\"}"))
            .check(status().is(201))
            .check(jsonPath("$.accepted").is("true"))
            .check(jsonPath("$.id").saveAs("orderId"))
            .check(jsonPath("$.csrf").optional().saveAs("freshCsrf")))
            .exec(updateCsrf());
    }

    private static ChainBuilder checkoutOrFail() {
        return doIf(session -> Boolean.TRUE.equals(session.getBoolean("resReady")))
            .then(checkout())
            .exec(doIf(session -> !Boolean.TRUE.equals(session.getBoolean("resReady")))
                .then(exec(session -> session.markAsFailed())));
    }

    private static ChainBuilder journey(int maxPolls) {
        return exec(session -> session.set("maxPolls", maxPolls))
            .exec(login())
            .exec(catalog())
            .exec(challenge())
            .exec(cart())
            .exec(reserve())
            .exec(poll())
            .exec(checkoutOrFail());
    }

    ScenarioBuilder reservationProfile1 =
        scenario("reservation_profile1").exec(repeat(2).on(journey(2)));

    ScenarioBuilder reservationProfile2 =
        scenario("reservation_profile2").exec(repeat(2).on(journey(3)));

    {
        setUp(
            reservationProfile1.injectOpen(atOnceUsers(1)),
            reservationProfile2.injectOpen(atOnceUsers(1))
        ).protocols(httpProtocol);
    }
}
