```javascript
import http from 'k6/http';
import { sleep } from 'k6';

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '60s',
    },
  },
};

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const POLL_INTERVAL_S = Math.max(0.05, parseFloat(__ENV.POLL_INTERVAL || '0.02'));

const state = {
  csrf: null,
  user: null,
  username: null,
  cartId: null,
  cartEtag: null,
};

function fail(message) {
  throw new Error(message);
}

function getHeader(resp, name) {
  const keys = Object.keys(resp.headers || {});
  for (let i = 0; i < keys.length; i += 1) {
    if (String(keys[i]).toLowerCase() === name.toLowerCase()) {
      return resp.headers[keys[i]];
    }
  }
  return null;
}

function maybeJson(resp) {
  try {
    return resp.json();
  } catch (e) {
    return null;
  }
}

function absoluteUrl(url) {
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('/')) return BASE_URL + url;
  return BASE_URL + '/' + url;
}

function extractAttr(tag, attr) {
  const escaped = attr.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`(?:^|\\s)${escaped}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i');
  const m = tag.match(re);
  if (!m) return null;
  if (m[1] !== undefined) return m[1];
  if (m[2] !== undefined) return m[2];
  if (m[3] !== undefined) return m[3];
  return null;
}

function extractInputValue(html, inputName) {
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const tag = m[0];
    if (extractAttr(tag, 'name') === inputName) {
      const value = extractAttr(tag, 'value');
      if (value !== null) return value;
    }
  }
  fail(`input[name=${inputName}] not found`);
}

function extractFormAction(html) {
  const m = html.match(/<form\b[^>]*>/i);
  if (!m) fail('form tag not found');
  const action = extractAttr(m[0], 'action');
  if (!action) fail('form action not found');
  return action;
}

function resetState() {
  state.csrf = null;
  state.user = null;
  state.username = null;
  state.cartId = null;
  state.cartEtag = null;
}

function login(username, password) {
  http.cookieJar().clear(BASE_URL);

  const formResp = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (formResp.status !== 200) fail(`login-form status ${formResp.status}`);
  const csrf = extractInputValue(formResp.body, 'csrf');

  const loginResp = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password, csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    },
  );

  let data = null;

  if (loginResp.status === 302) {
    const location = getHeader(loginResp, 'Location');
    if (!location) fail('login 302 missing Location');
    const followResp = http.get(absoluteUrl(location), { redirects: 0 });
    if (followResp.status !== 200) fail(`login follow status ${followResp.status}`);
    data = maybeJson(followResp);
    if (data && data.csrf) state.csrf = data.csrf;
  } else if (loginResp.status === 200) {
    data = maybeJson(loginResp);
    if (data && data.csrf) state.csrf = data.csrf;
  } else {
    fail(`login status ${loginResp.status}: ${loginResp.body}`);
  }

  if (!state.csrf) state.csrf = csrf;
  state.username = username;
  state.user = data && data.user ? data.user : username;
}

function renewSession() {
  const resp = makeRequest(
    'POST',
    `${BASE_URL}/v2/session/renew`,
    {},
    { expectedStatus: [200, 201, 202, 204], allowRetry: false },
  );
  const data = maybeJson(resp);
  if (data && data.csrf) state.csrf = data.csrf;
  return resp;
}

function recoverCart() {
  if (!state.cartId) return;
  const resp = makeRequest(
    'POST',
    `${BASE_URL}/v2/carts/${state.cartId}/recover`,
    {},
    { expectedStatus: [200, 201, 204], allowRetry: false },
  );
  const data = maybeJson(resp);
  if (data && data.csrf) state.csrf = data.csrf;
  const etag = getHeader(resp, 'ETag');
  if (etag) state.cartEtag = etag;
}

function handle401(data, resp) {
  const err = data && data.error ? data.error : null;

  if (err === 'denied') fail('401 denied');

  if (err === 'expired') {
    renewSession();
    if (state.cartId) recoverCart();
    return;
  }

  if (err === 'session') {
    let renewed = false;
    try {
      renewSession();
      renewed = true;
    } catch (e) {
      renewed = false;
    }

    if (!renewed) {
      login(state.username, 'bench');
    }

    if (state.cartId) recoverCart();
    return;
  }

  fail(`unrecognized 401: ${resp.body}`);
}

function makeRequest(method, url, body, opts = {}) {
  const headers = Object.assign(
    {
      'Content-Type': 'application/json',
      'X-CSRF-Token': state.csrf,
    },
    opts.headers || {},
  );

  if (opts.ifMatch) headers['If-Match'] = opts.ifMatch;
  if (opts.idempotencyKey) headers['Idempotency-Key'] = opts.idempotencyKey;

  const payload = body === undefined || body === null ? '{}' : JSON.stringify(body);
  const resp = http.request(method, url, payload, { headers, redirects: 0 });
  const data = maybeJson(resp);

  if (data && data.csrf) state.csrf = data.csrf;
  const etag = getHeader(resp, 'ETag');
  if (etag) state.cartEtag = etag;

  if (resp.status === 401 && opts.allowRetry !== false) {
    handle401(data, resp);
    return makeRequest(method, url, body, Object.assign({}, opts, { allowRetry: false }));
  }

  if (opts.expectedStatus && !opts.expectedStatus.includes(resp.status)) {
    fail(`${method} ${url} expected ${opts.expectedStatus.join(',')} got ${resp.status}: ${resp.body}`);
  }

  return resp;
}

function getWithCSRF(url) {
  let resp = http.get(url, {
    headers: { 'X-CSRF-Token': state.csrf },
    redirects: 0,
  });
  let data = maybeJson(resp);
  if (data && data.csrf) state.csrf = data.csrf;

  if (resp.status === 401) {
    handle401(data, resp);
    resp = http.get(url, {
      headers: { 'X-CSRF-Token': state.csrf },
      redirects: 0,
    });
    data = maybeJson(resp);
    if (data && data.csrf) state.csrf = data.csrf;
  }

  return resp;
}

function findInStockProduct(data) {
  if (!data || !data.data || !Array.isArray(data.data.products)) return null;
  for (let i = 0; i < data.data.products.length; i += 1) {
    const product = data.data.products[i];
    if (product && Array.isArray(product.variants)) {
      const variant = product.variants.find((v) => v && v.in_stock);
      if (variant) return { product_id: product.id, variant_id: variant.id };
    }
  }
  return null;
}

function selectProduct() {
  let resp = getWithCSRF(`${BASE_URL}/v2/catalog`);
  if (resp.status !== 200) fail(`catalog status ${resp.status}`);
  let data = maybeJson(resp);
  let chosen = findInStockProduct(data);
  if (chosen) return chosen;

  let next = data && data.next ? data.next : null;
  let pageCount = 0;

  while (next && pageCount < 3) {
    resp = getWithCSRF(absoluteUrl(next));
    if (resp.status !== 200) fail(`catalog page status ${resp.status}`);
    data = maybeJson(resp);
    chosen = findInStockProduct(data);
    if (chosen) return chosen;
    next = data && data.next ? data.next : null;
    pageCount += 1;
  }

  fail('no in-stock product found');
}

function solveChallenge() {
  const resp = getWithCSRF(`${BASE_URL}/v2/challenge-form`);
  if (resp.status !== 200) fail(`challenge-form status ${resp.status}`);

  const action = extractFormAction(resp.body);
  const challenge = extractInputValue(resp.body, 'challenge');
  const actionUrl = absoluteUrl(action);

  const postResp = makeRequest(
    'POST',
    actionUrl,
    { challenge },
    { expectedStatus: [200, 302], allowRetry: true },
  );

  if (postResp.status === 302) {
    const location = getHeader(postResp, 'Location');
    if (!location) fail('challenge 302 missing Location');
    const grantResp = http.get(absoluteUrl(location), { redirects: 0 });
    if (grantResp.status !== 200) fail(`challenge grant status ${grantResp.status}`);
    const data = maybeJson(grantResp);
    if (data && data.csrf) state.csrf = data.csrf;
    if (!data || !data.grant_id) fail('challenge grant missing grant_id');
    return data.grant_id;
  }

  const data = maybeJson(postResp);
  if (data && data.grant_id) return data.grant_id;
  fail('challenge did not provide grant_id');
}

function createCart(productId, variantId, grantId) {
  const resp = makeRequest(
    'POST',
    `${BASE_URL}/v2/carts`,
    { product_id: productId, variant_id: variantId, grant_id: grantId },
    { expectedStatus: [201], allowRetry: true },
  );

  const data = maybeJson(resp);
  if (!data || !data.id) fail('cart creation missing id');
  state.cartId = data.id;

  const etag = getHeader(resp, 'ETag');
  if (etag) state.cartEtag = etag;

  return data;
}

function getCartETag() {
  const resp = getWithCSRF(`${BASE_URL}/v2/carts/${state.cartId}`);
  if (resp.status !== 200) fail(`get cart status ${resp.status}`);

  const data = maybeJson(resp);
  if (data && data.csrf) state.csrf = data.csrf;

  const etag = getHeader(resp, 'ETag');
  if (etag) state.cartEtag = etag;

  return state.cartEtag;
}

function patchCartQuantity(quantity) {
  let etag = getCartETag();
  let resp = makeRequest(
    'PATCH',
    `${BASE_URL}/v2/carts/${state.cartId}`,
    { quantity },
    { expectedStatus: [200, 412], ifMatch: etag, allowRetry: true },
  );

  if (resp.status === 412) {
    etag = getCartETag();
    resp = makeRequest(
      'PATCH',
      `${BASE_URL}/v2/carts/${state.cartId}`,
      { quantity },
      { expectedStatus: [200], ifMatch: etag, allowRetry: true },
    );
  }

  const data = maybeJson(resp);
  if (data && data.csrf) state.csrf = data.csrf;

  const newEtag = getHeader(resp, 'ETag');
  if (newEtag) state.cartEtag = newEtag;

  return resp;
}

function createReservation() {
  const resp = makeRequest(
    'POST',
    `${BASE_URL}/v2/reservations`,
    { cart_id: state.cartId },
    { expectedStatus: [202], allowRetry: true },
  );

  const data = maybeJson(resp);
  if (!data || !data.status_url) fail('reservation missing status_url');
  return data.status_url;
}

function pollReservationStatus(statusUrl) {
  const url = absoluteUrl(statusUrl);
  let reservationId = null;

  for (let i = 0; i < 5; i += 1) {
    if (i > 0) sleep(POLL_INTERVAL_S);

    const resp = http.get(url, {
      headers: { 'X-CSRF-Token': state.csrf },
      redirects: 0,
    });
    const data = maybeJson(resp);

    if (data && data.csrf) state.csrf = data.csrf;
    if (resp.status !== 200) fail(`poll status ${resp.status}: ${resp.body}`);

    const status = data ? data.status : null;

    if (status === 'ready') {
      if (!data.reservation_id) fail('ready without reservation_id');
      reservationId = data.reservation_id;
      break;
    } else if (status === 'failed') {
      fail('reservation job failed');
    } else if (status !== 'pending') {
      fail(`unexpected reservation status ${status}`);
    }
  }

  if (!reservationId) fail('reservation not ready after 5 polls');
  return reservationId;
}

function commitOrder(reservationId) {
  const idempotencyKey = `order-${state.cartId}`;

  const resp = makeRequest(
    'POST',
    `${BASE_URL}/v2/orders`,
    { cart_id: state.cartId, reservation_id: reservationId },
    {
      expectedStatus: [201],
      ifMatch: state.cartEtag,
      idempotencyKey,
      allowRetry: true,
    },
  );

  const data = maybeJson(resp);
  if (resp.status === 201) {
    if (!data || data.accepted !== true) fail(`order 201 not accepted true: ${resp.body}`);
    return data;
  }

  fail(`order status ${resp.status}`);
}

export default function main() {
  resetState();

  const username = `bench-${__VU}`;
  login(username, 'bench');

  const product = selectProduct();
  const grantId = solveChallenge();
  const cart = createCart(product.product_id, product.variant_id, grantId);

  patchCartQuantity(2);

  const statusUrl = createReservation();
  const reservationId = pollReservationStatus(statusUrl);

  commitOrder(reservationId);
}
