import json
import re
import time
import uuid

from locust import HttpUser, task, constant, LoadTestShape
from locust.exception import StopUser


def extract_csrf(html):
    """Extract the value of an <input name="csrf"> tag, tolerating attribute order/quote variants."""
    for tag in re.findall(r"<input\b[^>]*>", html, re.I):
        if re.search(r"name\s*=\s*([\"'])csrf\1", tag, re.I) or re.search(r"name\s*=\s*csrf(?:\s|>)", tag, re.I):
            m = re.search(r"value\s*=\s*([\"'])([^\"']*)\1", tag, re.I)
            if m:
                return m.group(2)
    return None


def try_parse_json(text):
    try:
        return json.loads(text)
    except Exception:
        return None


def extract_products(payload):
    if not isinstance(payload, dict):
        return []
    data = payload.get("data", payload)
    if isinstance(data, list):
        return data
    if not isinstance(data, dict):
        return []
    if "products" in data and isinstance(data["products"], list):
        return data["products"]
    if "product" in data and isinstance(data["product"], dict):
        return [data["product"]]
    return []


def pick_variant(products):
    for product in products:
        if not isinstance(product, dict):
            continue
        pid = product.get("id")
        for variant in product.get("variants", []):
            if isinstance(variant, dict) and variant.get("in_stock"):
                vid = variant.get("id")
                if pid is not None and vid is not None:
                    return str(pid), str(vid)
    return None


class ReservationUserBase(HttpUser):
    abstract = True
    wait_time = constant(0)

    profile = {}
    username = "bench"

    def on_start(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.order_id = None
        self.idempotency_key = None
        self.iterations_done = 0

    @task
    def reservation_journey(self):
        self.iterations_done += 1
        if self.iterations_done > 2:
            raise StopUser()
        self.do_journey()

    def do_journey(self):
        if not self.login():
            return
        product_id, variant_id = self.find_variant()
        if not product_id:
            return
        if not self.create_cart(product_id, variant_id):
            return
        status_url = self.create_reservation()
        if not status_url:
            return
        reservation_id = self.poll_reservation(status_url)
        if not reservation_id:
            return
        if not self.create_order(reservation_id):
            return
        self.perform_work()

    def login(self):
        # GET login form
        redirect_url = None
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            name="/v2/login-form",
            catch_response=True,
        ) as r:
            if r.status_code in (301, 302, 303, 307, 308):
                redirect_url = r.headers.get("Location")
                if not redirect_url:
                    r.failure("login-form redirect missing Location")
                    return False
            elif r.status_code == 200:
                csrf = extract_csrf(r.text)
                if not csrf:
                    r.failure("login-form csrf missing")
                    return False
            else:
                r.failure(f"login-form HTTP {r.status_code}: {r.text[:200]}")
                return False

        if redirect_url:
            with self.client.get(
                redirect_url,
                allow_redirects=False,
                name="/v2/login-form-redirect",
                catch_response=True,
            ) as r:
                if r.status_code != 200:
                    r.failure(f"login-form-redirect HTTP {r.status_code}: {r.text[:200]}")
                    return False
                csrf = extract_csrf(r.text)
                if not csrf:
                    r.failure("login-form-redirect csrf missing")
                    return False

        # POST login
        headers = {"X-CSRF-Token": csrf}
        login_redirect = None
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": csrf},
            headers=headers,
            allow_redirects=False,
            name="/v2/login",
            catch_response=True,
        ) as r:
            if r.status_code in (301, 302, 303, 307, 308):
                login_redirect = r.headers.get("Location")
                if not login_redirect:
                    r.failure("login 302 missing Location")
                    return False
            elif r.status_code == 200:
                data = try_parse_json(r.text)
                if not isinstance(data, dict) or not data.get("csrf"):
                    r.failure("login response missing csrf")
                    return False
                self.csrf = data.get("csrf", csrf)
                return True
            else:
                r.failure(f"login HTTP {r.status_code}: {r.text[:200]}")
                return False

        if login_redirect:
            with self.client.get(
                login_redirect,
                allow_redirects=False,
                name="/v2/login-location",
                catch_response=True,
            ) as r:
                if r.status_code != 200:
                    r.failure(f"login-location HTTP {r.status_code}: {r.text[:200]}")
                    return False
                data = try_parse_json(r.text)
                if not isinstance(data, dict) or not data.get("csrf"):
                    r.failure("login-location missing csrf")
                    return False
                self.csrf = data.get("csrf", csrf)
                return True
        return False

    def find_variant(self):
        with self.client.get(
            "/v2/catalog",
            allow_redirects=False,
            name="/v2/catalog",
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                data = try_parse_json(r.text)
                if isinstance(data, dict):
                    variant = pick_variant(extract_products(data))
                    if variant:
                        return variant
            # If not 200 or no variant, fall back to paged catalog.

        url = "/v2/catalog/page"
        for _ in range(3):
            with self.client.get(
                url,
                allow_redirects=False,
                name="/v2/catalog/page",
                catch_response=True,
            ) as r:
                if r.status_code != 200:
                    r.failure(f"catalog page HTTP {r.status_code}: {r.text[:200]}")
                    return None
                data = try_parse_json(r.text)
                if not isinstance(data, dict):
                    r.failure("catalog page invalid JSON")
                    return None
                variant = pick_variant(extract_products(data))
                if variant:
                    return variant
                next_url = data.get("next")
                if not next_url:
                    break
                url = next_url

        return None

    def create_cart(self, product_id, variant_id):
        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post(
            "/v2/carts",
            json={"product_id": product_id, "variant_id": variant_id},
            headers=headers,
            allow_redirects=False,
            name="/v2/carts",
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                data = try_parse_json(r.text)
                if not isinstance(data, dict) or not data.get("id"):
                    r.failure("cart create missing id")
                    return False
                self.cart_id = str(data.get("id"))
                self.cart_etag = r.headers.get("ETag")
                self.csrf = data.get("csrf", self.csrf)
                return True
            if r.status_code == 401:
                body = try_parse_json(r.text) or {}
                error = body.get("error")
                if error == "expired":
                    # Expected expiry; do not mark this response as a failure.
                    if self.renew_session():
                        headers["X-CSRF-Token"] = self.csrf
                        return self.create_cart_retry(product_id, variant_id, headers)
                    r.failure("cart create expired and renew failed")
                    return False
                r.failure(f"cart create 401 {error}")
                return False
            r.failure(f"cart create HTTP {r.status_code}: {r.text[:200]}")
            return False
        return False

    def create_cart_retry(self, product_id, variant_id, headers):
        with self.client.post(
            "/v2/carts",
            json={"product_id": product_id, "variant_id": variant_id},
            headers=headers,
            allow_redirects=False,
            name="/v2/carts",
            catch_response=True,
        ) as r:
            if r.status_code == 201:
                data = try_parse_json(r.text)
                if not isinstance(data, dict) or not data.get("id"):
                    r.failure("cart create retry missing id")
                    return False
                self.cart_id = str(data.get("id"))
                self.cart_etag = r.headers.get("ETag")
                self.csrf = data.get("csrf", self.csrf)
                return True
            r.failure(f"cart create retry HTTP {r.status_code}: {r.text[:200]}")
            return False

    def create_reservation(self):
        headers = {"X-CSRF-Token": self.csrf}
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=headers,
            allow_redirects=False,
            name="/v2/reservations",
            catch_response=True,
        ) as r:
            if r.status_code == 202:
                data = try_parse_json(r.text)
                if not isinstance(data, dict) or not data.get("status_url"):
                    r.failure("reservation missing status_url")
                    return None
                self.csrf = data.get("csrf", self.csrf)
                return data.get("status_url")
            if r.status_code == 401:
                body = try_parse_json(r.text) or {}
                error = body.get("error")
                if error == "expired":
                    if self.renew_session() and self.recover_cart():
                        headers["X-CSRF-Token"] = self.csrf
                        return self.create_reservation_retry(headers)
                    r.failure("reservation expired and recovery failed")
                    return None
                r.failure(f"reservation 401 {error}")
                return None
            r.failure(f"reservation HTTP {r.status_code}: {r.text[:200]}")
            return None
        return None

    def create_reservation_retry(self, headers):
        with self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=headers,
            allow_redirects=False,
            name="/v2/reservations",
            catch_response=True,
        ) as r:
            if r.status_code == 202:
                data = try_parse_json(r.text)
                if not isinstance(data, dict) or not data.get("status_url"):
                    r.failure("reservation retry missing status_url")
                    return None
                self.csrf = data.get("csrf", self.csrf)
                return data.get("status_url")
            r.failure(f"reservation retry HTTP {r.status_code}: {r.text[:200]}")
            return None

    def poll_reservation(self, status_url):
        interval = max(0.05, float(self.profile.get("poll_interval", 0.02)))
        max_polls = min(int(self.profile.get("job_polls", 5)), 5)

        for i in range(max_polls):
            if i > 0:
                time.sleep(interval)
            with self.client.get(
                status_url,
                allow_redirects=False,
                name="/v2/reservations/status",
                catch_response=True,
            ) as r:
                if r.status_code != 200:
                    r.failure(f"reservation status HTTP {r.status_code}: {r.text[:200]}")
                    return None
                data = try_parse_json(r.text)
                if not isinstance(data, dict):
                    r.failure("reservation status invalid JSON")
                    return None

                status = data.get("status")
                if status == "ready":
                    reservation_id = data.get("reservation_id")
                    if not reservation_id:
                        r.failure("reservation ready missing reservation_id")
                        return None
                    return str(reservation_id)

                if status == "pending":
                    if i == max_polls - 1:
                        r.failure("reservation not ready after max polls")
                        return None
                    # Pending is expected between polls; leave as success.
                elif status == "failed":
                    r.failure("reservation job failed")
                    return None
                else:
                    r.failure(f"unexpected reservation status {status}")
                    return None
        return None

    def renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            name="/v2/session/renew",
            catch_response=True,
        ) as r:
            if r.status_code == 200:
                data = try_parse_json(r.text)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                return True
            r.failure(f"renew HTTP {r.status_code}: {r.text[:200]}")
            return False

    def recover_cart(self):
        if not self.cart_id:
            return True
        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
