            catch_response=True,
        ) as r:
            if r.status_code == 200:
                data = try_parse_json(r.text)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                return True
            r.failure(f"recover HTTP {r.status_code}: {r.text[:200]}")
            return False

    def create_order(self, reservation_id):
        if not self.idempotency_key:
            self.idempotency_key = uuid.uuid4().hex

        payload = {"cart_id": self.cart_id, "reservation_id": reservation_id}
        headers = {
            "X-CSRF-Token": self.csrf,
            "Idempotency-Key": self.idempotency_key,
        }
        if self.cart_etag:
            headers["If-Match"] = self.cart_etag

        for attempt in range(2):
            retry_expired = False
            with self.client.post(
                "/v2/orders",
                json=payload,
                headers=headers,
                allow_redirects=False,
                name="/v2/orders",
                catch_response=True,
            ) as r:
                if r.status_code == 201:
                    data = try_parse_json(r.text)
                    if not isinstance(data, dict) or data.get("accepted") is not True:
                        r.failure("orders 201 accepted not true")
                        return False
                    self.csrf = data.get("csrf", self.csrf)
                    self.order_id = data.get("id")
                    return True

                if r.status_code == 200:
                    data = try_parse_json(r.text)
                    if not isinstance(data, dict) or data.get("accepted") is False:
                        r.failure("orders accepted:false business failure")
                        return False
                    r.failure("orders 200 unexpected accepted value")
                    return False

                if r.status_code == 401:
                    body = try_parse_json(r.text) or {}
                    error = body.get("error")
                    if error == "expired" and attempt == 0:
                        retry_expired = True
                        # Expected expiry; do not mark this response as a failure.
                    elif error == "session":
                        r.failure("orders session revoked")
                        return False
                    elif error == "denied":
                        r.failure("orders denied not expiry")
                        return False
                    else:
                        r.failure(f"orders 401 {error}")
                        return False
                else:
                    r.failure(f"orders HTTP {r.status_code}: {r.text[:200]}")
                    return False

            if retry_expired:
                if not self.renew_session():
                    return False
                if not self.recover_cart():
                    return False
                headers["X-CSRF-Token"] = self.csrf
                continue

        return False

    def perform_work(self):
        attempt = 0
        while True:
            retry_429 = False
            with self.client.post(
                "/v2/browse",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                allow_redirects=False,
                name="/v2/browse",
                catch_response=True,
            ) as r:
                if r.status_code == 200:
                    data = try_parse_json(r.text)
                    if isinstance(data, dict) and data.get("ok") is True:
                        return
                    r.failure("browse ok not true")
                    return

                if r.status_code == 429:
                    attempt += 1
                    if attempt < 4:
                        retry_429 = True
                    else:
                        # Scheduled 429 responses are not unexpected failures.
                        return

                elif r.status_code == 401:
                    body = try_parse_json(r.text) or {}
                    if body.get("error") == "expired":
                        # Expected expiry; not a failure for this work sample.
                        return
                    r.failure(f"browse 401 {body.get('error')}")
                    return

                else:
                    r.failure(f"browse HTTP {r.status_code}: {r.text[:200]}")
                    return

            if retry_429:
                time.sleep(1)


