                        if (token == null || token.isEmpty()) {
                            return session.markAsFailed();
                        }

                        Matcher idMatcher = Pattern.compile("/v2/challenges/([^/?#]+)").matcher(action);
                        if (!idMatcher.find()) {
                            return session.markAsFailed();
                        }

                        return session
                            .set("challengeAction", action)
                            .set("challengeToken", token)
                            .set("challengeId", idMatcher.group(1));
                    })
                    .exec(http("POST challenge")
                        .post("/v2/challenges/#{challengeId}")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Content-Type", "application/json")
                        .body(StringBody("{\"challenge\":\"#{challengeToken}\"}"))
                        .check(status().is(302))
                        .check(header("Location").saveAs("challengeLocation")))
                    .exec(http("GET challenge claim")
                        .get(session -> session.getString("challengeLocation"))
                        .check(status().is(200))
                        .check(jsonPath("$.grant_id").saveAs("grantId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exec(session -> {
                        if (!session.contains("grantId") || session.getString("grantId").isEmpty()) {
                            return session.markAsFailed();
                        }
                        return session;
                    })

                    // Cart creation, pass grant_id exactly once
                    .exec(http("POST create cart")
                        .post("/v2/carts")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Content-Type", "application/json")
                        .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\",\"grant_id\":\"#{grantId}\"}"))
                        .check(status().is(201))
                        .check(jsonPath("$.id").saveAs("cartId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                        .check(header("ETag").optional().saveAs("cartEtag")))
                    .exec(session -> {
                        if (!session.contains("cartId") || session.getString("cartId").isEmpty()) {
                            return session.markAsFailed();
                        }
                        return session;
                    })
                    .exec(http("GET cart")
                        .get("/v2/carts/#{cartId}")
                        .check(status().is(200))
                        .check(header("ETag").optional().saveAs("cartEtag")))

                    // PATCH quantity with 412 re-read and exactly one retry
                    .exec(session -> session.set("patchAttempt", 0).set("patchSucceeded", false))
                    .asLongAs(session ->
                        getInt(session, "patchAttempt") < 2 && !session.getBoolean("patchSucceeded"))
                    .on(
                        exec(http("PATCH cart quantity")
                            .patch("/v2/carts/#{cartId}")
                            .header("X-CSRF-Token", "#{csrf}")
                            .header("If-Match", "#{cartEtag}")
                            .header("Content-Type", "application/json")
                            .body(StringBody("{\"quantity\":1}"))
                            .check(status().in(200, 412).saveAs("patchStatus"))
                            .check(jsonPath("$.csrf").optional().saveAs("csrf")))
                            .exec(session -> {
                                int attempt = getInt(session, "patchAttempt") + 1;
                                String status = session.getString("patchStatus");
                                if ("200".equals(status)) {
                                    return session.set("patchSucceeded", true).set("patchAttempt", attempt);
                                } else if ("412".equals(status)) {
                                    return session.set("patchAttempt", attempt);
                                } else {
                                    return session.markAsFailed();
                                }
                            })
                            .doIf(session -> "412".equals(session.getString("patchStatus")))
                                .then(
                                    exec(http("GET cart for 412 retry")
                                        .get("/v2/carts/#{cartId}")
                                        .check(status().is(200))
                                        .check(header("ETag").saveAs("cartEtag")))
                                )
                    )
                    .exec(session -> {
                        if (!session.getBoolean("patchSucceeded")) {
                            return session.markAsFailed();
                        }
                        return session;
                    })

                    // Reservation with polling
                    .exec(session -> session.set("reservationAttempts", 0).set("reservationReady", false))
                    .exec(http("POST reservation")
                        .post("/v2/reservations")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Content-Type", "application/json")
                        .body(StringBody("{\"cart_id\":\"#{cartId}\"}"))
                        .check(status().is(202))
                        .check(jsonPath("$.status_url").saveAs("reservationStatusUrl"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf")))
                    .asLongAs(session ->
                        getInt(session, "reservationAttempts") < 5 && !session.getBoolean("reservationReady"))
                    .on(
                        exec(http("GET reservation status")
                            .get(session -> session.getString("reservationStatusUrl"))
                            .check(status().is(200))
                            .check(jsonPath("$.status").saveAs("reservationStatus"))
                            .check(jsonPath("$.reservation_id").optional().saveAs("reservationId"))
                            .check(jsonPath("$.csrf").optional().saveAs("csrf")))
                            .exec(session -> {
                                int attempts = getInt(session, "reservationAttempts") + 1;
                                String status = session.getString("reservationStatus");
                                if ("ready".equals(status)) {
                                    if (!session.contains("reservationId") || session.getString("reservationId").isEmpty()) {
                                        return session.markAsFailed();
                                    }
                                    return session
                                        .set("reservationAttempts", attempts)
                                        .set("reservationReady", true);
                                } else if ("pending".equals(status)) {
                                    return session.set("reservationAttempts", attempts);
                                } else {
                                    return session.markAsFailed();
                                }
                            })
                            .pause(Duration.ofMillis(100))
                    )
                    .exec(session -> {
                        if (!session.getBoolean("reservationReady")) {
                            return session.markAsFailed();
                        }
                        return session;
                    })

                    // Commit exactly one order per journey
                    .exec(session -> session.set("idempotencyKey", "order-" + session.getString("cartId")))
                    .exec(http("POST order")
                        .post("/v2/orders")
                        .header("X-CSRF-Token", "#{csrf}")
                        .header("Content-Type", "application/json")
                        .header("If-Match", "#{cartEtag}")
                        .header("Idempotency-Key", "#{idempotencyKey}")
                        .body(StringBody("{\"cart_id\":\"#{cartId}\",\"reservation_id\":\"#{reservationId}\"}"))
                        .check(status().in(200, 201).saveAs("orderStatus"))
                        .check(jsonPath("$.accepted").optional().saveAs("orderAccepted"))
                        .check(jsonPath("$.id").optional().saveAs("orderId"))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exec(session -> {
                        String status = session.getString("orderStatus");
                        String accepted = session.contains("orderAccepted")
                            ? String.valueOf(session.get("orderAccepted"))
                            : null;

                        if ("201".equals(status) && "true".equals(accepted)) {
                            return session;
                        }
                        if ("200".equals(status) && "false".equals(accepted)) {
                            return session.markAsFailed();
                        }
                        return session.markAsFailed();
                    })
            );

    {
        setUp(
            scn.injectOpen(atOnceUsers(2))
        ).protocols(httpProtocol);
    }
}

import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const USER = `bench-${__VU}`;
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    main: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '180s',
    },
  },
};

let csrf = '';
let cartId = null;
let cartEtag = null;

function resolveUrl(value) {
  if (!value) return null;
  if (/^https?:\/\//i.test(value)) return value;
  if (value.startsWith('/')) return BASE_URL + value;
  return BASE_URL + '/' + value;
}

function safeJson(response) {
  try {
    return response.json();
  } catch (e) {
    return null;
  }
}

function must(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
  return true;
}

function decodeEntities(value) {
  return value
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function extractInputValue(html, name) {
  const inputRegex = new RegExp(
    `<input\\b[^>]*\\bname\\s*=\\s*["']\\s*${name}\\s*["'][^>]*>`,
    'i'
  );
  const inputMatch = html.match(inputRegex);
  if (!inputMatch) return null;

  const tag = inputMatch[0];
  const quotedValue = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
  if (quotedValue) return decodeEntities(quotedValue[1]);

  const unquotedValue = tag.match(/\bvalue\s*=\s*([^\s>]+)/i);
  if (unquotedValue) return decodeEntities(unquotedValue[1]);

  return '';
}

function extractChallengeForm(html) {
  const formRegex = /<form\b[^>]*\baction\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))[^>]*>/gi;
  let match;

  while ((match = formRegex.exec(html)) !== null) {
    const action = match[1] || match[2] || match[3];
    if (!action || action.indexOf('/v2/challenges/') === -1) continue;

    const challenge = extractInputValue(html, 'challenge');
    if (challenge !== null && challenge !== undefined) {
      return {
        action: decodeEntities(action),
        challenge: challenge,
      };
    }
  }

  return null;
}

function findInStockVariant(data) {
  if (!data || !data.data || !Array.isArray(data.data.products)) return null;

  for (const product of data.data.products) {
    if (!product || !product.id || !Array.isArray(product.variants)) continue;

    for (const variant of product.variants) {
      if (variant && variant.id && variant.in_stock) {
        return {
          product_id: product.id,
          variant_id: variant.id,
        };
      }
    }
  }

  return null;
}

function getEtag(response) {
  return response.headers['Etag'] || response.headers['ETag'] || response.headers['etag'];
}

function getLocation(response) {
  return response.headers['Location'] || response.headers['location'];
}

function renewAndRecover() {
  const renewRes = http.post(
    `${BASE_URL}/v2/session/renew`,
    '{}',
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
    }
  );

  must(
    renewRes.status === 200 || renewRes.status === 201,
    `session renew failed: ${renewRes.status}, body ${renewRes.body}`
  );

  const renewData = safeJson(renewRes);
  if (renewData && renewData.csrf) csrf = renewData.csrf;

  if (cartId) {
    const recoverRes = http.post(
      `${BASE_URL}/v2/carts/${cartId}/recover`,
      '{}',
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': csrf,
        },
        redirects: 0,
      }
    );

    must(
      recoverRes.status === 200 || recoverRes.status === 201 || recoverRes.status === 204,
      `cart recover failed: ${recoverRes.status}, body ${recoverRes.body}`
    );

    const recoverData = safeJson(recoverRes);
    if (recoverData && recoverData.csrf) csrf = recoverData.csrf;

    const etag = getEtag(recoverRes);
    if (etag) cartEtag = etag;
  }
}

function authRequest(method, url, payload, extraHeaders = {}) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
    ...extraHeaders,
  };

  let response = http.request(method, url, JSON.stringify(payload), {
    headers: headers,
    redirects: 0,
  });

  if (response.status === 401) {
    const errorData = safeJson(response);

    if (errorData && errorData.error === 'expired') {
      renewAndRecover();
      headers['X-CSRF-Token'] = csrf;
      response = http.request(method, url, JSON.stringify(payload), {
        headers: headers,
        redirects: 0,
      });
    } else if (errorData && errorData.error === 'session') {
      throw new Error(`session revoked during ${method} ${url}`);
    } else if (errorData && errorData.error === 'denied') {
      throw new Error(`denied during ${method} ${url}`);
    }
  }

  return response;
}

function login() {
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  const formOk = check(formRes, {
    'login-form status 200': (r) => r.status === 200,
  });
  must(formOk, `login-form returned ${formRes.status}`);

  const loginCsrf = extractInputValue(formRes.body, 'csrf');
  must(loginCsrf !== null && loginCsrf !== '', `login csrf not found in form`);
  csrf = loginCsrf;

  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: USER, password: PASSWORD, csrf: loginCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    }
  );

  let loginData = null;

  if (loginRes.status === 302) {
    const location = getLocation(loginRes);
    must(location, `login returned 302 without Location`);

    const followRes = http.get(resolveUrl(location), { redirects: 0 });
    const followOk = check(followRes, {
      'login-follow status 200': (r) => r.status === 200,
    });
    must(followOk, `login follow returned ${followRes.status}`);
    loginData = safeJson(followRes);
  } else {
    must(
      loginRes.status === 200 || loginRes.status === 201,
      `login returned ${loginRes.status}, body ${loginRes.body}`
    );
    loginData = safeJson(loginRes);
  }

  must(loginData, `login response was not JSON: ${loginRes.status}`);
  if (loginData.csrf) csrf = loginData.csrf;
  must(loginData.user != null, `login response missing user`);
}

function selectProduct() {
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  const catalogOk = check(catalogRes, {
    'catalog status 200': (r) => r.status === 200,
  });
  must(catalogOk, `catalog returned ${catalogRes.status}`);

  let found = findInStockVariant(safeJson(catalogRes));

  if (!found) {
    let next = '/v2/catalog/page';
    for (let i = 0; i < 3 && !found; i++) {
      const pageRes = http.get(resolveUrl(next), { redirects: 0 });
      const pageOk = check(pageRes, {
        'catalog page status 200': (r) => r.status === 200,
      });
      must(pageOk, `catalog page returned ${pageRes.status}`);

      const pageData = safeJson(pageRes);
      found = findInStockVariant(pageData);

      if (!found && pageData && pageData.next) {
        next = pageData.next;
      } else {
        break;
      }
    }
  }

  must(found, `no in-stock product variant found`);
  return found;
}

function getGrantId() {
  const challengeFormRes = http.get(`${BASE_URL}/v2/challenge-form`, { redirects: 0 });
  const challengeFormOk = check(challengeFormRes, {
    'challenge-form status 200': (r) => r.status === 200,
  });
  must(challengeFormOk, `challenge-form returned ${challengeFormRes.status}`);

  const challenge = extractChallengeForm(challengeFormRes.body);
  must(challenge && challenge.action, `challenge action not found`);
  must(
    challenge && challenge.challenge !== null && challenge.challenge !== '',
    `challenge input value not found`
  );

  const claimRes = authRequest(
    'POST',
    resolveUrl(challenge.action),
    { challenge: challenge.challenge }
  );

  let grantData = null;

  if (claimRes.status === 302) {
    const location = getLocation(claimRes);
    must(location, `challenge claim returned 302 without Location`);

    const grantRes = http.get(resolveUrl(location), { redirects: 0 });
    const grantOk = check(grantRes, {
      'grant status 200': (r) => r.status === 200,
    });
    must(grantOk, `grant returned ${grantRes.status}`);
    grantData = safeJson(grantRes);
  } else {
    must(
      claimRes.status === 200 || claimRes.status === 201,
      `challenge claim returned ${claimRes.status}, body ${claimRes.body}`
    );
    grantData = safeJson(claimRes);
  }

  must(grantData && grantData.grant_id, `grant_id missing from challenge claim`);
  if (grantData.csrf) csrf = grantData.csrf;

  return grantData.grant_id;
}

function createCart(product, grantId) {
  const cartRes = authRequest(
    'POST',
    `${BASE_URL}/v2/carts`,
    {
      product_id: product.product_id,
      variant_id: product.variant_id,
      grant_id: grantId,
    }
  );

  must(
    cartRes.status === 201,
    `cart create returned ${cartRes.status}, body ${cartRes.body}`
  );

  const cartData = safeJson(cartRes);
  must(cartData && cartData.id, `cart create response missing id`);
  cartId = cartData.id;

  if (cartData.csrf) csrf = cartData.csrf;

  cartEtag = getEtag(cartRes);
  must(cartEtag, `cart create response missing ETag`);
}

function patchCart() {
  let patchRes = authRequest(
    'PATCH',
    `${BASE_URL}/v2/carts/${cartId}`,
    { quantity: 2 },
    { 'If-Match': cartEtag }
  );

  if (patchRes.status === 412) {
    const rereadRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, { redirects: 0 });
    const rereadOk = check(rereadRes, {
      'cart reread status 200': (r) => r.status === 200,
    });
    must(rereadOk, `cart reread returned ${rereadRes.status}`);

    cartEtag = getEtag(rereadRes);
    must(cartEtag, `cart reread missing ETag`);

    patchRes = authRequest(
      'PATCH',
      `${BASE_URL}/v2/carts/${cartId}`,
      { quantity: 2 },
      { 'If-Match': cartEtag }
    );
  }

  must(
    patchRes.status === 200 || patchRes.status === 201 || patchRes.status === 204,
    `cart patch returned ${patchRes.status}, body ${patchRes.body}`
  );

  const patchData = safeJson(patchRes);
  if (patchData && patchData.csrf) csrf = patchData.csrf;

  const newEtag = getEtag(patchRes);
  if (newEtag) cartEtag = newEtag;
}

function commitOrder() {
  const idempotencyKey = `${USER}-${__VU}-${__ITER}-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const payload = { cart_id: cartId };
  const headers = {
    'Idempotency-Key': idempotencyKey,
  };
  if (cartEtag) headers['If-Match'] = cartEtag;

  let orderRes = authRequest(
    'POST',
    `${BASE_URL}/v2/orders`,
    payload,
    headers
  );

  if (orderRes.status === 412) {
    const rereadRes = http.get(`${BASE_URL}/v2/carts/${cartId}`, { redirects: 0 });
    const rereadOk = check(rereadRes, {
      'order cart reread status 200': (r) => r.status === 200,
    });
    must(rereadOk, `order cart reread returned ${rereadRes.status}`);

    cartEtag = getEtag(rereadRes);
    must(cartEtag, `order cart reread missing ETag`);
    headers['If-Match'] = cartEtag;

    orderRes = authRequest(
      'POST',
      `${BASE_URL}/v2/orders`,
      payload,
      headers
    );
  }

  must(
    orderRes.status === 201,
    `order returned ${orderRes.status}, body ${orderRes.body}`
  );

  const orderData = safeJson(orderRes);
  must(
    orderData && orderData.accepted === true,
    `order accepted !== true: ${orderRes.body}`
  );

  if (orderData.csrf) csrf = orderData.csrf;
}

export default function () {
  csrf = '';
  cartId = null;
  cartEtag = null;

  try {
    login();
    const product = selectProduct();
    const grantId = getGrantId();
    createCart(product, grantId);
    patchCart();
    commitOrder();
  } catch (error) {
    console.error(`Journey failed for ${USER}: ${error.message}`);
    throw error;
  }
}

