        if BenchUser._account_seq >= 16:
            BenchUser._account_seq = 0
        self.username = f"bench-{BenchUser._account_seq + 1}"
        BenchUser._account_seq += 1

    def _update_csrf(self, data):
        if isinstance(data, dict):
            csrf = data.get("csrf")
            if csrf:
