    def _extract_input(self, page_html, name):
        if not page_html:
            return None
        for tag in re.findall(r'<input\b[^>]*>', page_html, re.I):
            if not re.search(r'\bname\s*=\s*["\']' + re.escape(name) + r'["\']', tag, re.I):
                continue
            vm = re.search(r'\bvalue\s*=\s*["\']([^"\']*)["\']', tag, re.I)
            if vm:
                return html.unescape(vm.group(1))
            vm = re.search(r'\bvalue\s*=\s*([^\s>]+)', tag, re.I)
            if vm:
                return html.unescape(vm.group(1))
            return ""
        return None

    def _extract_challenge_action(self, page_html):
