        pat = re.compile(
            r'(?:^|\s)' + re.escape(attr) + r'\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))',
            re.I,
        )
        m = pat.search(tag)
        if not m:
            return None
        return html.unescape(m.group(1) or m.group(2) or m.group(3) or "")

    def _extract_input(self, page_html, name):
