import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static HttpProtocolBuilder httpProtocol() {
        return http.baseUrl(BASE_URL)
                .disableFollowRedirect()
                .acceptHeader("application/json")
                .contentTypeHeader("application/json")
                .userAgentHeader("Gatling/3.15");
    }

    private static ChainBuilder login() {
        return exec(session -> session.remove("error")
                        .remove("newCsrf")
                        .remove("newEtag")
                        .remove("loginLocation")
                        .remove("loginCsrf"))
                .exec(http("Get Login Form")
                        .get("/v2/login-form")
                        .check(status().is(200))
                        .check(css("input[name='csrf']", "value").saveAs("loginCsrf")))
                .exec(http("Post Login")
                        .post("/v2/login")
                        .header("Content-Type", "application/json")
                        .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{loginCsrf}\"}"))
                        .check(status().in(200, 302))
                        .check(header("Location").optional().saveAs("loginLocation"))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                        .check(jsonPath("$.user").optional().saveAs("user")))
                .doIf(session -> session.getString("loginLocation") != null && !session.getString("loginLocation").isEmpty())
                .then(exec(http("Get Login Location")
                        .get(session -> {
                            String loc = session.getString("loginLocation");
                            return (loc.startsWith("http") || loc.startsWith("/")) ? loc : "/" + loc;
                        })
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                        .check(jsonPath("$.user").optional().saveAs("user")))
                )
                .exec(updateState());
    }

    private static ChainBuilder updateState() {
        return exec(session -> {
            String csrf = session.getString("newCsrf");
            if (csrf != null && !csrf.isEmpty()) {
                session = session.set("csrf", csrf);
            }
            String etag = session.getString("newEtag");
            if (etag != null && !etag.isEmpty()) {
                session = session.set("cartEtag", etag);
            }
            return session;
        });
    }

    private static ChainBuilder recoverSession() {
        return login();
    }

    private static ChainBuilder recoverCart() {
        return exec(http("Recover Cart")
                .post(session -> "/v2/carts/" + session.getString("cartId") + "/recover")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Content-Type", "application/json")
                .body(StringBody("{}"))
                .check(status().in(200, 201, 401))
                .check(jsonPath("$.error").optional().saveAs("error"))
                .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
                .check(header("ETag").optional().saveAs("newEtag")))
                .exec(updateState());
    }

    private static ChainBuilder withRecovery(ChainBuilder action) {
        return exec(session -> session.remove("error").remove("newCsrf").remove("newEtag"))
                .exec(action)
                .exec(updateState())
                .doIf(session -> "session".equals(session.getString("error")))
                .then(
                        exec(recoverSession())
                                .doIf(session -> session.get("cartId") != null)
                                .then(exec(recoverCart()))
                                .exec(session -> session.remove("error").remove("newCsrf").remove("newEtag"))
                                .exec(action)
                                .exec(updateState())
                )
                .exec(session -> {
                    String err = session.getString("error");
                    if ("session".equals(err) || "denied".equals(err) || "expired".equals(err)) {
                        throw new RuntimeException("unexpected auth error after recovery: " + err);
                    }
                    return session;
                });
    }

    private static ChainBuilder catalogAction() {
        return exec(http("Get Catalog")
                .get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(status().in(200, 401))
                .check(jsonPath("$.error").optional().saveAs("error"))
                .check(jsonPath("$.data.products[0].id").optional().saveAs("productId"))
                .check(jsonPath("$.data.products[0].variants[0].id").optional().saveAs("variantId")));
    }

    private static ChainBuilder validateProduct() {
        return exec(session -> {
            if (session.getString("productId") == null || session.getString("variantId") == null) {
                throw new RuntimeException("catalog did not provide a product/variant");
            }
            return session;
        });
    }

    private static ChainBuilder createCartAction() {
        return exec(http("Create Cart")
                .post("/v2/carts")
