import http from 'k6/http';
import { check, fail } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const businessFailure = new Rate('business_failure');

function getJsonBody(resp) {
  if (!resp.body || resp.body.length === 0) return {};
  try {
    return JSON.parse(resp.body);
  } catch (e) {
    return {};
  }
}

function extractCsrf(html) {
  if (!html) return null;
  const fragments = html.split(/<input/i);
  for (let i = 1; i < fragments.length; i++) {
    const fragment = fragments[i];
    if (/name\s*=\s*["']csrf["']/i.test(fragment)) {
      const valueMatch = fragment.match(/value\s*=\s*["']([^"']+)["']/i);
      if (valueMatch) return valueMatch[1];
    }
  }
  return null;
}

function getETag(resp) {
  return resp.headers['ETag'] || resp.headers['etag'] || resp.headers['Etag'] || null;
}

function reqHeaders(csrf, extra = {}) {
  const headers = {
    'X-CSRF-Token': csrf,
    'Content-Type': 'application/json',
  };
  Object.assign(headers, extra);
  return headers;
}

function parseAccountCsv(text) {
  const lines = text.trim().split('\n');
  if (lines.length < 2) throw new Error('Account CSV missing data');
  const header = lines[0].split(',').map((s) => s.trim());
  const values = lines[1].split(',').map((s) => s.trim());
  const account = {};
  for (let i = 0; i < header.length; i++) {
    account[header[i]] = values[i];
  }
  return {
    username: account.username,
    password: account.password,
    quantity: parseInt(account.quantity, 10),
    delay: parseInt(account.delay, 10),
  };
}

function loadAccountFromPaths(vuIndex) {
  const logical = vuIndex === 1 ? '/fixtures/c11-account-1.csv' : '/fixtures/c11-account-2.csv';
  const aliases = [
    logical,
    `.${logical}`,
    logical.replace('/fixtures/', 'fixtures/'),
  ];
  for (let path of aliases) {
    try {
      const text = open(path, 'r');
      return parseAccountCsv(text);
    } catch (e) {
      // try next alias
    }
  }
  return vuIndex === 1
    ? { username: 'bench', password: 'bench', quantity: 2, delay: 0 }
    : { username: 'bench', password: 'bench', quantity: 3, delay: 500 };
}

const ACCOUNT_1 = loadAccountFromPaths(1);
const ACCOUNT_2 = loadAccountFromPaths(2);

function login(username, password) {
  const formResp = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (formResp.status < 200 || formResp.status >= 300) {
    fail(`login form failed: ${formResp.status}`);
  }

  const loginCsrf = extractCsrf(formResp.body);
  if (!loginCsrf) fail('missing login csrf');

  let loginResp = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password, csrf: loginCsrf }),
    { redirects: 0, headers: reqHeaders(loginCsrf) }
  );

  if (loginResp.status === 302) {
    const location = loginResp.headers.Location;
    if (!location) fail('login 302 missing Location');
    loginResp = http.get(location, { redirects: 0, headers: reqHeaders(loginCsrf) });
  }

  const body = getJsonBody(loginResp);
  const csrf = body.csrf || extractCsrf(loginResp.body) || loginCsrf;
  return { csrf, user: body.user || username };
}

function selectProduct() {
  const catalogResp = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  if (catalogResp.status !== 200) fail(`catalog failed: ${catalogResp.status}`);

  const catalog = getJsonBody(catalogResp);
  if (catalog.data && Array.isArray(catalog.data.products)) {
    for (const product of catalog.data.products) {
      for (const variant of product.variants || []) {
        if (variant.in_stock) return { product_id: product.id, variant_id: variant.id };
      }
    }
  }

  let next = '/v2/catalog/page';
  for (let i = 0; i < 3 && next; i++) {
    const url = next.startsWith('http') ? next : `${BASE_URL}${next}`;
    const pageResp = http.get(url, { redirects: 0 });
    if (pageResp.status !== 200) break;
    const page = getJsonBody(pageResp);
    const product = page.data && (page.data.product || (page.data.products && page.data.products[0]));
    if (product) {
      for (const variant of product.variants || []) {
        if (variant.in_stock) return { product_id: product.id, variant_id: variant.id };
      }
    }
    next = page.next || null;
  }

  fail('no in-stock product found');
}

function createCart(productId, variantId, csrf, grantId = null) {
  const payload = { product_id: productId, variant_id: variantId };
  if (grantId) payload.grant_id = grantId;

  const resp = http.post(
    `${BASE_URL}/v2/carts`,
    JSON.stringify(payload),
    { redirects: 0, headers: reqHeaders(csrf) }
  );

  if (resp.status !== 201) fail(`cart creation failed: ${resp.status}`);
  return resp;
}

function patchCart(cartId, quantity, csrf, etag) {
  const payload = JSON.stringify({ quantity });
  let resp = http.patch(
    `${BASE_URL}/v2/carts/${cartId}`,
    payload,
    { redirects: 0, headers: reqHeaders(csrf, { 'If-Match': etag }) }
  );

  if (resp.status === 412) {
    const getResp = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      redirects: 0,
      headers: reqHeaders(csrf),
    });
    etag = getETag(getResp);
    const getBody = getJsonBody(getResp);
    if (getBody.csrf) csrf = getBody.csrf;

    resp = http.patch(
      `${BASE_URL}/v2/carts/${cartId}`,
      payload,
      { redirects: 0, headers: reqHeaders(csrf, { 'If-Match': etag }) }
    );
  }

  if (resp.status !== 200) fail(`cart update failed: ${resp.status}`);
  const body = getJsonBody(resp);
  if (body.csrf) csrf = body.csrf;
  return { csrf, etag: getETag(resp) || etag };
}

function reserveCart(cartId, csrf) {
  const resp = http.post(
    `${BASE_URL}/v2/reservations`,
    JSON.stringify({ cart_id: cartId }),
    { redirects: 0, headers: reqHeaders(csrf) }
  );

  if (resp.status !== 202) fail(`reservation failed: ${resp.status}`);
  let body = getJsonBody(resp);
  if (body.csrf) csrf = body.csrf;

  const statusUrl = body.status_url;
  if (!statusUrl) fail('reservation missing status_url');

  let reservationId = null;
  for (let i = 0; i < 5; i++) {
    sleep(0.1);
    const pollResp = http.get(
      statusUrl.startsWith('http') ? statusUrl : `${BASE_URL}${statusUrl}`,
      { redirects: 0, headers: reqHeaders(csrf) }
    );
    const pollBody = getJsonBody(pollResp);
    if (pollBody.csrf) csrf = pollBody.csrf;
    if (pollBody.status === 'ready') {
      reservationId = pollBody.reservation_id;
      break;
    }
    if (pollBody.status === 'failed') fail('reservation failed');
  }

  if (!reservationId) fail('reservation never became ready');
  return { csrf, reservationId };
}

function placeOrder(cartId, reservationId, csrf, etag) {
  const payload = JSON.stringify({ cart_id: cartId, reservation_id: reservationId });
  const idempotencyKey = `cart-${cartId}-${__VU}`;

  let resp = http.post(
    `${BASE_URL}/v2/orders`,
    payload,
    {
      redirects: 0,
      headers: reqHeaders(csrf, {
        'If-Match': etag,
        'Idempotency-Key': idempotencyKey,
      }),
    }
  );

  if (resp.status === 412) {
    const getResp = http.get(`${BASE_URL}/v2/carts/${cartId}`, {
      redirects: 0,
      headers: reqHeaders(csrf),
    });
    etag = getETag(getResp);
    const getBody = getJsonBody(getResp);
    if (getBody.csrf) csrf = getBody.csrf;

    resp = http.post(
      `${BASE_URL}/v2/orders`,
      payload,
      {
        redirects: 0,
        headers: reqHeaders(csrf, {
          'If-Match': etag,
          'Idempotency-Key': idempotencyKey,
        }),
      }
    );
  }

  if (resp.status !== 201 && !(resp.status === 200 && getJsonBody(resp).accepted === true)) {
    const body = getJsonBody(resp);
    if (resp.status === 200 && body.accepted === false) fail('order accepted:false is a business failure');
    fail(`order failed: ${resp.status}`);
  }

  const body = getJsonBody(resp);
  if (body.csrf) csrf = body.csrf;
  if (body.accepted !== true) fail('order not accepted');
  return { csrf, orderId: body.id };
}

function postWork(csrf) {
  let attempts = 0;
  while (attempts < 5) {
    const resp = http.post(
      `${BASE_URL}/v2/work`,
      '{}',
      { redirects: 0, headers: reqHeaders(csrf) }
    );

    if (resp.status === 200) {
      const body = getJsonBody(resp);
      if (body.ok === true) {
        businessFailure.add(false);
        return;
      }
      businessFailure.add(true);
      fail('/v2/work did not return ok');
    }

    if (resp.status === 429) {
      businessFailure.add(false);
      const retryAfter = parseInt(resp.headers['Retry-After'] || '1', 10) || 1;
      sleep(retryAfter);
      attempts++;
      continue;
    }

    businessFailure.add(true);
    fail(`/v2/work failed: ${resp.status}`);
  }

  fail('/v2/work scheduled 429 retries exhausted');
}

function postBrowse(csrf) {
  return http.post(
    `${BASE_URL}/v2/browse`,
    '{}',
    { redirects: 0, headers: reqHeaders(csrf) }
  );
}

function handleSessionRevocation(csrf, cartId) {
  const fresh = login(ACCOUNT_1.username, ACCOUNT_1.password);
  let newCsrf = fresh.csrf;

  if (cartId) {
    const recoverResp = http.post(
      `${BASE_URL}/v2/carts/${cartId}/recover`,
      '{}',
      { redirects: 0, headers: reqHeaders(newCsrf) }
    );
    if (recoverResp.status !== 200 && recoverResp.status !== 201) {
      fail(`cart recovery failed: ${recoverResp.status}`);
    }
    const body = getJsonBody(recoverResp);
    if (body.csrf) newCsrf = body.csrf;
  }
  return newCsrf;
}

function handleExpiryRenew(csrf, cartId) {
  const renewResp = http.post(
    `${BASE_URL}/v2/session/renew`,
    '{}',
    { redirects: 0, headers: reqHeaders(csrf) }
  );
  if (renewResp.status !== 200 && renewResp.status !== 201) {
    fail(`session renew failed: ${renewResp.status}`);
  }
  const body = getJsonBody(renewResp);
  let newCsrf = body.csrf || csrf;

  if (cartId) {
    const recoverResp = http.post(
      `${BASE_URL}/v2/carts/${cartId}/recover`,
      '{}',
      { redirects: 0, headers: reqHeaders(newCsrf) }
    );
    if (recoverResp.status !== 200 && recoverResp.status !== 201) {
      fail(`cart recovery failed: ${recoverResp.status}`);
    }
    const recoverBody = getJsonBody(recoverResp);
    if (recoverBody.csrf) newCsrf = recoverBody.csrf;
  }
  return newCsrf;
}

function waitForSessionInvalidation(csrf) {
  for (let i = 0; i < 20; i++) {
    const resp = postBrowse(csrf);
    if (resp.status === 401) {
      const body = getJsonBody(resp);
      if (body.error === 'session' || body.error === 'expired') {
        return { resp, body };
      }
      fail(`401 denied is not expected here: ${body.error}`);
    }

    if (resp.status === 429) {
      const retryAfter = parseInt(resp.headers['Retry-After'] || '1', 10) || 1;
      sleep(retryAfter);
    } else {
      sleep(1);
    }
  }
  fail('session was never invalidated by later login');
}

