def _parse_csrf(text):
    for tag in re.findall(r"<input\b[^>]*>", text, re.I):
        if re.search(r'\bname\s*=\s*["\']csrf["\']', tag):
            m = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", tag)
            return m.group(1) if m else None
    return None


def _parse_challenge_form(text):
    action = None
    challenge = None
    for form in re.findall(r"<form\b[^>]*>", text, re.I):
        m = re.search(r'\baction\s*=\s*["\']([^"\']*)["\']', form)
        if m and "/v2/challenges/" in m.group(1):
            action = m.group(1)
            break
    for tag in re.findall(r"<input\b[^>]*>", text, re.I):
        if re.search(r'\bname\s*=\s*["\']challenge["\']', tag):
            m = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", tag)
            challenge = m.group(1) if m else ""
            break
    return action, challenge


class BaseSharedUser(HttpUser):
    wait_time = constant(0)
    username = "bench"
    password = "bench"
    quantity = 2
    delay_ms = 0
    reverse_catalog = False
    html_layout = 0

    def on_start(self):
        if self.__class__._completed:
            raise StopUser()
        self.client.allow_redirects = False
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self.revoked_detected = False

    def _fail(self, resp, msg):
        if resp is not None:
            try:
                resp.failure(msg)
            except Exception:
                pass

    def _stop(self, resp=None, msg=None):
        self._fail(resp, msg)
        self.__class__._completed = True
        raise StopUser()

    def _json(self, resp):
        try:
            return resp.json()
        except Exception:
            return {}

    def _update_csrf(self, resp):
        data = self._json(resp)
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _login(self):
        resp = self.client.get("/v2/login-form", catch_response=True)
        if resp.status_code != 200:
            self._stop(resp, f"login-form status {resp.status_code}")
        login_csrf = _parse_csrf(resp.text)
        if not login_csrf:
            self._stop(resp, "login csrf not found")

        resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": login_csrf},
            catch_response=True,
        )
        if resp.status_code == 302:
            loc = resp.headers.get("Location")
            if not loc:
                self._stop(resp, "login 302 without Location")
            resp2 = self.client.get(loc, catch_response=True)
            if resp2.status_code != 200:
                self._stop(resp2, f"login redirect GET status {resp2.status_code}")
            self._update_csrf(resp2)
            return
        if resp.status_code == 200:
            self._update_csrf(resp)
            return
        self._stop(resp, f"login failed status {resp.status_code}")

    def _fresh_login(self):
        self.client.cookies.clear()
        self.csrf = None
        self._login()

    def _get_grant(self):
        resp = self.client.get("/v2/challenge-form", catch_response=True)
        if resp.status_code != 200:
            return None
        action, challenge = _parse_challenge_form(resp.text)
        if not action or challenge is None:
            return None
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        resp2 = self.client.post(action, json={"challenge": challenge}, headers=headers, catch_response=True)
        if resp2.status_code == 302:
            loc = resp2.headers.get("Location")
            if not loc:
                self._fail(resp2, "challenge 302 without Location")
                return None
            resp3 = self.client.get(loc, catch_response=True)
            if resp3.status_code != 200:
                self._fail(resp3, f"challenge redirect GET status {resp3.status_code}")
                return None
            self._update_csrf(resp3)
            return self._json(resp3).get("grant_id")
        if resp2.status_code in (200, 201):
            self._update_csrf(resp2)
            return self._json(resp2).get("grant_id")
        return None

    def _select_product(self):
        products = []
        resp = self.client.get("/v2/catalog", catch_response=True)
        if resp.status_code != 200:
            self._stop(resp, f"catalog status {resp.status_code}")
        data = self._json(resp)
        if isinstance(data.get("data"), dict):
            products = data["data"].get("products") or []
        else:
            products = data.get("products") or []

        if not products:
