                if resp.status_code != 200:
                    self._stop(resp, f"catalog page {i+1} status {resp.status_code}")
                data = self._json(resp)
                d = data.get("data")
                if isinstance(d, dict):
                    if "products" in d:
                        products = d.get("products") or []
                    elif "product" in d:
                        products = [d["product"]] if d.get("product") else []
                else:
                    products = data.get("products") or []
                if products:
