            headers=headers,
            catch_response=True,
        )
        if resp.status_code not in (200, 201, 204):
            self._stop(resp, f"cart recover status {resp.status_code}")
        self._update_csrf(resp)
        if resp.headers.get("ETag"):
            self.etag = resp.headers.get("ETag")

    def _recover_from_401(self, error):
        if error == "expired":
            headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
            resp = self.client.post("/v2/session/renew", json={}, headers=headers, catch_response=True)
            if resp.status_code == 200:
