            variants = product.get("variants") or []
            if variants:
                self.product_id = product.get("id")
                self.variant_id = variants[0].get("id")
                return
        self._stop(resp, "no in-stock product found")

    def _create_cart(self):
        if not self.product_id or not self.variant_id:
            self._stop(None, "product not selected before cart creation")
        payload = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id:
            payload["grant_id"] = self.grant_id
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        resp = self.client.post("/v2/carts", json=payload, headers=headers, catch_response=True)
        if resp.status_code != 201:
            self._stop(resp, f"cart create status {resp.status_code}")
        data = self._json(resp)
        self.cart_id = data.get("id")
        self.etag = resp.headers.get("ETag")
        self._update_csrf(resp)
        if not self.cart_id:
            self._stop(resp, "cart created without id")

    def _read_cart(self):
        resp = self.client.get(f"/v2/carts/{self.cart_id}", catch_response=True)
        if resp.status_code != 200:
            self._stop(resp, f"cart read status {resp.status_code}")
        self.etag = resp.headers.get("ETag") or self.etag
        self._update_csrf(resp)

    def _patch_quantity_raw(self):
        url = f"/v2/carts/{self.cart_id}"
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        if self.etag:
            headers["If-Match"] = self.etag
        resp = self.client.patch(url, json={"quantity": self.quantity}, headers=headers, catch_response=True)
        if resp.status_code == 200:
            self._update_csrf(resp)
            self.etag = resp.headers.get("ETag") or self.etag
        return resp

    def _recover_cart(self):
        if not self.cart_id:
            return
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        resp = self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers=headers,
            catch_response=True,
        )
        if resp.status_code not in (200, 201, 204):
            self._stop(resp, f"cart recover status {resp.status_code}")
        self._update_csrf(resp)
        if resp.headers.get("ETag"):
            self.etag = resp.headers.get("ETag")

    def _recover_from_401(self, error):
        if error == "expired":
            headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
            resp = self.client.post("/v2/session/renew", json={}, headers=headers, catch_response=True)
            if resp.status_code == 200:
                self._update_csrf(resp)
            else:
                self._fresh_login()
        elif error == "session":
            # Revoked by a later login: renew may fail; use a fresh login.
            self._fresh_login()
        else:
            return False
        self._recover_cart()
        return True

    def _perform_patch_expect_revoked(self):
        resp = self._patch_quantity_raw()
        if resp.status_code == 401:
            data = self._json(resp)
            error = data.get("error")
            if error != "session":
                self._stop(resp, f"expected revoked session but got error={error}")
            self.revoked_detected = True
            self._recover_from_401(error)
            resp = self._patch_quantity_raw()
            if resp.status_code == 412:
                self._read_cart()
                resp = self._patch_quantity_raw()
            if resp.status_code != 200:
                self._stop(resp, f"patch after recovery status {resp.status_code}")
            self._update_csrf(resp)
            self.etag = resp.headers.get("ETag") or self.etag
            return
        if resp.status_code == 412:
            self._stop(resp, "expected revoked session but got 412")
        if resp.status_code == 200:
            self._stop(resp, "expected revoked session but patch succeeded without revocation")
        self._stop(resp, f"unexpected patch status {resp.status_code}")

    def _reservation_raw(self):
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        if self.etag:
            headers["If-Match"] = self.etag
        return self.client.post(
            "/v2/reservations",
            json={"cart_id": self.cart_id},
            headers=headers,
            catch_response=True,
        )

    def _poll_reservation(self, status_url):
        for _ in range(5):
            gevent.sleep(0.06)
            resp = self.client.get(status_url, catch_response=True)
            if resp.status_code != 200:
                self._stop(resp, f"reservation poll status {resp.status_code}")
            data = self._json(resp)
            self._update_csrf(resp)
            status = data.get("status")
            if status == "ready":
                return data.get("reservation_id")
            if status == "pending":
                continue
            if status == "failed":
                self._stop(resp, "reservation failed")
            self._stop(resp, f"unexpected reservation status {status}")
        self._stop(None, "reservation polling exceeded")

    def _perform_reservation(self):
        resp = self._reservation_raw()
        if resp.status_code == 412:
            self._read_cart()
            resp = self._reservation_raw()
        if resp.status_code == 401:
            data = self._json(resp)
            error = data.get("error")
            if error == "denied":
                self._stop(resp, "reservation denied")
            self._recover_from_401(error)
            resp = self._reservation_raw()
            if resp.status_code == 412:
                self._read_cart()
                resp = self._reservation_raw()
            if resp.status_code != 202:
                self._stop(resp, f"reservation retry status {resp.status_code}")
        if resp.status_code != 202:
            self._stop(resp, f"reservation status {resp.status_code}")
        data = self._json(resp)
        status_url = data.get("status_url")
        self._update_csrf(resp)
        if not status_url:
            self._stop(resp, "reservation missing status_url")
        return self._poll_reservation(status_url)

    def _perform_order(self, reservation_id):
        headers = {"X-CSRF-Token": self.csrf} if self.csrf else {}
        if self.etag:
            headers["If-Match"] = self.etag
        headers["Idempotency-Key"] = f"order-{self.cart_id}"
        payload = {"cart_id": self.cart_id}
        if reservation_id:
            payload["reservation_id"] = reservation_id

        resp = self.client.post("/v2/orders", json=payload, headers=headers, catch_response=True)
        if resp.status_code == 412:
            self._read_cart()
            headers["If-Match"] = self.etag
            resp = self.client.post("/v2/orders", json=payload, headers=headers, catch_response=True)

        if resp.status_code == 401:
            data = self._json(resp)
            error = data.get("error")
            if error == "denied":
                self._stop(resp, "order denied")
            self._recover_from_401(error)
            headers["X-CSRF-Token"] = self.csrf
            if self.etag:
                headers["If-Match"] = self.etag
            resp = self.client.post("/v2/orders", json=payload, headers=headers, catch_response=True)
            if resp.status_code == 412:
                self._read_cart()
                headers["If-Match"] = self.etag
                resp = self.client.post("/v2/orders", json=payload, headers=headers, catch_response=True)

        if resp.status_code == 201:
            data = self._json(resp)
            if data.get("accepted") is True:
                self._update_csrf(resp)
                return True
            self._stop(resp, "order accepted false")
        if resp.status_code == 200:
            data = self._json(resp)
            if data.get("accepted") is True:
                self._update_csrf(resp)
                return True
            self._stop(resp, "order business failure accepted=false")
        self._stop(resp, f"order status {resp.status_code}")


class FirstUser(BaseSharedUser):
    _completed = False
    quantity = 2
    delay_ms = 0
    reverse_catalog = False
    html_layout = 0

    @task
    def journey(self):
        self._login()
        self._select_product()
        self.grant_id = self._get_grant()
        self._create_cart()

        first_ready.set()
        if not second_cart_ready.wait(timeout=20):
            self._stop()

        self._perform_patch_expect_revoked()
        reservation_id = self._perform_reservation()
        self._perform_order(reservation_id)

        self.__class__._completed = True
        first_done.set()
        if not second_done.wait(timeout=20):
            self._stop()
        raise StopUser()


class SecondUser(BaseSharedUser):
    _completed = False
    quantity = 3
    delay_ms = 500
    reverse_catalog = True
    html_layout = 1

    @task
    def journey(self):
        if not first_ready.wait(timeout=20):
            self._stop()

        self._login()
        if self.delay_ms:
            gevent.sleep(self.delay_ms / 1000.0)

        self._select_product()
        self.grant_id = self._get_grant()
        self._create_cart()
        second_cart_ready.set()

        if not first_done.wait(timeout=20):
            self._stop()

        self._perform_patch_expect_revoked()
        reservation_id = self._perform_reservation()
        self._perform_order(reservation_id)

        self.__class__._completed = True
        second_done.set()
        raise StopUser()


class ScenarioShape(LoadTestShape):
    def tick(self):
        uncompleted = (0 if FirstUser._completed else 1) + (0 if SecondUser._completed else 1)
        if uncompleted == 0:
            return None
        return (uncompleted, 1.0)
