import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

public class ModelSimulation extends Simulation {

  private static String baseUrl = System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

  private HttpProtocolBuilder httpProtocol = http
      .baseUrl(baseUrl)
      .maxRedirects(0)
      .header("Content-Type", "application/json")
      .header("X-CSRF-Token", session -> session.getString("csrf"))
      .header("If-Match", session -> session.getString("etag"))
      .header("Idempotency-Key", session -> session.getString("cart"));

  private ChainBuilder resetVars = exec(session -> session
      .set("csrf", "MISSING")
      .set("cart", "MISSING")
      .set("etag", "MISSING")
      .set("grant", "MISSING")
      .set("product", "MISSING")
      .set("variant", "MISSING")
      .set("form", "MISSING")
      .set("redirect", "false")
      .set("location", "MISSING"));

  private ChainBuilder getLoginForm = exec(
      http("GET /v2/login-form")
          .get("/v2/login-form")
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>").optional().saveAs("form"))
  );

  private ChainBuilder postLogin = exec(
      http("POST /v2/login")
          .post("/v2/login")
          .body(StringBody(session -> String.format("{\"username\":\"%s\",\"password\":\"bench\",\"csrf\":\"%s\"}",
              session.getString("username"), session.getString("form"))))
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(header("Location").optional().saveAs("location"))
          .check(header("Location").optional().transform(loc -> "true").saveAs("redirect"))
          .check(regex("\"csrf\"\\s*:").find().exists())
  );

  private ChainBuilder followLoginRedirect = exec(
      http("GET login redirect Location")
          .get(session -> session.getString("location"))
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(jsonPath("$.grant_id").optional().saveAs("grant"))
  );

  private ChainBuilder getCatalog = exec(
      http("GET /v2/catalog")
          .get("/v2/catalog")
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").optional().saveAs("product"))
          .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").optional().saveAs("variant"))
  );

  private ChainBuilder createCart = exec(
      http("POST /v2/carts")
          .post("/v2/carts")
          .body(StringBody(session -> String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\",\"grant_id\":\"%s\"}",
              session.get("product").toString(), session.get("variant").toString(), session.getString("grant"))))
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(jsonPath("$.id").optional().saveAs("cart"))
          .check(regex("\"id\"\\s*:\\s*\"cart-").find().exists())
  );

  private ChainBuilder createOrder = exec(
      http("POST /v2/orders")
          .post("/v2/orders")
          .body(StringBody(session -> String.format("{\"cart_id\":\"%s\"}", session.getString("cart"))))
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(regex("\"accepted\"\\s*:\\s*true").find().exists())
  );

  private ChainBuilder initUsername = exec(session -> {
    long uid = session.userId();
    long n = Math.floorMod(uid, 16L) + 1L;
    return session.set("username", "bench-" + n);
  });

  private ScenarioBuilder scn = scenario("CookieCSRFShop")
      .exec(initUsername)
      .repeat(2, "iteration").on(
          exec(flushCookieJar()),
          exec(resetVars),
          exec(getLoginForm),
          exec(postLogin),
          doIf(session -> "true".equals(session.getString("redirect"))).then(
              exec(followLoginRedirect)
          ),
          exec(getCatalog),
          exec(createCart),
          exec(createOrder)
      );

  {
    setUp(
        scn.injectOpen(atOnceUsers(2))
    ).protocols(httpProtocol);
  }
}
