import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');

let csrf = '';
let grant = null;
let cartId = null;
let etag = null;
let username = '';
let productId = null;
let variantId = null;

function resolveUrl(location) {
  if (/^https?:\/\//i.test(location)) return location;
  return `${BASE_URL}${location.startsWith('/') ? '' : '/'}${location}`;
}

function getHeader(res, name) {
  let value = res.headers[name] || res.headers[String(name).toLowerCase()] || res.headers[String(name).toUpperCase()];
  if (Array.isArray(value)) value = value[0];
  return value || null;
}

function safeJsonBody(res) {
  try { return res.json(); } catch (e) { return null; }
}

function updateCsrfFromBody(body) {
  if (body && typeof body.csrf === 'string' && body.csrf.trim().length > 0) {
    csrf = body.csrf;
  }
}

function extractCsrfFromForm(html) {
  if (!html) return null;
  const inputTagRegex = /<input\b[^>]*>/gi;
  let tagMatch;
  while ((tagMatch = inputTagRegex.exec(html)) !== null) {
    const tag = tagMatch[0];
    if (!/\bname\s*=\s*(?:"csrf"|'csrf')/i.test(tag)) continue;
    const quotedValue = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)')/i);
    if (quotedValue) return quotedValue[1] !== undefined ? quotedValue[1] : quotedValue[2];
    const unquoted = tag.match(/\bvalue\s*=\s*([^\s>]+)/i);
    if (unquoted) return unquoted[1];
  }
  const fallback = html.match(/<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  return fallback ? fallback[1] : null;
}

function getAuthError(res) {
  if (res.status !== 401) return null;
  const body = safeJsonBody(res);
  return body && body.error ? body.error : null;
}

function getETag(headers) {
  return headers['ETag'] || headers['etag'] || headers['ETAG'] || null;
}

function login(initialCsrf) {
  const res = http.post(`${BASE_URL}/v2/login`, JSON.stringify({ username, password: 'bench', csrf: initialCsrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  if (res.status === 200) {
    const body = safeJsonBody(res);
    updateCsrfFromBody(body);
    return Boolean(csrf);
  }

  if (res.status === 302) {
    const location = getHeader(res, 'Location');
    if (!location) return false;
    const url = resolveUrl(location);
    const locRes = http.get(url, { redirects: 0 });
    if (locRes.status < 200 || locRes.status >= 300) return false;
    const body = safeJsonBody(locRes);
    updateCsrfFromBody(body);
    if (body && body.grant_id !== undefined && body.grant_id !== null && body.grant_id !== '') {
      grant = body.grant_id;
    }
    return Boolean(csrf);
  }

  return false;
}

function freshLogin() {
  http.cookieJar().clear(BASE_URL);
  const formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  const loginCsrf = extractCsrfFromForm(formRes.body);
  if (!loginCsrf) return false;
  csrf = loginCsrf;
  return login(loginCsrf);
}

function renewSession() {
  if (!csrf) return false;
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (res.status === 200) {
    const body = safeJsonBody(res);
    updateCsrfFromBody(body);
    return true;
  }
  return false;
}

function recoverCart() {
  if (!cartId || !csrf) return false;
  const res = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
    redirects: 0,
  });
  if (res.status === 200) {
    const body = safeJsonBody(res);
    updateCsrfFromBody(body);
    return true;
  }
  return false;
}

function createCartWithRetry() {
  const attempt = () => {
    const payload = { product_id: productId, variant_id: variantId };
    if (grant !== null && grant !== 'MISSING' && grant !== '') payload.grant_id = grant;
    return http.post(`${BASE_URL}/v2/carts`, JSON.stringify(payload), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
      redirects: 0,
    });
  };

  const parseSuccess = (res) => {
    if (res.status !== 201) return null;
    const body = safeJsonBody(res);
    updateCsrfFromBody(body);
    cartId = body && body.id ? body.id : null;
    etag = getETag(res.headers);
    return cartId;
  };

  let res = attempt();
  let id = parseSuccess(res);
  if (id) return true;

  if (res.status === 401) {
    const err = getAuthError(res);
    if (err === 'expired') {
      if (!renewSession()) {
        if (!freshLogin()) return false;
      }
      res = attempt();
      id = parseSuccess(res);
      return Boolean(id);
    } else if (err === 'session') {
      if (!freshLogin()) return false;
      res = attempt();
      id = parseSuccess(res);
      return Boolean(id);
    } else if (err === 'denied') {
      return false;
    }
  }

  return false;
}

function placeOrderWithRetry() {
  const attempt = () => {
    const payload = { cart_id: cartId };
    const headers = {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'Idempotency-Key': cartId,
    };
    if (etag) headers['If-Match'] = etag;
    return http.post(`${BASE_URL}/v2/orders`, JSON.stringify(payload), {
      headers,
      redirects: 0,
    });
  };

  const parseSuccess = (res) => {
    if (res.status !== 201 && res.status !== 200) return false;
    const body = safeJsonBody(res);
    updateCsrfFromBody(body);
    return body && body.accepted === true;
  };

  let res = attempt();
  let accepted = parseSuccess(res);
  if (accepted) return true;
  if (res.status === 200) return false;

  if (res.status === 401) {
    const err = getAuthError(res);
    if (err === 'expired') {
      if (!renewSession()) {
        if (!freshLogin()) return false;
      }
      if (cartId) recoverCart();
      res = attempt();
      accepted = parseSuccess(res);
      return accepted;
    } else if (err === 'session') {
      if (!freshLogin()) return false;
      if (cartId) recoverCart();
      res = attempt();
      accepted = parseSuccess(res);
      return accepted;
    } else if (err === 'denied') {
      return false;
    }
  }

  return false;
}

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
    },
  },
};

export default function () {
  csrf = '';
  grant = null;
  cartId = null;
  etag = null;
  productId = null;
  variantId = null;
  username = `bench-${__VU}`;

  http.cookieJar().clear(BASE_URL);

  const loginFormRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  const formCsrf = extractCsrfFromForm(loginFormRes.body);
  if (!formCsrf) {
    check(false, { 'login form csrf': (v) => v });
    throw new Error('login form did not contain csrf input');
  }
  csrf = formCsrf;

  const loginOk = login(formCsrf);
  if (!loginOk || !csrf) {
    check(false, { 'login succeeded': (v) => v });
    throw new Error('login failed');
  }
  check(true, { 'login succeeded': (v) => v });

  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, { redirects: 0 });
  const catalogBody = safeJsonBody(catalogRes);
  const products = catalogBody && catalogBody.data && catalogBody.data.products ? catalogBody.data.products : [];

  let selected = null;
  for (const p of products) {
    if (p && p.id && p.variants && p.variants.length > 0 && p.variants[0].in_stock === true) {
      selected = { product_id: p.id, variant_id: p.variants[0].id };
      break;
    }
  }
  if (!selected) {
    check(false, { 'catalog has available product': (v) => v });
    throw new Error('catalog did not contain an in-stock product');
  }
  productId = selected.product_id;
  variantId = selected.variant_id;
  check(true, { 'catalog product available': (v) => v });

  const cartOk = createCartWithRetry();
  if (!cartOk || !cartId) {
    check(false, { 'cart created': (v) => v });
    throw new Error('cart creation failed');
  }
  check(true, { 'cart created': (v) => v });
  check(cartId.startsWith('cart-'), { 'cart id prefix': (v) => v });

  const orderAccepted = placeOrderWithRetry();
  if (!orderAccepted) {
    check(false, { 'order accepted': (v) => v });
    throw new Error('order was not accepted');
  }
  check(true, { 'order accepted': (v) => v });
}

