import itertools
import os
import re

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

_USER_IDS = itertools.count(1)


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000").rstrip("/")
    wait_time = constant(0)

    iterations = 2

    def on_start(self):
        self.user_num = next(_USER_IDS)
        self.completed_iterations = 0
        self.reset_state()

    def reset_state(self):
        self.csrf = "MISSING"
        self.cart = "MISSING"
        self.etag = "MISSING"
        self.grant = "MISSING"
        self.product = "MISSING"
        self.variant = "MISSING"
        self.login_csrf = "MISSING"
        self.has_cart = "false"
        self.location = None
        self.redirect = False

    @task
    def journey(self):
        if self.completed_iterations >= self.iterations:
            raise StopUser()
        self.completed_iterations += 1
        self.run_journey()

    def run_journey(self):
        self.client.cookies.clear()
        self.reset_state()
        self._get_login_form()
        self._post_login()
        if self.redirect:
            self._get_location()
        self._get_catalog()
        self._post_cart()
        self._post_order()

    def _headers(self):
        headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": self.csrf,
        }
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag
        if self.cart != "MISSING":
            headers["Idempotency-Key"] = self.cart
        return headers

    def _json(self, response):
        try:
            data = response.json()
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    def _check_status(self, response):
        if response.status_code >= 400:
            response.failure(f"HTTP error {response.status_code}")
            return True
        return False

    def _extract_csrf(self, response):
        data = self._json(response)
        if isinstance(data, dict) and "csrf" in data:
            self.csrf = data["csrf"]

    def _extract_grant(self, response):
        data = self._json(response)
        if isinstance(data, dict) and "grant_id" in data:
            self.grant = data["grant_id"]

    def _extract_etag(self, response):
        etag = response.headers.get("ETag") or response.headers.get("Etag")
        if etag:
            self.etag = etag

    def _extract_form(self, response):
        m = re.search(
            r"""<input(?=[^>]*\bname=['"]csrf['"])(?=[^>]*\bvalue=['"]([^'"]+)['"])[^>]*>""",
            response.text,
        )
        if m:
            self.login_csrf = m.group(1)

    def _get_login_form(self):
        with self.client.get(
            "/v2/login-form",
            headers=self._headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/login-form",
        ) as r:
            self._check_status(r)
            self._extract_form(r)
            self._extract_etag(r)

    def _post_login(self):
        payload = {
            "username": f"bench-{self.user_num}",
            "password": "bench",
            "csrf": self.login_csrf,
        }
        with self.client.post(
            "/v2/login",
            json=payload,
            headers=self._headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        ) as r:
            failed = self._check_status(r)
            if not failed and not re.search(r'"csrf"\s*:', r.text):
                r.failure("login response missing csrf")

            self._extract_csrf(r)
            self._extract_etag(r)

            location = r.headers.get("Location")
            if location:
                self.location = location
                self.redirect = True

    def _get_location(self):
        if not self.location:
            return
        with self.client.get(
            self.location,
            headers=self._headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/location",
        ) as r:
            self._check_status(r)
            self._extract_csrf(r)
            self._extract_grant(r)
            self._extract_etag(r)

    def _get_catalog(self):
        with self.client.get(
            "/v2/catalog",
            headers=self._headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/catalog",
        ) as r:
            self._check_status(r)
            self._extract_csrf(r)

            data = self._json(r)
            products = (data.get("data") or {}).get("products", [])
            for product in products:
                variants = product.get("variants", [])
                if variants and variants[0].get("in_stock") is True:
                    self.product = product.get("id")
                    self.variant = variants[0].get("id")
                    break

            self._extract_etag(r)

    def _post_cart(self):
        payload = {
            "product_id": self.product,
            "variant_id": self.variant,
            "grant_id": self.grant,
        }
        with self.client.post(
            "/v2/carts",
            json=payload,
            headers=self._headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/carts",
        ) as r:
            failed = self._check_status(r)
            if not failed and not re.search(r'"id"\s*:\s*"cart-', r.text):
                r.failure("cart creation missing cart id")

            self._extract_csrf(r)
            data = self._json(r)
            if isinstance(data, dict) and "id" in data:
                self.cart = data["id"]
                self.has_cart = "true"
            self._extract_etag(r)

    def _post_order(self):
        payload = {"cart_id": self.cart}
        with self.client.post(
            "/v2/orders",
            json=payload,
            headers=self._headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/orders",
        ) as r:
            failed = self._check_status(r)
            if not failed and not re.search(r'"accepted"\s*:\s*true', r.text):
                r.failure("order not accepted")

            self._extract_csrf(r)
            self._extract_etag(r)


class ShopShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._spawned = False

    def tick(self):
        current = self.get_current_user_count()

        if not self._spawned:
            if current < 2:
                return (2, 2)
