    ).exec(mergeCsrfGrant);

    ChainBuilder followChallengeRedirect = exec(http("GET challenge redirect")
            .get(session -> session.getString("challengeLocation"))
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .check(status().is(200))
            .check(jsonPath("$.csrf").optional().saveAs("tmpCsrf"))
            .check(jsonPath("$.grant_id").optional().saveAs("tmpGrant"))
    ).exec(mergeCsrfGrant);

    ChainBuilder challengeFlow = exec(challengeForm)
            .exec(postChallenge)
            .doIf(session -> session.contains("challengeLocation") && !session.getString("challengeLocation").isEmpty())
            .then(followChallengeRedirect);

