            .header("Content-Type", "application/json")
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .header("If-Match", session -> session.getString("etag"))
            .header("Idempotency-Key", session -> session.getString("cart"))
            .body(StringBody("{\"cart_id\":\"${cart}\"}"))
            .check(status().is(201))
            .check(jsonPath("$.accepted").is("true"))
            .check(jsonPath("$.csrf").optional().saveAs("tmpCsrf"))
    ).exec(mergeCsrfOnly);

    ChainBuilder journey = exec(flushCookieJar())
            .exec(initSession)
            .exec(getLoginForm)
            .exec(login)
            .doIf(session -> session.contains("location") && !session.getString("location").isEmpty())
            .then(followLoginRedirect)
