```javascript
import http from 'k6/http';
import { check, fail } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

let csrf;
let formCsrf;
let grant;
let cart;
let etag;
let username;

function getHeader(res, name) {
  const lower = name.toLowerCase();
  for (const key of Object.keys(res.headers)) {
    if (key.toLowerCase() === lower) {
      return res.headers[key];
    }
  }
  return undefined;
}

function safeJson(res) {
  try {
    if (!res.body) return null;
    return res.json();
  } catch (e) {
    return null;
  }
}

function resolveUrl(u) {
  if (/^https?:\/\//i.test(u)) return u;
  return new URL(u, BASE_URL).toString();
}

function extractInputValue(html, name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(
    `<input(?=[^>]*\\bname\\s*=\\s*["']${escaped}["'])(?=[^>]*\\bvalue\\s*=\\s*["']([^"']+)["'])[^>]*>`,
    'i'
  );
  const m = html.match(re);
  return m ? m[1] : null;
}

function extractFormAction(html) {
  const re = /<form(?=[^>]*\baction\s*=\s*["']([^"']+)["'])[^>]*>/i;
  const m = html.match(re);
  return m ? m[1] : null;
}

function jsonHeaders(token, extra = {}) {
  const headers = { 'Content-Type': 'application/json', ...extra };
  if (token) headers['X-CSRF-Token'] = token;
  return headers;
}

function updateEtag(res) {
  const h = getHeader(res, 'ETag');
  if (h) etag = h;
}

function updateCsrfAndGrant(res) {
  const body = safeJson(res);
  if (!body) return;
  if (typeof body.csrf === 'string' && body.csrf.length > 0) csrf = body.csrf;
  if (typeof body.grant_id === 'string' && body.grant_id.length > 0) grant = body.grant_id;
}

function parseError(res) {
  if (res.status !== 401) return null;
  const body = safeJson(res);
  if (body && typeof body.error === 'string') return body.error;
  return null;
}

function findStock(body) {
  if (!body || !body.data || !body.data.products) return null;
  for (const p of body.data.products) {
    if (
      p &&
      p.id &&
      Array.isArray(p.variants) &&
      p.variants.length > 0 &&
      p.variants[0].in_stock === true
    ) {
      return { product_id: p.id, variant_id: p.variants[0].id };
    }
  }
  return null;
}

function handleChallengeForm(html) {
  const action = extractFormAction(html);
  const challengeValue = extractInputValue(html, 'challenge');

  check(action, { 'challenge form action': (v) => v != null }) || fail('challenge action missing');
  check(challengeValue, { 'challenge value': (v) => v != null }) || fail('challenge value missing');
  if (!csrf) fail('missing csrf before challenge POST');

  let res = http.post(resolveUrl(action), JSON.stringify({ challenge: challengeValue }), {
    redirects: 0,
    headers: jsonHeaders(csrf),
    timeout: '5s',
  });

  check(res, {
    'challenge POST status 200 or 302': (r) => r.status === 200 || r.status === 302,
  }) || fail('challenge POST failed');

  const location = getHeader(res, 'Location');
  if (location) {
    res = http.get(resolveUrl(location), { redirects: 0, timeout: '5s' });
    check(res, { 'challenge redirect status 200': (r) => r.status === 200 }) || fail('challenge redirect GET failed');
    updateCsrfAndGrant(res);
  } else {
    updateCsrfAndGrant(res);
  }
}

function login() {
  let res = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0, timeout: '5s' });
  check(res, { 'login form status 200': (r) => r.status === 200 }) || fail('login form failed');

  formCsrf = extractInputValue(res.body, 'csrf');
  check(formCsrf, { 'login form csrf': (v) => v != null && v.length > 0 }) || fail('login form csrf missing');

  username = `bench-${__VU}`;

  res = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: 'bench', csrf: formCsrf }),
    {
      redirects: 0,
      headers: { 'Content-Type': 'application/json' },
      timeout: '5s',
    }
  );

  check(res, { 'login status 200 or 302': (r) => r.status === 200 || r.status === 302 }) || fail('login failed');

  let body = safeJson(res);
  if (body && body.csrf) csrf = body.csrf;

  const location = getHeader(res, 'Location');
  if (location) {
    res = http.get(resolveUrl(location), { redirects: 0, timeout: '5s' });
    check(res, { 'login redirect status 200': (r) => r.status === 200 }) || fail('login redirect GET failed');

    updateCsrfAndGrant(res);

    if (!grant && /name\s*=\s*["']challenge["']/i.test(res.body)) {
      handleChallengeForm(res.body);
    }
  }

  if (body && body.csrf) csrf = body.csrf;
}

function handle401(error, currentCart, currentCsrf) {
  if (error === 'expired') {
    let res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      redirects: 0,
      headers: jsonHeaders(currentCsrf),
      timeout: '5s',
    });

    if (res.status === 200) {
      const body = safeJson(res);
      if (body && body.csrf) currentCsrf = body.csrf;
    } else {
      fail('session renew failed for expired token');
    }

    if (currentCart) {
      res = http.post(`${BASE_URL}/v2/carts/${currentCart}/recover`, '{}', {
        redirects: 0,
        headers: jsonHeaders(currentCsrf),
        timeout: '5s',
      });
      updateEtag(res);
      const body = safeJson(res);
      if (body && body.csrf) currentCsrf = body.csrf;
    }

    return currentCsrf;
  }

  if (error === 'session') {
    let res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
      redirects: 0,
      headers: jsonHeaders(currentCsrf),
      timeout: '5s',
    });

    if (res.status === 200) {
      const body = safeJson(res);
      if (body && body.csrf) currentCsrf = body.csrf;
    } else {
      let formRes = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0, timeout: '5s' });
      const newFormCsrf = extractInputValue(formRes.body, 'csrf');

      const loginRes = http.post(
        `${BASE_URL}/v2/login`,
        JSON.stringify({ username, password: 'bench', csrf: newFormCsrf }),
        {
          redirects: 0,
          headers: { 'Content-Type': 'application/json' },
