    ]
    for pattern in patterns:
        m = re.search(pattern, text, re.I | re.S)
        if m:
            return m.group(1)
    return None


_USER_IDS = itertools.count(1)


class ShoppingUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

