        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if self.etag:
            headers["If-Match"] = self.etag
        if idempotency_key:
            headers["Idempotency-Key"] = idempotency_key
        return headers

    def _update_csrf(self, data):
        if isinstance(data, dict):
            csrf = data.get("csrf")
            if csrf:
                self.csrf = csrf

    @task
    def journey(self):
        if self.journey_count >= 2:
            raise StopUser()
        self.journey_count += 1
        self.clear_state()

        # 1. Get login form
        r = self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            catch_response=True,
            name="/v2/login-form",
        )
        if r.status_code != 200:
            r.failure(f"Expected login form 200, got {r.status_code}")
