            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": login_csrf},
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        )
        if r.status_code not in (200, 302):
            r.failure(f"Expected login 200/302, got {r.status_code}")
            return

        data = {}
        try:
            data = r.json()
        except ValueError:
            data = {}
        if "csrf" in data:
            self.csrf = data["csrf"]

        location = r.headers.get("Location")
        if not location:
            r.failure("Login redirect Location missing")
            return

        # 3. Follow the login redirect exactly once
        r_red = self.client.get(
            location,
            allow_redirects=False,
            catch_response=True,
            name="GET login redirect",
        )
