            json=cart_body,
            headers=self._auth_headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/carts",
        )
        if r_cart.status_code != 201:
            r_cart.failure(f"Expected cart 201, got {r_cart.status_code}")
            return
        try:
            cart_data = r_cart.json()
        except ValueError:
            r_cart.failure("Invalid cart JSON")
            return
        if "id" not in cart_data or not cart_data["id"]:
            r_cart.failure("Cart creation missing id")
            return
        self.cart_id = cart_data["id"]
        if "csrf" in cart_data:
            self.csrf = cart_data["csrf"]
        etag = r_cart.headers.get("ETag")
        if etag:
            self.etag = etag

        # 6. Commit one order
        order_body = {"cart_id": self.cart_id}
        r_order = self.client.post(
            "/v2/orders",
            json=order_body,
            headers=self._auth_headers(idempotency_key=self.cart_id),
            allow_redirects=False,
            catch_response=True,
            name="/v2/orders",
        )
        if r_order.status_code == 201:
            try:
                order_data = r_order.json()
            except ValueError:
                r_order.failure("Invalid order JSON")
                return
            if order_data.get("accepted") is not True:
                r_order.failure("Order accepted not true")
                return
            if "csrf" in order_data:
                self.csrf = order_data["csrf"]
        elif r_order.status_code == 200:
            r_order.failure("Order returned HTTP 200 accepted false")
            return
        else:
            r_order.failure(f"Expected order 201, got {r_order.status_code}")
            return


class RedirectShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._started = False

    def tick(self):
        runner = getattr(self, "runner", None)
        if self._started and runner is not None and runner.user_count == 0:
            return None
        self._started = True
        return (2, 1)
