                self.csrf = order_data["csrf"]


class RedirectShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False

    def tick(self):
        runner = getattr(self, "runner", None)

        if self.started and runner is not None and runner.user_count == 0:
