        .check(status().is(200))
        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        .check(header("ETag").optional().saveAs("etag"))
    );

    private ChainBuilder patchCartWithRetry = exec(patchCart)
        .doIf(session ->
            session.get("patchStatus") != null
                && session.get("patchStatus").toString().equals("412")
        ).then(patchRetry);

    private ChainBuilder postOrder = exec(http("POST /v2/orders")
        .post("/v2/orders")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{etag}")
        .header("Idempotency-Key", "#{cart}")
        .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
        .check(status().is(201))
        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        .check(regex("\"accepted\"\\s*:\\s*true").exists())
    );

    private ScenarioBuilder scn = scenario("ModelScenario")
        .feed(jsonFile("/fixtures/accounts.json").circular())
        .exec(setUpAccount)
        .repeat(ITERATIONS).on(
            exec(flushCookieJar())
                .exec(getLoginForm)
                .exec(postLogin)
                .exec(followLocation)
                .exec(getCatalog)
                .exec(createCart)
                .exec(patchCartWithRetry)
                .exec(postOrder)
        );

    {
        setUp(scn.injectOpen(atOnceUsers(USERS))).protocols(httpProtocol);
    }
}
