import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const ACCOUNTS = JSON.parse(open('/fixtures/accounts.json'));

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function makeGet(url, jar) {
  return http.get(url, {
    jar,
    redirects: 0,
    timeout: '5s',
  });
}

function makePost(url, body, headers, jar) {
  return http.post(url, body || '{}', {
    headers: Object.assign({ 'Content-Type': 'application/json' }, headers || {}),
    jar,
    redirects: 0,
    timeout: '5s',
  });
}

function makePatch(url, body, headers, jar) {
  return http.patch(url, body, {
    headers: Object.assign({ 'Content-Type': 'application/json' }, headers || {}),
    jar,
    redirects: 0,
    timeout: '5s',
  });
}

function getHeader(res, name) {
  if (!res || !res.headers) return null;
  const wanted = name.toLowerCase();
  for (const key of Object.keys(res.headers)) {
    if (key.toLowerCase() === wanted) {
      return res.headers[key];
    }
  }
  return null;
}

function parseJson(res) {
  if (!res || !res.body) return null;
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function getError(res) {
  const body = parseJson(res);
  if (body && body.error) return body.error;
  const text = String(res && res.body || '');
  const m = /"error"\s*:\s*"([^"]+)"/.exec(text);
  return m ? m[1] : null;
}

function extractFormCsrf(html) {
  if (!html) return null;
  const inputRe = /<input[^>]*>/gi;
  let match;
  while ((match = inputRe.exec(html)) !== null) {
    const tag = match[0];
    if (/name\s*=\s*["']csrf["']/i.test(tag)) {
      let value = /value\s*=\s*["']([^"']*)["']/i.exec(tag);
      if (value) return value[1];
      value = /value\s*=\s*([^\s>]+)/i.exec(tag);
      if (value) return value[1];
    }
  }
  return null;
}

function require(condition, message) {
  const ok = check(null, { [message]: () => Boolean(condition) });
  if (!ok) {
    throw new Error(message);
  }
}

function csrfHeaders(state) {
  const headers = {};
  if (state.csrf) headers['X-CSRF-Token'] = state.csrf;
  return headers;
}

function mutationHeaders(state) {
  const headers = csrfHeaders(state);
  if (state.etag) headers['If-Match'] = state.etag;
  if (state.cartId) headers['Idempotency-Key'] = state.cartId;
  return headers;
}

function handleLoginResponse(res, state, jar) {
  const body = parseJson(res);
  if (body && body.csrf) state.csrf = body.csrf;
  if (body && body.grant_id !== undefined) state.grant = String(body.grant_id);

  const location = getHeader(res, 'Location');
  if (location) {
    const locUrl = location.startsWith('http')
      ? location
      : BASE_URL + (location.startsWith('/') ? location : '/' + location);
    const locRes = makeGet(locUrl, jar);
    const locBody = parseJson(locRes);
    if (locBody && locBody.csrf) state.csrf = locBody.csrf;
    if (locBody && locBody.grant_id !== undefined) state.grant = String(locBody.grant_id);
  }
}

function freshLogin(state, jar) {
  const formRes = makeGet(`${BASE_URL}/v2/login-form`, jar);
  require(formRes.status === 200, 'fresh login-form status');
  const formCsrf = extractFormCsrf(formRes.body);
  require(formCsrf, 'fresh login form csrf extracted');
  state.csrf = formCsrf;

  const loginRes = makePost(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: state.username, password: state.password, csrf: state.csrf }),
    csrfHeaders(state),
    jar
  );
  require(loginRes.status === 200 || loginRes.status === 302, 'fresh login status');
  handleLoginResponse(loginRes, state, jar);
  require(state.csrf, 'fresh login csrf after login');
}

function renewSession(state, jar) {
  const res = makePost(`${BASE_URL}/v2/session/renew`, '{}', csrfHeaders(state), jar);
  const body = parseJson(res);
  if (body && body.csrf) state.csrf = body.csrf;
  return res;
}

function recoverCart(state, jar) {
  if (!state.cartId) return null;
  const res = makePost(`${BASE_URL}/v2/carts/${state.cartId}/recover`, '{}', csrfHeaders(state), jar);
  const body = parseJson(res);
  if (body && body.csrf) state.csrf = body.csrf;
  const etag = getHeader(res, 'ETag');
  if (etag) state.etag = etag;
  return res;
}

function isExpiredOrSession(res) {
  if (!res || res.status !== 401) return false;
  const err = getError(res);
  return err === 'expired' || err === 'session';
}

function ensureNotDenied(res) {
  if (res && res.status === 401 && getError(res) === 'denied') {
    require(false, 'request not denied');
  }
}

function withRecovery(operation, state, jar) {
  let res = operation();
  if (isExpiredOrSession(res)) {
    const renewRes = renewSession(state, jar);
    if (isExpiredOrSession(renewRes)) {
      freshLogin(state, jar);
    }
    if (state.cartId) {
      recoverCart(state, jar);
    }
    res = operation();
  }
  ensureNotDenied(res);
  return res;
}

function findInStockProductFromBody(body) {
  if (!body) return null;
  let products = [];
  if (body.data && Array.isArray(body.data.products)) {
    products = body.data.products;
  } else if (body.data && body.data.product) {
    products = [body.data.product];
  } else if (body.products && Array.isArray(body.products)) {
    products = body.products;
  } else if (body.product) {
    products = [body.product];
  }

  for (const product of products) {
    if (!product || !product.id || !Array.isArray(product.variants)) continue;
    for (const variant of product.variants) {
      if (variant && variant.id && (variant.in_stock === true || variant.in_stock === 'true' || variant.in_stock === 1)) {
        return { productId: String(product.id), variantId: String(variant.id) };
      }
    }
  }
  return null;
}

function getNextUrl(body) {
  if (!body) return null;
  if (body.next) return body.next;
  if (body.data && body.data.next) return body.data.next;
  return null;
}

function findInStockProduct(jar) {
  let res = makeGet(`${BASE_URL}/v2/catalog`, jar);
  if (res.status === 200) {
    const body = parseJson(res);
    const product = findInStockProductFromBody(body);
    if (product) return product;
  }

  let next = '/v2/catalog/page';
  for (let i = 0; i < 3; i++) {
    const url = next.startsWith('http')
      ? next
      : BASE_URL + (next.startsWith('/') ? next : '/' + next);
    res = makeGet(url, jar);
    if (res.status !== 200) break;
    const body = parseJson(res);
    const product = findInStockProductFromBody(body);
    if (product) return product;
    next = getNextUrl(body);
    if (!next) break;
  }
  return null;
}

function createCart(state, jar, product) {
  const payload = {
    product_id: product.productId,
    variant_id: product.variantId,
  };
  if (state.grant) payload.grant_id = state.grant;
  return makePost(`${BASE_URL}/v2/carts`, JSON.stringify(payload), csrfHeaders(state), jar);
}

function patchCart(state, jar) {
  return makePatch(
    `${BASE_URL}/v2/carts/${state.cartId}`,
    JSON.stringify({ quantity: state.quantity }),
    mutationHeaders(state),
    jar
  );
}

function postOrder(state, jar) {
  return makePost(
    `${BASE_URL}/v2/orders`,
    JSON.stringify({ cart_id: state.cartId }),
    mutationHeaders(state),
    jar
  );
}

function getAccount() {
  const index = (__VU - 1) % ACCOUNTS.length;
  const row = ACCOUNTS[index];
  return {
    username: row.username,
    password: row.password || 'bench',
    quantity: Number(row.quantity),
  };
}

export default function () {
  const jar = http.cookiejar();
  const account = getAccount();
  const state = {
    username: account.username,
    password: account.password,
    quantity: account.quantity,
    csrf: null,
    cartId: null,
    etag: null,
    grant: null,
  };

  // Fresh login form and csrf
  const formRes = makeGet(`${BASE_URL}/v2/login-form`, jar);
  require(formRes.status === 200, 'login-form status 200');
  const formCsrf = extractFormCsrf(formRes.body);
  require(formCsrf, 'login form csrf extracted');
  state.csrf = formCsrf;

  // Login
  const loginRes = makePost(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username: state.username, password: state.password, csrf: state.csrf }),
    csrfHeaders(state),
    jar
  );
  require(loginRes.status === 200 || loginRes.status === 302, 'login status');
  handleLoginResponse(loginRes, state, jar);
  require(state.csrf, 'csrf after login');

  // Catalog product selection
  const product = findInStockProduct(jar);
  require(product, 'in-stock product found');

  // Create one cart
  let cartRes = withRecovery(() => createCart(state, jar, product), state, jar);
  require(cartRes.status === 201, 'cart creation status 201');
  const cartBody = parseJson(cartRes);
  require(cartBody && cartBody.id, 'cart id present');
  state.cartId = String(cartBody.id);
  if (cartBody.csrf) state.csrf = cartBody.csrf;
  const cartEtag = getHeader(cartRes, 'ETag');
  if (cartEtag) state.etag = cartEtag;

  // Patch cart quantity
  let patchRes = withRecovery(() => patchCart(state, jar), state, jar);
  if (patchRes.status === 412) {
    const readRes = makeGet(`${BASE_URL}/v2/carts/${state.cartId}`, jar);
    require(readRes.status === 200, 'cart read status 200');
    const readEtag = getHeader(readRes, 'ETag');
    if (readEtag) state.etag = readEtag;
    patchRes = withRecovery(() => patchCart(state, jar), state, jar);
  }
  require(patchRes.status === 200 || patchRes.status === 201, 'patch cart status');
  const patchBody = parseJson(patchRes);
  if (patchBody && patchBody.csrf) state.csrf = patchBody.csrf;
  const patchEtag = getHeader(patchRes, 'ETag');
  if (patchEtag) state.etag = patchEtag;

  // Commit exactly one order
  const orderRes = withRecovery(() => postOrder(state, jar), state, jar);
  require(orderRes.status === 201, 'order status 201');
  const orderBody = parseJson(orderRes);
  require(orderBody && orderBody.accepted === true, 'order accepted true');
}

