import java.time.Duration;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    HttpProtocolBuilder httpProtocol = http
        .baseUrl(System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000"))
        .disableFollowRedirect()
        .acceptHeader("application/json")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{etag}")
        .header("Idempotency-Key", "#{cart}")
        .disableCaching();

    ChainBuilder resetSession = exec(session -> {
        Session s = session;
        s = s.set("csrf", "MISSING");
        s = s.set("cart", "MISSING");
        s = s.set("etag", "MISSING");
        s = s.set("hasCart", false);
        s = s.set("grant", "MISSING");
        s = s.set("product", "MISSING");
        s = s.set("variant", "MISSING");
        s = s.set("quantity", "2");
        s = s.set("username", "bench-" + session.userId());
        s = s.remove("location");
        return s;
    });

    ChainBuilder loginForm = exec(
        http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(
                status().is(200),
                regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                    .find(1)
                    .saveAs("form"),
                header("ETag").optional().saveAs("etag")
            )
    );

    ChainBuilder login = exec(
        http("POST /v2/login")
            .post("/v2/login")
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
            .check(
                status().is(200).or(status().is(302)),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                header("Location").optional().saveAs("location"),
                header("ETag").optional().saveAs("etag")
            )
    );

    ChainBuilder followRedirect = exec(
        http("GET login redirect")
            .get(session -> session.getString("location"))
            .check(
                status().is(200),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.grant_id").optional().saveAs("grant"),
                header("ETag").optional().saveAs("etag")
            )
    );

    ChainBuilder catalog = exec(
        http("GET /v2/catalog")
            .get("/v2/catalog")
            .check(
                status().is(200),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                    .find(1).saveAs("product"),
                jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                    .find(1).saveAs("variant"),
                header("ETag").optional().saveAs("etag")
            )
    );

    ChainBuilder createCart = exec(
        http("POST /v2/carts")
            .post("/v2/carts")
            .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"))
            .check(
