import http from 'k6/http';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    journey: {
      executor: 'constant-arrival-rate',
      rate: 2.02,
      timeUnit: '1s',
      duration: '38s',
      preAllocatedVUs: 2,
      maxVUs: 4,
    },
  },
};

function safeJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractCsrfFromHtml(html) {
  if (!html) return null;
  let m;
  m = html.match(/<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  if (m) return m[1];
  m = html.match(/<input[^>]*name=["']csrf["'][^>]*value=["']([^"']+)["']/i);
  if (m) return m[1];
  m = html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']csrf["'][^>]*>/i);
  return m ? m[1] : null;
}

function extractChallengeValue(html) {
  if (!html) return null;
  let m;
  m = html.match(/<input(?=[^>]*\bname=["']challenge["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i);
  if (m) return m[1];
  m = html.match(/<input[^>]*name=["']challenge["'][^>]*value=["']([^"']+)["']/i);
  if (m) return m[1];
  m = html.match(/<input[^>]*value=["']([^"']+)["'][^>]*name=["']challenge["'][^>]*>/i);
  return m ? m[1] : null;
}

function extractActionFromHtml(html) {
  const m = html.match(/<form[^>]*action=["']([^"']+)["'][^>]*>/i);
  return m ? m[1] : null;
}

function resolveUrl(base, path) {
  if (!path) return base;
  if (path.indexOf('http://') === 0 || path.indexOf('https://') === 0) return path;
  if (path.charAt(0) === '/') return base + path;
  return base + '/' + path;
}

function makeHeaders(csrf, extra) {
  const headers = { 'Content-Type': 'application/json' };
  if (csrf) headers['X-CSRF-Token'] = csrf;
  if (extra) {
    if (extra.etag) headers['If-Match'] = extra.etag;
    if (extra.idempotencyKey) headers['Idempotency-Key'] = extra.idempotencyKey;
  }
  return headers;
}

function getLocation(res) {
  return (res && res.headers && (res.headers.Location || res.headers['location'])) || null;
}

function getETag(res) {
  return (res && res.headers && (res.headers.ETag || res.headers['etag'] || res.headers.Etag)) || null;
}

function runJourney() {
  const username = `bench-${__VU}`;
  let csrf = '';
  let grant = null;
  let product = null;
  let variant = null;
  let cartId = null;
  let etag = null;

  // 1. Login form
  let res = http.get(`${BASE_URL}/v2/login-form`, {
    redirects: 0,
    headers: makeHeaders(csrf),
  });
  let formCsrf = extractCsrfFromHtml(res.body);
  if (!formCsrf) {
    const json = safeJson(res);
    if (json && json.csrf) formCsrf = json.csrf;
    else throw new Error('login form csrf missing');
  }

  // 2. Login
  res = http.post(`${BASE_URL}/v2/login`, JSON.stringify({ username, password: 'bench', csrf: formCsrf }), {
    redirects: 0,
    headers: makeHeaders(csrf),
  });
  let json = safeJson(res);
  if (json && json.csrf) csrf = json.csrf;
  if (json && json.grant_id) grant = json.grant_id;

  // Handle login redirect exactly once
  if (res.status >= 300 && res.status < 400) {
    const location = getLocation(res);
    if (location) {
      res = http.get(resolveUrl(BASE_URL, location), {
        redirects: 0,
        headers: makeHeaders(csrf),
      });
      json = safeJson(res);
      if (json) {
        if (json.csrf) csrf = json.csrf;
        if (json.grant_id) grant = json.grant_id;
      }

      // Solve challenge form if present
      const action = extractActionFromHtml(res.body);
      if (action && res.body.indexOf('challenge') !== -1) {
        const challengeValue = extractChallengeValue(res.body);
        if (challengeValue) {
          res = http.post(resolveUrl(BASE_URL, action), JSON.stringify({ challenge: challengeValue }), {
            redirects: 0,
            headers: makeHeaders(csrf),
          });
          json = safeJson(res);
          if (json && json.csrf) csrf = json.csrf;
          if (json && json.grant_id) grant = json.grant_id;

          if (res.status >= 300 && res.status < 400) {
            const loc2 = getLocation(res);
            if (loc2) {
              res = http.get(resolveUrl(BASE_URL, loc2), {
                redirects: 0,
                headers: makeHeaders(csrf),
              });
              json = safeJson(res);
              if (json && json.csrf) csrf = json.csrf;
              if (json && json.grant_id) grant = json.grant_id;
            }
          }
        }
      }
    }
  }

  if (!csrf) {
    const json2 = safeJson(res);
    if (json2 && json2.csrf) csrf = json2.csrf;
    if (!csrf) throw new Error('login csrf missing');
  }

  // 3. Catalog
  res = http.get(`${BASE_URL}/v2/catalog`, {
    redirects: 0,
    headers: makeHeaders(csrf),
  });
  json = safeJson(res);
  if (json && json.csrf) csrf = json.csrf;

  const products = (json && json.data && json.data.products) ? json.data.products : [];
  if (products.length) {
    for (const prod of products) {
      if (prod && prod.variants && Array.isArray(prod.variants)) {
        const v = prod.variants.find((v) => v && v.in_stock === true);
        if (v) {
          product = prod.id;
          variant = v.id;
          break;
        }
      }
    }
  }

