import os
import re
import time

from locust import HttpUser, task, LoadTestShape, StopUser


TARGET_RATE = 5.0
TARGET_USERS = 2


def extract_csrf_from_html(html):
    if not html:
        return None
    for tag in re.findall(r"<input\b[^>]*>", html, re.I):
        if re.search(r"\bname\s*=\s*['\"]csrf['\"]", tag, re.I):
            m = re.search(r"\bvalue\s*=\s*['\"]([^'\"]*)['\"]", tag, re.I)
            if m:
                return m.group(1)
    return None


class JourneyShape(LoadTestShape):
    def tick(self):
        global TARGET_RATE, TARGET_USERS
        run_time = self.get_run_time()

        if run_time < 5:
            TARGET_RATE = 5.0
            TARGET_USERS = 2
            return (TARGET_USERS, 4)
        elif run_time < 15:
            TARGET_RATE = 5.0
            TARGET_USERS = 2
            return (TARGET_USERS, 4)
        elif run_time < 25:
            TARGET_RATE = 15.0
            TARGET_USERS = 4
            return (TARGET_USERS, 4)
        elif run_time < 35:
            TARGET_RATE = 5.0
            TARGET_USERS = 2
            return (TARGET_USERS, 4)
        elif run_time < 40:
            TARGET_RATE = 0.0
            TARGET_USERS = 0
            return (0, 4)

        return None


class ShopUser(HttpUser):
    _seq = 0

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.account_id = (ShopUser._seq % 4) + 1
        ShopUser._seq += 1
        self.username = f"bench-{self.account_id}"

        self.csrf = "MISSING"
        self.grant_id = "MISSING"
        self.product = None
        self.variant = None
        self.cart_id = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.committed = False
        self.iteration = 0
        self.last_task_start = None

    def on_start(self):
        if TARGET_RATE <= 0:
            return
        try:
            n = self.environment.runner.user_count or max(1, TARGET_USERS)
        except Exception:
            n = max(1, TARGET_USERS)
        n = max(1, n)
        interval = n / TARGET_RATE
        offset = ((self.account_id - 1) % n) * (interval / n)
        time.sleep(max(0.0, offset))

    def wait_time(self):
        if TARGET_RATE <= 0:
            return 60.0
        if self.last_task_start is None:
            return 0.0

        try:
            n = self.environment.runner.user_count
        except Exception:
            n = TARGET_USERS
        if not n or n < 1:
            n = TARGET_USERS
        n = max(1, n)

        interval = n / TARGET_RATE
        return max(0.0, self.last_task_start + interval - time.monotonic())

    def _base_headers(self):
        headers = {"Content-Type": "application/json"}
        if self.csrf and self.csrf != "MISSING":
            headers["X-CSRF-Token"] = self.csrf
        if getattr(self, "etag", "MISSING") != "MISSING":
            headers["If-Match"] = self.etag
        return headers

    def _error_type(self, text):
        m = re.search(r'"error"\s*:\s*"(expired|session|denied)"', text or "", re.I)
        return m.group(1).lower() if m else None

    def _login(self):
        with self.client.get(
            "/v2/login-form",
            headers=self._base_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"login-form status {r.status_code}")
                return False
            form_csrf = extract_csrf_from_html(r.text)
            if not form_csrf:
                r.failure("login-form csrf not found")
                return False

        login_csrf = self.csrf if self.csrf != "MISSING" else form_csrf
        login_headers = {
            "Content-Type": "application/json",
            "X-CSRF-Token": login_csrf,
        }
        payload = {
            "username": self.username,
            "password": "bench",
            "csrf": form_csrf,
        }

        data = None
        location = None

        with self.client.post(
            "/v2/login",
            json=payload,
            headers=login_headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 302 and r.headers.get("Location"):
                r.success()
                location = r.headers.get("Location")
            elif r.status_code == 200:
                try:
                    data = r.json()
                    if "csrf" not in data:
                        r.failure("login response missing csrf")
                        return False
                    r.success()
                except Exception as e:
                    r.failure(f"login response json invalid: {e}")
                    return False
            else:
                if r.status_code == 401 and self._error_type(r.text) == "denied":
                    r.failure("login denied")
                else:
                    r.failure(f"login status {r.status_code}: {r.text[:200]}")
                return False

        if location:
            loc = location
            if not loc.startswith("http"):
                loc = loc if loc.startswith("/") else "/" + loc

            with self.client.get(
                loc,
                headers=self._base_headers(),
                catch_response=True,
                allow_redirects=False,
            ) as rr:
                if rr.status_code != 200:
                    rr.failure(f"login redirect status {rr.status_code}")
                    return False
                try:
                    data = rr.json()
                    if "csrf" not in data:
                        rr.failure("login redirect missing csrf")
                        return False
                    rr.success()
                except Exception as e:
                    rr.failure(f"login redirect json invalid: {e}")
                    return False

        if not isinstance(data, dict):
            return False

        self.csrf = data.get("csrf", self.csrf)
        self.grant_id = data.get("grant_id", "MISSING") or "MISSING"
        return True

    def _recover_cart(self):
