            headers.update(extra_headers)

        auth_error = None

        with self.client.post(
            path,
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code == 401 and self._error_type(r.text) in ("expired", "session"):
                auth_error = self._error_type(r.text)
                r.success()
            elif r.status_code == 401:
                r.failure(f"denied 401 on {path}: {r.text[:200]}")
                return False
            else:
                return validate(r)

        if auth_error == "expired":
            if not self._renew_session():
                return False
        elif auth_error == "session":
            if not self._fresh_login():
                return False
        else:
            return False

        headers = self._auth_headers()
        if extra_headers:
            headers.update(extra_headers)

        with self.client.post(
            path,
            json=payload,
            headers=headers,
            catch_response=True,
            allow_redirects=False,
        ) as r:
            return validate(r)

    # ----------------- journey steps -----------------

    def _catalog(self):
        with self.client.get(
            "/v2/catalog",
            headers=self._auth_headers(),
            catch_response=True,
            allow_redirects=False,
        ) as r:
            if r.status_code != 200:
                r.failure(f"catalog status {r.status_code}")
                return False

            try:
                data = r.json()
            except Exception as exc:
                r.failure(f"catalog json invalid: {exc}")
                return False

            self.csrf = data.get("csrf", self.csrf)

            products = data.get("data", {}).get("products", [])
            product = None
            variant = None

            for p in products:
                for v in p.get("variants", []):
                    if v.get("in_stock") is True:
                        product = p.get("id")
                        variant = v.get("id")
                        break
                if product is not None:
                    break

            if product is None or variant is None:
                r.failure("no in-stock product in catalog")
                return False

            self.product = str(product)
            self.variant = str(variant)
            r.success()
            return True

    def _create_cart(self):
        payload = {
            "product_id": self.product,
            "variant_id": self.variant,
        }
        if self.grant_id and self.grant_id != "MISSING":
            payload["grant_id"] = self.grant_id

        def validate(resp):
            if resp.status_code != 201:
                resp.failure(f"cart create status {resp.status_code}: {resp.text[:200]}")
                return False

            try:
                data = resp.json()
            except Exception as exc:
                resp.failure(f"cart create json invalid: {exc}")
                return False

            cart_id = data.get("id")
            if not cart_id:
                resp.failure("cart create missing id")
                return False

            self.cart_id = str(cart_id)
            self.has_cart = True
            self.csrf = data.get("csrf", self.csrf)
            self.etag = resp.headers.get("ETag", self.etag)
            return True

        return self._post_authenticated("/v2/carts", payload, validate)

    def _checkout(self):
        if not self.cart_id or self.cart_id == "MISSING":
            return False

        payload = {"cart_id": self.cart_id}
        extra_headers = {"Idempotency-Key": self.cart_id}
        if self.etag and self.etag != "MISSING":
            extra_headers["If-Match"] = self.etag

        def validate(resp):
            if resp.status_code not in (200, 201):
                resp.failure(f"order status {resp.status_code}: {resp.text[:200]}")
                return False

            try:
                data = resp.json()
            except Exception as exc:
                resp.failure(f"order json invalid: {exc}")
                return False

            if data.get("accepted") is not True:
                resp.failure("order accepted false")
                return False

            self.csrf = data.get("csrf", self.csrf)
            self.committed = True
            resp.success()
            return True

        return self._post_authenticated(
            "/v2/orders",
            payload,
            validate,
            extra_headers=extra_headers,
        )

    def _journey_impl(self):
        # Every journey starts a fresh login and a fresh cart.
        self.grant_id = "MISSING"
        self.product = None
        self.variant = None
        self.cart_id = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.committed = False

        if not self._login():
            return False
        if not self._catalog():
            return False
        if not self._create_cart():
            return False
        if not self._checkout():
            return False
        return True

    @task
    def journey(self):
        self.last_task_start = time.monotonic()

        self._journey_impl()

        self.iteration += 1
        if self.max_iterations and self.iteration >= self.max_iterations:
            raise StopUser()
