import io.gatling.javaapi.http.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final String CSRF_INPUT_REGEX =
        "<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>";

    private static final String CSRF_RESPONSE_REGEX = "\"csrf\"\\s*:";
    private static final String CART_ID_RESPONSE_REGEX = "\"id\"\\s*:\\s*\"cart-";
    private static final String ACCEPTED_RESPONSE_REGEX = "\"accepted\"\\s*:\\s*true";

    private static final HttpProtocolBuilder httpProtocol =
        http.baseUrl(System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000"))
            .contentTypeHeader("application/json")
            .header("X-CSRF-Token", session -> session.getString("csrf"))
            .header("If-Match", session -> session.getString("etag"))
            .header("Idempotency-Key", session -> session.getString("cart"))
            .followRedirect(false)
            .disableAutoReferer()
            .disableCaching()
            .shareConnections();

    private static String cartBody(Session session) {
        String product = session.getString("product");
        String variant = session.getString("variant");
        String grant = session.getString("grant");
        StringBuilder sb = new StringBuilder("{\"product_id\":\"");
        sb.append(product).append("\",\"variant_id\":\"").append(variant).append("\"");
        if (grant != null && !"MISSING".equals(grant)) {
            sb.append(",\"grant_id\":\"").append(grant).append("\"");
        }
        sb.append("}");
        return sb.toString();
    }

    private static final ChainBuilder LOGIN_FORM =
        exec(http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(regex(CSRF_INPUT_REGEX).optional().saveAs("form")));

    private static final ChainBuilder LOGIN =
        exec(http("POST /v2/login")
            .post("/v2/login")
            .body(StringBody(session -> {
                String username = "bench-" + session.userId();
                String form = session.getString("form");
                return "{\"username\":\"" + username + "\",\"password\":\"bench\",\"csrf\":\"" + form + "\"}";
            }))
            .check(regex(CSRF_RESPONSE_REGEX).exists())
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(header("Location").optional().saveAs("location")));

    private static final ChainBuilder REDIRECT =
        exec(http("GET redirect")
            .get(session -> session.getString("location"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(jsonPath("$.grant_id").optional().saveAs("grant")));

    private static final ChainBuilder CATALOG =
        exec(http("GET /v2/catalog")
            .get("/v2/catalog")
            .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find(0).optional().saveAs("product"))
            .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find(0).optional().saveAs("variant")));

    private static final ChainBuilder CREATE_CART =
        exec(http("POST /v2/carts")
            .post("/v2/carts")
            .body(StringBody(ModelSimulation::cartBody))
            .check(regex(CART_ID_RESPONSE_REGEX).exists())
            .check(jsonPath("$.id").optional().saveAs("cart"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf")));

    private static final ChainBuilder CREATE_ORDER =
        exec(http("POST /v2/orders")
            .post("/v2/orders")
            .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
            .check(regex(ACCEPTED_RESPONSE_REGEX).exists())
            .check(jsonPath("$.csrf").optional().saveAs("csrf")));

    private static final ChainBuilder JOURNEY =
        exec(clearCookies)
            .exec(session -> session.set("csrf", "MISSING")
                .set("cart", "MISSING")
                .set("etag", "MISSING")
                .set("grant", "MISSING")
                .set("product", "MISSING")
                .set("variant", "MISSING")
                .set("form", "MISSING"))
            .exec(LOGIN_FORM)
            .exec(LOGIN)
            .doIf(session -> session.contains("location")).then(REDIRECT)
            .exec(CATALOG)
            .exec(CREATE_CART)
            .exec(CREATE_ORDER);

    {
        setUp(scenario("ModelScenario")
                .repeat(2, "journey").on(JOURNEY)
                .injectOpen(atOnceUsers(2)))
            .protocols(httpProtocol);
    }
}
