    checks: ['rate>0.75'],
  },
};

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';

function makeHeaders(csrf, extra = {}) {
  const h = { 'Content-Type': 'application/json' };
  if (csrf && csrf !== 'MISSING') {
    h['X-CSRF-Token'] = csrf;
  }
  return Object.assign(h, extra);
}

function parseJson(body) {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function extractLoginCsrf(body) {
  const re = /<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>/i;
  const m = body.match(re);
  return m ? m[1] : null;
}

function getLocation(res) {
  return res.headers['Location'] || res.headers['location'];
}

function buildUrl(location) {
  if (/^https?:\/\//i.test(location)) {
    return location;
  }
  return `${BASE_URL}${location.startsWith('/') ? location : '/' + location}`;
}

export default function () {
  http.cookieJar().clear(BASE_URL);

  const vu = __VU;
  const username = `bench-${vu}`;
  let csrf = '';
  let grant = null;
  let cartId = null;
  let etag = null;

  // 1. login form
  const loginFormRes = http.get(`${BASE_URL}/v2/login-form`, {
    headers: { 'Content-Type': 'application/json' },
  });
  const formCsrf = extractLoginCsrf(loginFormRes.body);
  check(loginFormRes, {
    'login form contains csrf': (r) => r.status === 200 && !!formCsrf,
  });
  csrf = formCsrf || csrf;

  // 2. login
  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password, csrf }),
    { headers: makeHeaders(csrf) }
  );
  const loginJson = parseJson(loginRes.body);
  check(loginRes, {
    'login response has csrf': (r) => r.status === 200 && /"csrf"\s*:/.test(r.body),
  });

  if (loginRes.status === 200 && loginJson) {
    if (loginJson.csrf) csrf = loginJson.csrf;
  }

  // 3. manual redirect once
  const location = getLocation(loginRes);
  if (location) {
    const locRes = http.get(buildUrl(location), { headers: makeHeaders(csrf) });
    check(locRes, {
      'login redirect status 200': (r) => r.status === 200,
    });
    const locJson = parseJson(locRes.body);
    if (locJson) {
      if (locJson.csrf) csrf = locJson.csrf;
      if (locJson.grant_id) grant = locJson.grant_id;
    }
  }

  // 4. catalog
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, { headers: makeHeaders(csrf) });
  const catalogJson = parseJson(catalogRes.body);
  check(catalogRes, {
    'catalog status 200': (r) => r.status === 200,
  });

  let productId = null;
  let variantId = null;
  if (catalogJson && catalogJson.data && Array.isArray(catalogJson.data.products)) {
    for (const product of catalogJson.data.products) {
      if (
        product.variants &&
        product.variants.length > 0 &&
        product.variants[0].in_stock === true
      ) {
        productId = product.id;
        variantId = product.variants[0].id;
        break;
      }
    }
  }

  check({ productId, variantId }, {
    'in-stock product selected': (o) =>
      o.productId !== null &&
      o.productId !== undefined &&
      o.variantId !== null &&
      o.variantId !== undefined,
  });

  // 5. create cart
  const cartBody = { product_id: productId, variant_id: variantId };
  if (grant) cartBody.grant_id = grant;

  const cartRes = http.post(
    `${BASE_URL}/v2/carts`,
    JSON.stringify(cartBody),
    { headers: makeHeaders(csrf) }
