  });

  if (cartRes.headers['etag']) etag = cartRes.headers['etag'];
  if (cartJson) {
    if (cartJson.csrf) csrf = cartJson.csrf;
    if (cartJson.id) cartId = cartJson.id;
  }

  // 6. create order
  const orderHeaders = makeHeaders(csrf, { 'Idempotency-Key': cartId });
  if (etag) orderHeaders['If-Match'] = etag;

  const orderRes = http.post(
    `${BASE_URL}/v2/orders`,
    JSON.stringify({ cart_id: cartId }),
    { headers: orderHeaders }
  );
  const orderJson = parseJson(orderRes.body);
  check(orderRes, {
    'order accepted': (r) => r.status === 201 && /"accepted"\s*:\s*true/.test(r.body),
  });

  if (orderJson && orderJson.csrf) csrf = orderJson.csrf;
}
